// Men's Social — Step 9: first batch of Kayani Herbs Instagram content in Discover (English + Kiswahili).
// Also includes Steps 6, 7 and 8 (Man feed, three tabs, Social with Discover + Community).
// Run from the project folder:  node setup-step-9.mjs
import { mkdirSync, writeFileSync, existsSync, rmSync } from "node:fs";
import { dirname } from "node:path";

if (!existsSync("package.json") || !existsSync("src/components/progress/SleepCard.tsx")) {
  console.error("Run this inside the Men-s-Social-True folder, after Step 5 is set up.");
  process.exit(1);
}

const remove = [
  "src/app/(app)/home",
  "src/app/(app)/profile",
  "src/app/(app)/progress",
  ".next"
];
for (const path of remove) {
  if (existsSync(path)) {
    rmSync(path, { recursive: true, force: true });
    console.log("  removed", path);
  }
}

const files = {
  "next.config.ts": "import type { NextConfig } from \"next\";\n\nconst nextConfig: NextConfig = {\n  // Old addresses from before the 3-tab layout still work\n  async redirects() {\n    return [\n      { source: \"/home\", destination: \"/man\", permanent: false },\n      { source: \"/progress\", destination: \"/man\", permanent: false },\n      { source: \"/profile\", destination: \"/me\", permanent: false },\n    ];\n  },\n};\n\nexport default nextConfig;\n",
  "src/app/(app)/learn/[id]/page.tsx": "\"use client\";\n\nimport { useParams } from \"next/navigation\";\nimport ContentDetail from \"@/components/social/ContentDetail\";\n\n// Daily lessons opened from the Man tab use the same content page as Discover.\nexport default function LessonPage() {\n  const { id } = useParams<{ id: string }>();\n  return <ContentDetail id={id} back={{ href: \"/man\", label: \"Man\" }} />;\n}\n",
  "src/app/(app)/learn/page.tsx": "\"use client\";\n\nimport Link from \"next/link\";\nimport { ArrowLeft, BookOpen, Check } from \"lucide-react\";\nimport { LESSONS } from \"@/lib/feed/catalog\";\nimport { useFeed } from \"@/lib/feed/store\";\n\nexport default function LearnPage() {\n  const feed = useFeed();\n  return (\n    <div className=\"stagger space-y-4\">\n      <Link href=\"/man\" className=\"flex items-center gap-1 text-sm text-ink-soft\">\n        <ArrowLeft size={16} /> Man\n      </Link>\n      <h1 className=\"text-2xl font-bold\">Lessons</h1>\n      {LESSONS.map((l) => (\n        <Link key={l.id} href={`/learn/${l.id}`} className=\"block rounded-3xl bg-surface p-5 ring-1 ring-line\">\n          <p className=\"flex items-center gap-1.5 text-xs text-ink-soft\">\n            <BookOpen size={13} /> {l.minutes} min · {l.topic}\n            {feed.lessons[l.id] && (\n              <span className=\"ml-auto flex items-center gap-1 font-semibold text-forest\">\n                <Check size={12} /> Read\n              </span>\n            )}\n          </p>\n          <p className=\"mt-1 font-semibold\">{l.title}</p>\n          <p className=\"mt-1 text-sm text-ink-soft\">{l.summary}</p>\n        </Link>\n      ))}\n    </div>\n  );\n}\n",
  "src/app/(app)/man/page.tsx": "\"use client\";\n\n// \"Man\": Home and Progress in one place.\n// Top: what to do today (all interactive right here). Bottom: his trends.\n\nimport TopBar from \"@/components/feed/TopBar\";\nimport ActivitiesCard from \"@/components/feed/ActivitiesCard\";\nimport TrendsSection from \"@/components/feed/TrendsSection\";\nimport { EndCard, LessonCard, ReminderCard, TipCard, TodayCard } from \"@/components/feed/FeedCards\";\nimport { useHomeFeed } from \"@/components/feed/useHomeFeed\";\nimport CheckInCard from \"@/components/progress/CheckInCard\";\nimport HydrationCard from \"@/components/progress/HydrationCard\";\nimport SleepCard from \"@/components/progress/SleepCard\";\n\nexport default function ManPage() {\n  const f = useHomeFeed();\n\n  if (!f.ready) {\n    return (\n      <div className=\"space-y-4\">\n        <TopBar />\n        <div className=\"h-40 animate-pulse rounded-3xl bg-forest-deep/20\" />\n        <div className=\"h-64 animate-pulse rounded-3xl bg-surface ring-1 ring-line\" />\n      </div>\n    );\n  }\n\n  return (\n    <div className=\"stagger space-y-4\">\n      <TopBar />\n      <TodayCard f={f} />\n      {f.allClosed ? <EndCard /> : <ReminderCard f={f} />}\n\n      <div id=\"checkin\" className=\"scroll-mt-4\">\n        <CheckInCard period={1} />\n      </div>\n      <div id=\"sleep\" className=\"scroll-mt-4\">\n        <SleepCard period={1} />\n      </div>\n      <div id=\"water\" className=\"scroll-mt-4\">\n        <HydrationCard period={1} />\n      </div>\n      <ActivitiesCard f={f} />\n\n      <LessonCard f={f} />\n      <TipCard f={f} />\n\n      <div className=\"pt-4\">\n        <TrendsSection />\n      </div>\n\n      <p className=\"px-2 pt-2 text-center text-[11px] text-ink-soft\">\n        Saved on this phone for now. Your records move to your account when you sign up.\n      </p>\n    </div>\n  );\n}\n",
  "src/app/(app)/me/page.tsx": "import ComingSoon from \"@/components/ComingSoon\";\n\nexport default function MePage() {\n  return <ComingSoon title=\"Me\" text=\"Your account, reminders, privacy and discreet mode will appear here.\" />;\n}\n",
  "src/app/(app)/social/c/[id]/page.tsx": "\"use client\";\n\nimport { useParams } from \"next/navigation\";\nimport ContentDetail from \"@/components/social/ContentDetail\";\n\nexport default function SocialContentPage() {\n  const { id } = useParams<{ id: string }>();\n  return <ContentDetail id={id} back={{ href: \"/social\", label: \"Discover\" }} />;\n}\n",
  "src/app/(app)/social/error.tsx": "\"use client\";\n\n// Shown if anything on the Social pages fails to load, instead of a blank screen.\nexport default function SocialError({ reset }: { error: Error; reset: () => void }) {\n  return (\n    <div className=\"rounded-3xl bg-surface p-8 text-center ring-1 ring-line\" role=\"alert\">\n      <p className=\"font-semibold\">Something went wrong</p>\n      <p className=\"mt-1 text-sm text-ink-soft\">This page couldn&apos;t load. Your saved items are safe.</p>\n      <button onClick={reset} className=\"mt-4 rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white\">\n        Try again\n      </button>\n    </div>\n  );\n}\n",
  "src/app/(app)/social/page.tsx": "\"use client\";\n\nimport { Suspense, useState } from \"react\";\nimport Link from \"next/link\";\nimport { usePathname, useRouter, useSearchParams } from \"next/navigation\";\nimport { Bookmark, Search } from \"lucide-react\";\nimport Discover, { DiscoverSkeleton } from \"@/components/social/Discover\";\nimport Community from \"@/components/social/Community\";\nimport SearchPanel from \"@/components/social/SearchPanel\";\n\ntype Tab = \"discover\" | \"community\";\n\nfunction SocialInner() {\n  const router = useRouter();\n  const pathname = usePathname();\n  const params = useSearchParams();\n  const tab: Tab = params.get(\"tab\") === \"community\" ? \"community\" : \"discover\";\n  const [searching, setSearching] = useState(false);\n\n  // Switching tabs keeps him on /social; the tab is remembered in the address for Back\n  const setTab = (t: Tab) => router.replace(t === \"discover\" ? pathname : `${pathname}?tab=${t}`, { scroll: false });\n\n  return (\n    <div className=\"space-y-5\">\n      <header className=\"flex items-center justify-between\">\n        <h1 className=\"text-[28px] font-bold leading-none\">Social</h1>\n        <div className=\"flex gap-2\">\n          <button\n            aria-label=\"Search\"\n            aria-pressed={searching}\n            onClick={() => setSearching((s) => !s)}\n            className=\"flex h-10 w-10 items-center justify-center rounded-full bg-surface ring-1 ring-line transition-transform active:scale-95\"\n          >\n            <Search size={18} />\n          </button>\n          <Link\n            href=\"/social/saved\"\n            aria-label=\"Saved\"\n            className=\"flex h-10 w-10 items-center justify-center rounded-full bg-surface ring-1 ring-line transition-transform active:scale-95\"\n          >\n            <Bookmark size={18} />\n          </Link>\n        </div>\n      </header>\n\n      <div className=\"inline-flex rounded-full bg-surface p-1 ring-1 ring-line\" role=\"tablist\" aria-label=\"Social sections\">\n        {([\"discover\", \"community\"] as const).map((t) => (\n          <button\n            key={t}\n            role=\"tab\"\n            id={`tab-${t}`}\n            aria-selected={tab === t}\n            aria-controls=\"social-panel\"\n            onClick={() => setTab(t)}\n            className={`rounded-full px-5 py-2 text-sm font-semibold transition-colors ${\n              tab === t ? \"bg-forest-deep text-white\" : \"text-ink-soft\"\n            }`}\n          >\n            {t === \"discover\" ? \"Discover\" : \"Community\"}\n          </button>\n        ))}\n      </div>\n\n      <div id=\"social-panel\" role=\"tabpanel\" aria-labelledby={`tab-${tab}`} key={`${tab}-${searching}`} className=\"page-enter\">\n        {searching ? (\n          <SearchPanel tab={tab} onClose={() => setSearching(false)} />\n        ) : tab === \"discover\" ? (\n          <Discover />\n        ) : (\n          <Community />\n        )}\n      </div>\n    </div>\n  );\n}\n\nexport default function SocialPage() {\n  return (\n    <Suspense fallback={<DiscoverSkeleton />}>\n      <SocialInner />\n    </Suspense>\n  );\n}\n",
  "src/app/(app)/social/post/[id]/page.tsx": "\"use client\";\n\nimport { useState } from \"react\";\nimport Link from \"next/link\";\nimport { useParams, useRouter } from \"next/navigation\";\nimport { ArrowLeft, Flag, Lock, Stethoscope, Trash2 } from \"lucide-react\";\nimport { AuthorLine } from \"@/components/social/PostCard\";\nimport ReactionBar from \"@/components/social/ReactionBar\";\nimport ReportSheet from \"@/components/social/ReportSheet\";\nimport { useCommunity } from \"@/components/social/useCommunity\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { checkReply, LIMITS, topicLabel } from \"@/lib/social/community\";\nimport { socialStore } from \"@/lib/social/store\";\n\nexport default function PostPage() {\n  const { id } = useParams<{ id: string }>();\n  const router = useRouter();\n  const showToast = useToast();\n  const c = useCommunity();\n  const [reply, setReply] = useState(\"\");\n  const [anonymous, setAnonymous] = useState(true);\n  const [error, setError] = useState(\"\");\n  const [reporting, setReporting] = useState<string | null>(null);\n\n  const back = (\n    <Link href=\"/social?tab=community\" className=\"flex items-center gap-1 text-sm text-ink-soft\">\n      <ArrowLeft size={16} /> Community\n    </Link>\n  );\n\n  if (!c.ready) {\n    return (\n      <div className=\"space-y-4\" aria-busy=\"true\">\n        {back}\n        <div className=\"h-48 animate-pulse rounded-3xl bg-surface ring-1 ring-line\" />\n      </div>\n    );\n  }\n\n  const post = c.getPost(id);\n  if (!post) {\n    return (\n      <div className=\"space-y-4\">\n        {back}\n        <div className=\"rounded-3xl bg-surface p-8 text-center ring-1 ring-line\">\n          <p className=\"font-semibold\">{c.isReported(id) ? \"You reported this post\" : \"This conversation isn't available\"}</p>\n          <p className=\"mt-1 text-sm text-ink-soft\">\n            {c.isReported(id) ? \"It's hidden for you and sent to our moderators.\" : \"It may have been removed.\"}\n          </p>\n          {c.isReported(id) && (\n            <button\n              onClick={() => socialStore.undoReport(id)}\n              className=\"mt-4 rounded-full px-5 py-2.5 text-sm font-semibold ring-1 ring-line\"\n            >\n              Undo report\n            </button>\n          )}\n        </div>\n      </div>\n    );\n  }\n\n  const replies = c.repliesFor(post.id);\n\n  function send() {\n    const problem = checkReply(reply);\n    if (problem) return setError(problem);\n    socialStore.addReply(post!.id, reply, anonymous || !c.nickname);\n    setReply(\"\");\n    showToast(\"Reply posted\");\n  }\n\n  return (\n    <div className=\"space-y-4\">\n      {back}\n\n      <article className=\"rounded-3xl bg-surface p-5 ring-1 ring-line\">\n        <div className=\"flex items-start justify-between gap-2\">\n          <AuthorLine author={post.author} at={post.createdAt} fixture={post.fixture} mine={post.mine} />\n          {post.mine ? (\n            <button\n              aria-label=\"Delete post\"\n              onClick={() => {\n                socialStore.deletePost(post.id);\n                showToast(\"Post deleted\");\n                router.push(\"/social?tab=community\");\n              }}\n              className=\"-mr-1 -mt-1 flex h-8 w-8 items-center justify-center rounded-full text-ink-soft\"\n            >\n              <Trash2 size={15} />\n            </button>\n          ) : (\n            <button\n              aria-label=\"Report post\"\n              onClick={() => setReporting(post.id)}\n              className=\"-mr-1 -mt-1 flex h-8 w-8 items-center justify-center rounded-full text-ink-soft\"\n            >\n              <Flag size={14} />\n            </button>\n          )}\n        </div>\n        <p className=\"mt-3 text-[11px] font-semibold uppercase tracking-wide text-forest\">{topicLabel(post.topic)}</p>\n        <h1 className=\"mt-0.5 text-xl font-bold leading-snug\">{post.title}</h1>\n        {post.body && <p className=\"mt-2 whitespace-pre-line text-[15px] leading-relaxed\">{post.body}</p>}\n        {post.wantsExpert && (\n          <p className=\"mt-3 flex items-start gap-1.5 rounded-2xl bg-bg px-3 py-2 text-xs text-ink-soft ring-1 ring-line\">\n            <Stethoscope size={14} className=\"mt-px shrink-0\" />\n            Waiting for a verified expert. Verified professionals aren&apos;t on the app yet — this question is queued for\n            them.\n          </p>\n        )}\n        <div className=\"mt-4\">\n          <ReactionBar targetId={post.id} base={post.baseReactions} />\n        </div>\n      </article>\n\n      <h2 className=\"px-1 text-sm font-bold\">\n        {replies.length ? `${replies.length} ${replies.length === 1 ? \"reply\" : \"replies\"}` : \"No replies yet\"}\n      </h2>\n\n      <div className=\"stagger space-y-3\">\n        {replies.map((r) => (\n          <div key={r.id} className=\"rounded-3xl bg-surface p-4 ring-1 ring-line\">\n            <div className=\"flex items-start justify-between gap-2\">\n              <AuthorLine author={r.author} at={r.createdAt} fixture={r.fixture} mine={r.mine} />\n              {r.mine ? (\n                <button\n                  aria-label=\"Delete reply\"\n                  onClick={() => {\n                    socialStore.deleteReply(r.id);\n                    showToast(\"Reply deleted\");\n                  }}\n                  className=\"-mr-1 -mt-1 flex h-8 w-8 items-center justify-center rounded-full text-ink-soft\"\n                >\n                  <Trash2 size={14} />\n                </button>\n              ) : (\n                <button\n                  aria-label=\"Report reply\"\n                  onClick={() => setReporting(r.id)}\n                  className=\"-mr-1 -mt-1 flex h-8 w-8 items-center justify-center rounded-full text-ink-soft\"\n                >\n                  <Flag size={13} />\n                </button>\n              )}\n            </div>\n            <p className=\"mt-2 whitespace-pre-line text-sm leading-relaxed\">{r.body}</p>\n            <div className=\"mt-3\">\n              <ReactionBar targetId={r.id} base={r.baseReactions} compact />\n            </div>\n          </div>\n        ))}\n      </div>\n\n      {/* Reply box */}\n      <div className=\"rounded-3xl bg-surface p-4 ring-1 ring-line\">\n        <label htmlFor=\"reply\" className=\"text-xs font-semibold\">\n          Add a supportive reply\n        </label>\n        <textarea\n          id=\"reply\"\n          rows={3}\n          value={reply}\n          maxLength={LIMITS.replyMax}\n          onChange={(e) => {\n            setReply(e.target.value);\n            setError(\"\");\n          }}\n          placeholder=\"Share what helped you. Be kind.\"\n          className=\"mt-2 w-full resize-none rounded-2xl px-4 py-3 text-sm outline-none ring-1 ring-line focus:ring-2 focus:ring-forest\"\n        />\n        {error && (\n          <p role=\"alert\" className=\"mt-1 text-xs font-medium text-red-600\">\n            {error}\n          </p>\n        )}\n        <div className=\"mt-2 flex items-center justify-between gap-2\">\n          <label className=\"flex items-center gap-2 text-xs text-ink-soft\">\n            <input\n              type=\"checkbox\"\n              checked={anonymous || !c.nickname}\n              disabled={!c.nickname}\n              onChange={(e) => setAnonymous(e.target.checked)}\n              className=\"h-4 w-4 accent-[var(--forest)]\"\n            />\n            {c.nickname ? \"Reply anonymously\" : \"Replying anonymously\"}\n          </label>\n          <button onClick={send} className=\"rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white\">\n            Reply\n          </button>\n        </div>\n        <p className=\"mt-2 flex items-start gap-1.5 text-[11px] text-ink-soft\">\n          <Lock size={11} className=\"mt-px shrink-0\" /> Don&apos;t share phone numbers, links or private details.\n        </p>\n      </div>\n\n      <ReportSheet\n        targetId={reporting ?? \"\"}\n        open={reporting !== null}\n        onClose={() => setReporting(null)}\n        onReported={() => {\n          if (reporting === post.id) router.push(\"/social?tab=community\");\n        }}\n      />\n    </div>\n  );\n}\n",
  "src/app/(app)/social/saved/page.tsx": "\"use client\";\n\nimport Link from \"next/link\";\nimport { ArrowLeft, Bookmark } from \"lucide-react\";\nimport { ContentRow } from \"@/components/social/ContentCards\";\nimport { LIBRARY } from \"@/lib/content/library\";\nimport { useSocial } from \"@/lib/social/store\";\n\nexport default function SavedPage() {\n  const { bookmarks, ready } = useSocial();\n  const items = Object.entries(bookmarks)\n    .sort((a, b) => b[1].localeCompare(a[1])) // newest saved first\n    .map(([id]) => LIBRARY.find((c) => c.id === id))\n    .filter((c): c is (typeof LIBRARY)[number] => Boolean(c));\n\n  return (\n    <div className=\"stagger space-y-4\">\n      <Link href=\"/social\" className=\"flex items-center gap-1 text-sm text-ink-soft\">\n        <ArrowLeft size={16} /> Social\n      </Link>\n      <div>\n        <h1 className=\"text-2xl font-bold\">Saved</h1>\n        <p className=\"mt-1 text-sm text-ink-soft\">Saved on this phone. Only you can see this list.</p>\n      </div>\n\n      {!ready ? (\n        <div className=\"space-y-3\" aria-busy=\"true\">\n          {[0, 1].map((i) => (\n            <div key={i} className=\"h-24 animate-pulse rounded-3xl bg-surface ring-1 ring-line\" />\n          ))}\n        </div>\n      ) : items.length === 0 ? (\n        <div className=\"rounded-3xl bg-surface p-8 text-center ring-1 ring-line\">\n          <Bookmark className=\"mx-auto text-forest\" size={26} />\n          <p className=\"mt-2 font-semibold\">Nothing saved yet</p>\n          <p className=\"mt-1 text-sm text-ink-soft\">Tap the bookmark on any guide, video or answer to keep it here.</p>\n          <Link href=\"/social\" className=\"mt-4 inline-block rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white\">\n            Explore Discover\n          </Link>\n        </div>\n      ) : (\n        <div className=\"space-y-3\">\n          {items.map((c) => (\n            <ContentRow key={c.id} item={c} />\n          ))}\n        </div>\n      )}\n    </div>\n  );\n}\n",
  "src/app/(app)/social/topic/[id]/page.tsx": "\"use client\";\n\nimport Link from \"next/link\";\nimport { useParams } from \"next/navigation\";\nimport { ArrowLeft } from \"lucide-react\";\nimport { ContentRow } from \"@/components/social/ContentCards\";\nimport { isSectionId, sectionAll, SECTIONS } from \"@/lib/content/select\";\n\nexport default function TopicPage() {\n  const { id } = useParams<{ id: string }>();\n  const valid = isSectionId(id);\n  const items = valid ? sectionAll(id) : [];\n  const section = SECTIONS.find((s) => s.id === id);\n\n  return (\n    <div className=\"stagger space-y-4\">\n      <Link href=\"/social\" className=\"flex items-center gap-1 text-sm text-ink-soft\">\n        <ArrowLeft size={16} /> Discover\n      </Link>\n\n      {/* Category navigation */}\n      <div className=\"-mx-5 flex gap-2 overflow-x-auto px-5 pb-1 [scrollbar-width:none]\">\n        {SECTIONS.map((s) => (\n          <Link\n            key={s.id}\n            href={`/social/topic/${s.id}`}\n            aria-current={s.id === id ? \"page\" : undefined}\n            className={`shrink-0 rounded-full px-3.5 py-2 text-xs font-semibold ${\n              s.id === id ? \"bg-forest-deep text-white\" : \"bg-surface text-ink-soft ring-1 ring-line\"\n            }`}\n          >\n            {s.title}\n          </Link>\n        ))}\n      </div>\n\n      {!valid ? (\n        <div className=\"rounded-3xl bg-surface p-8 text-center ring-1 ring-line\">\n          <p className=\"font-semibold\">Topic not found</p>\n          <Link href=\"/social\" className=\"mt-4 inline-block rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white\">\n            Back to Discover\n          </Link>\n        </div>\n      ) : (\n        <>\n          <div>\n            <h1 className=\"text-2xl font-bold leading-tight\">{section?.title}</h1>\n            <p className=\"mt-1 text-sm text-ink-soft\">\n              {items.length} {items.length === 1 ? \"item\" : \"items\"}\n              {section?.blurb ? ` · ${section.blurb}` : \"\"}\n            </p>\n          </div>\n          {items.length === 0 ? (\n            <div className=\"rounded-3xl bg-surface p-8 text-center ring-1 ring-line\">\n              <p className=\"font-semibold\">Nothing here yet</p>\n              <p className=\"mt-1 text-sm text-ink-soft\">New content for this topic is on the way.</p>\n            </div>\n          ) : (\n            <div className=\"space-y-3\">\n              {items.map((c) => (\n                <ContentRow key={c.id} item={c} />\n              ))}\n            </div>\n          )}\n        </>\n      )}\n    </div>\n  );\n}\n",
  "src/app/globals.css": "@import \"tailwindcss\";\n\n/* Brand tokens — Kayani Men's Social (Fernly-inspired: white, forest green, mint) */\n:root {\n  --bg: #f4f6f4;\n  --surface: #ffffff;\n  --ink: #0f1f1a;\n  --ink-soft: #5b6b65;\n  --line: #e3e8e5;\n  --forest: #0f5c46;\n  --forest-deep: #073b2d;\n  --mint: #dff3ea;\n  --mint-strong: #5dcaa5;\n}\n\n@theme inline {\n  --color-bg: var(--bg);\n  --color-surface: var(--surface);\n  --color-ink: var(--ink);\n  --color-ink-soft: var(--ink-soft);\n  --color-line: var(--line);\n  --color-forest: var(--forest);\n  --color-forest-deep: var(--forest-deep);\n  --color-mint: var(--mint);\n  --color-mint-strong: var(--mint-strong);\n  --font-sans: \"Plus Jakarta Sans Variable\", system-ui, sans-serif;\n}\n\nhtml {\n  scroll-behavior: smooth;\n}\n\nbody {\n  background: var(--bg);\n  color: var(--ink);\n  font-family: \"Plus Jakarta Sans Variable\", system-ui, sans-serif;\n  -webkit-tap-highlight-color: transparent;\n}\n\n/* Gentle entrance motion */\n@keyframes rise {\n  from { opacity: 0; transform: translateY(12px); }\n  to { opacity: 1; transform: translateY(0); }\n}\n.rise { animation: rise 0.5s cubic-bezier(0.2, 0.8, 0.2, 1) both; }\n.rise-2 { animation-delay: 0.08s; }\n.rise-3 { animation-delay: 0.16s; }\n.rise-4 { animation-delay: 0.24s; }\n\n/* ===== Motion kit (Fernly-style) ===== */\n\n/* 1. Page enter: whole page fades in */\n@keyframes page-in {\n  from { opacity: 0; }\n  to { opacity: 1; }\n}\n.page-enter { animation: page-in 0.35s ease-out both; }\n\n/* 1b. Stagger: each direct child rises in, one after another */\n.stagger > * { animation: rise 0.55s cubic-bezier(0.2, 0.8, 0.2, 1) both; }\n.stagger > *:nth-child(1) { animation-delay: 0.04s; }\n.stagger > *:nth-child(2) { animation-delay: 0.10s; }\n.stagger > *:nth-child(3) { animation-delay: 0.16s; }\n.stagger > *:nth-child(4) { animation-delay: 0.22s; }\n.stagger > *:nth-child(5) { animation-delay: 0.28s; }\n.stagger > *:nth-child(6) { animation-delay: 0.34s; }\n.stagger > *:nth-child(7) { animation-delay: 0.40s; }\n.stagger > *:nth-child(n + 8) { animation-delay: 0.46s; }\n\n/* 2. Bars grow upward */\n@keyframes grow-up {\n  from { transform: scaleY(0); }\n  to { transform: scaleY(1); }\n}\n.grow-bar {\n  transform-origin: bottom;\n  animation: grow-up 0.8s cubic-bezier(0.2, 0.8, 0.2, 1) both;\n}\n\n/* 3. Toast pill: pops up from the bottom, then fades away */\n@keyframes toast-in {\n  from { opacity: 0; transform: translate(-50%, 16px) scale(0.96); }\n  to { opacity: 1; transform: translate(-50%, 0) scale(1); }\n}\n@keyframes toast-out {\n  from { opacity: 1; transform: translate(-50%, 0) scale(1); }\n  to { opacity: 0; transform: translate(-50%, 8px) scale(0.98); }\n}\n.toast-in { animation: toast-in 0.32s cubic-bezier(0.2, 0.8, 0.2, 1) both; }\n.toast-out { animation: toast-out 0.25s ease-in both; }\n\n/* 4. Popup sheet: background dims + blurs, card scales in */\n@keyframes backdrop-in {\n  from { opacity: 0; }\n  to { opacity: 1; }\n}\n@keyframes sheet-in {\n  from { opacity: 0; transform: translateY(16px) scale(0.97); }\n  to { opacity: 1; transform: translateY(0) scale(1); }\n}\n.backdrop-in { animation: backdrop-in 0.25s ease-out both; }\n.sheet-in { animation: sheet-in 0.35s cubic-bezier(0.2, 0.8, 0.2, 1) both; }\n\n/* 5. Points burst: \"+15\" floats up and fades when an activity is done */\n@keyframes float-up {\n  0% { opacity: 0; transform: translateY(4px) scale(0.9); }\n  20% { opacity: 1; transform: translateY(0) scale(1.05); }\n  100% { opacity: 0; transform: translateY(-28px) scale(1); }\n}\n.float-up { animation: float-up 0.9s ease-out both; pointer-events: none; }\n\n/* Hatched (striped) bar, like Fernly's empty days */\n.hatch {\n  background-image: repeating-linear-gradient(\n    -45deg,\n    var(--line) 0 2px,\n    transparent 2px 7px\n  );\n  box-shadow: inset 0 0 0 1px var(--line);\n}\n\n/* Respect phones set to \"reduce motion\" */\n@media (prefers-reduced-motion: reduce) {\n  .rise, .page-enter, .stagger > *, .grow-bar,\n  .toast-in, .toast-out, .backdrop-in, .sheet-in, .float-up { animation: none; }\n}\n",
  "src/app/page.tsx": "\"use client\";\n\nimport { useEffect, useState } from \"react\";\nimport { useRouter } from \"next/navigation\";\n\ntype Lang = \"en\" | \"sw\";\n\nconst copy = {\n  en: {\n    tagline: \"Your private companion for men's wellness\",\n    points: [\n      \"Daily activities that fit your life\",\n      \"Short lessons from trusted sources\",\n      \"A private space to track how you feel\",\n    ],\n    ageQuestion: \"This app talks openly about men's sexual health.\",\n    confirm: \"I am 18 or older\",\n    privacy: \"No sign-up needed to look around. Your data stays private.\",\n  },\n  sw: {\n    tagline: \"Mwenzako wa siri kwa afya ya mwanaume\",\n    points: [\n      \"Shughuli za kila siku zinazoendana na maisha yako\",\n      \"Masomo mafupi kutoka vyanzo vya kuaminika\",\n      \"Sehemu ya siri ya kufuatilia unavyojisikia\",\n    ],\n    ageQuestion: \"Programu hii inazungumzia afya ya uzazi ya mwanaume kwa uwazi.\",\n    confirm: \"Nina miaka 18 au zaidi\",\n    privacy: \"Huhitaji kujisajili ili kuangalia. Taarifa zako ni siri.\",\n  },\n} as const;\n\nexport default function Welcome() {\n  const router = useRouter();\n  const [lang, setLang] = useState<Lang>(\"en\");\n  const t = copy[lang];\n\n  // If he already confirmed 18+ before, go straight to Man\n  useEffect(() => {\n    try {\n      if (localStorage.getItem(\"ms_age_ok\") === \"1\") router.replace(\"/man\");\n    } catch {}\n  }, [router]);\n\n  function enter() {\n    try {\n      localStorage.setItem(\"ms_age_ok\", \"1\");\n      localStorage.setItem(\"ms_lang\", lang);\n    } catch {}\n    router.push(\"/man\");\n  }\n\n  return (\n    <main className=\"mx-auto flex min-h-dvh max-w-md flex-col px-5 pb-8 pt-6\">\n      {/* Top bar: logo + language switch */}\n      <header className=\"rise flex items-center justify-between\">\n        <div className=\"flex items-center gap-2\">\n          <div className=\"flex h-9 w-9 items-center justify-center rounded-xl bg-forest text-sm font-bold text-mint\">\n            MS\n          </div>\n          <span className=\"text-base font-semibold\">Men&apos;s Social</span>\n        </div>\n        <div className=\"flex rounded-full bg-surface p-1 text-xs font-semibold ring-1 ring-line\">\n          {([\"en\", \"sw\"] as const).map((l) => (\n            <button\n              key={l}\n              onClick={() => setLang(l)}\n              className={`rounded-full px-3 py-1.5 transition-colors ${\n                lang === l ? \"bg-forest text-white\" : \"text-ink-soft\"\n              }`}\n              aria-pressed={lang === l}\n            >\n              {l.toUpperCase()}\n            </button>\n          ))}\n        </div>\n      </header>\n\n      {/* Hero card */}\n      <section className=\"rise rise-2 mt-8 rounded-3xl bg-forest-deep p-6 text-white\">\n        <p className=\"text-sm text-mint-strong\">Kayani Men&apos;s Social</p>\n        <h1 className=\"mt-2 text-[28px] font-bold leading-tight\">{t.tagline}</h1>\n        <ul className=\"mt-6 space-y-3\">\n          {t.points.map((p) => (\n            <li key={p} className=\"flex items-start gap-3 text-sm text-mint\">\n              <span className=\"mt-1.5 h-2 w-2 shrink-0 rounded-full bg-mint-strong\" />\n              {p}\n            </li>\n          ))}\n        </ul>\n      </section>\n\n      {/* Age check */}\n      <section className=\"rise rise-3 mt-4 rounded-3xl bg-surface p-5 ring-1 ring-line\">\n        <p className=\"text-sm text-ink-soft\">{t.ageQuestion}</p>\n        <button\n          onClick={enter}\n          className=\"mt-4 w-full rounded-full bg-forest py-3.5 text-sm font-semibold text-white transition-transform active:scale-[0.98]\"\n        >\n          {t.confirm}\n        </button>\n      </section>\n\n      <p className=\"rise rise-4 mt-auto pt-8 text-center text-xs text-ink-soft\">{t.privacy}</p>\n    </main>\n  );\n}\n",
  "src/components/BottomNav.tsx": "\"use client\";\n\nimport Link from \"next/link\";\nimport { usePathname } from \"next/navigation\";\nimport { MessageCircle, Sparkles, UserRound } from \"lucide-react\";\n\n// Three tabs only. \"Man\" is Home and Progress in one place.\nconst tabs = [\n  { href: \"/social\", label: \"Social\", Icon: MessageCircle },\n  { href: \"/man\", label: \"Man\", Icon: Sparkles },\n  { href: \"/me\", label: \"Me\", Icon: UserRound },\n];\n\nexport default function BottomNav() {\n  const pathname = usePathname();\n\n  return (\n    <nav className=\"fixed inset-x-0 bottom-0 z-20 border-t border-line bg-surface/95 backdrop-blur pb-[env(safe-area-inset-bottom)]\">\n      <ul className=\"mx-auto flex max-w-md justify-around px-2 py-2\">\n        {tabs.map(({ href, label, Icon }) => {\n          const active = pathname.startsWith(href) || (href === \"/man\" && pathname.startsWith(\"/learn\"));\n          return (\n            <li key={href}>\n              <Link\n                href={href}\n                className={`flex w-20 flex-col items-center gap-1 rounded-xl py-1.5 text-[11px] font-medium transition-colors ${\n                  active ? \"text-forest\" : \"text-ink-soft\"\n                }`}\n              >\n                <span\n                  className={`flex h-8 w-12 items-center justify-center rounded-full transition-colors ${\n                    active ? \"bg-mint\" : \"\"\n                  }`}\n                >\n                  <Icon size={20} strokeWidth={active ? 2.4 : 1.8} />\n                </span>\n                {label}\n              </Link>\n            </li>\n          );\n        })}\n      </ul>\n    </nav>\n  );\n}\n",
  "src/components/feed/ActivitiesCard.tsx": "\"use client\";\n\nimport { useState } from \"react\";\nimport { Check, Clock, Undo2 } from \"lucide-react\";\nimport { Why } from \"./FeedCards\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { feedStore } from \"@/lib/feed/store\";\nimport type { Activity } from \"@/lib/feed/catalog\";\nimport type { HomeFeed } from \"./useHomeFeed\";\n\nexport default function ActivitiesCard({ f }: { f: HomeFeed }) {\n  const showToast = useToast();\n  const [burst, setBurst] = useState<{ id: string; points: number; key: number } | null>(null);\n\n  function done(a: Activity) {\n    feedStore.setChoice(a.id, \"done\");\n    setBurst({ id: a.id, points: a.points, key: Date.now() });\n    setTimeout(() => setBurst(null), 950);\n    showToast(f.isNew ? \"Nice! Your points are saved on this phone.\" : `+${a.points} points`);\n  }\n\n  // Check-in, water and sleep have their own cards on this screen, so only show the rest here\n  const list = f.activities.filter((a) => !a.tracker);\n  const listDone = list.filter((a) => f.statuses[a.id] === \"done\").length;\n\n  return (\n    <section className=\"rounded-3xl bg-surface p-5 ring-1 ring-line\">\n      <div className=\"flex items-center justify-between\">\n        <p className=\"font-semibold\">Today&apos;s activities</p>\n        <span className=\"text-xs text-ink-soft\">\n          {listDone} of {list.length} done\n        </span>\n      </div>\n\n      <ul className=\"mt-3 divide-y divide-line\">\n        {list.map((a) => {\n          const s = f.statuses[a.id];\n          const title = f.discreet ? a.discreetTitle : a.title;\n          const closed = s === \"done\" || s === \"skipped\";\n          return (\n            <li key={a.id} className=\"relative py-3\">\n              <div className=\"flex items-start gap-3\">\n                <span\n                  className={`mt-0.5 flex h-6 w-6 shrink-0 items-center justify-center rounded-full ${\n                    s === \"done\" ? \"bg-forest text-white\" : s === \"later\" ? \"bg-mint text-forest\" : \"ring-1 ring-line\"\n                  }`}\n                >\n                  {s === \"done\" ? <Check size={14} strokeWidth={3} /> : s === \"later\" ? <Clock size={12} /> : null}\n                </span>\n                <div className=\"min-w-0 flex-1\">\n                  <p className={`text-sm font-medium ${closed ? \"text-ink-soft line-through decoration-line\" : \"\"}`}>\n                    {title}\n                  </p>\n                  <p className=\"text-[11px] text-ink-soft\">\n                    {s === \"skipped\"\n                      ? \"Skipped today\"\n                      : s === \"later\"\n                        ? \"Saved for later today\"\n                        : `${a.detail} · +${a.points} points`}\n                  </p>\n\n                  {/* Actions */}\n                  {!closed && (\n                    <div className=\"mt-2 flex flex-wrap gap-1.5\">\n                      <button\n                        onClick={() => done(a)}\n                        className=\"rounded-full bg-forest px-3.5 py-1.5 text-xs font-semibold text-white transition-transform active:scale-95\"\n                      >\n                        Done\n                      </button>\n                      {s !== \"later\" && (\n                        <button\n                          onClick={() => {\n                            feedStore.setChoice(a.id, \"later\");\n                            showToast(\"Saved for later today\");\n                          }}\n                          className=\"rounded-full px-3.5 py-1.5 text-xs font-semibold ring-1 ring-line\"\n                        >\n                          Later\n                        </button>\n                      )}\n                      <button\n                        onClick={() => {\n                          feedStore.setChoice(a.id, \"skipped\");\n                          showToast(\"Skipped. No problem.\");\n                        }}\n                        className=\"rounded-full px-3.5 py-1.5 text-xs font-semibold text-ink-soft\"\n                      >\n                        Skip\n                      </button>\n                    </div>\n                  )}\n                  {closed && (\n                    <button\n                      onClick={() => feedStore.clearChoice(a.id)}\n                      className=\"mt-1 flex items-center gap-1 text-[11px] font-semibold text-forest\"\n                    >\n                      <Undo2 size={11} /> Undo\n                    </button>\n                  )}\n                  {!closed && <Why text={a.why} />}\n                </div>\n              </div>\n\n              {burst?.id === a.id && (\n                <span\n                  key={burst.key}\n                  className=\"float-up absolute right-2 top-2 rounded-full bg-forest-deep px-2.5 py-1 text-xs font-bold text-white\"\n                >\n                  +{burst.points}\n                </span>\n              )}\n            </li>\n          );\n        })}\n      </ul>\n    </section>\n  );\n}\n",
  "src/components/feed/FeedCards.tsx": "\"use client\";\n\nimport Link from \"next/link\";\nimport { BookOpen, Clock, Flame, Lightbulb, PartyPopper } from \"lucide-react\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { feedStore } from \"@/lib/feed/store\";\nimport type { HomeFeed } from \"./useHomeFeed\";\n\n/** Small \"Why am I seeing this?\" link that opens a one-line reason. */\nexport function Why({ text }: { text: string }) {\n  return (\n    <details className=\"mt-1.5 text-[11px] text-ink-soft\">\n      <summary className=\"cursor-pointer select-none list-none font-medium underline decoration-line underline-offset-2\">\n        Why am I seeing this?\n      </summary>\n      <p className=\"mt-1\">{text}</p>\n    </details>\n  );\n}\n\nconst NEW_USER_WHY =\n  \"Suggested for everyone while you're new. After the short assessment, this adapts to your goals.\";\n\nexport function TodayCard({ f }: { f: HomeFeed }) {\n  const pct = f.total ? Math.round((f.doneCount / f.total) * 100) : 0;\n  return (\n    <section className=\"rounded-3xl bg-forest-deep p-5 text-white\">\n      <p className=\"text-sm text-mint-strong\">{f.greeting}</p>\n      {f.isNew ? (\n        <>\n          <p className=\"mt-1 text-2xl font-bold\">Try your first activity</p>\n          <p className=\"mt-1 text-sm text-mint\">Pick anything below. Small steps count.</p>\n        </>\n      ) : (\n        <>\n          <p className=\"mt-1 text-2xl font-bold\">\n            {f.doneCount} of {f.total} done today\n          </p>\n          <div\n            className=\"mt-3 h-2.5 w-full overflow-hidden rounded-full bg-white/15\"\n            role=\"progressbar\"\n            aria-label=\"Activities done today\"\n            aria-valuenow={pct}\n            aria-valuemin={0}\n            aria-valuemax={100}\n          >\n            <div\n              className=\"h-full rounded-full bg-mint-strong transition-[width] duration-700 ease-out\"\n              style={{ width: `${Math.max(pct, f.doneCount ? 6 : 0)}%` }}\n            />\n          </div>\n          <div className=\"mt-4 flex items-center justify-between text-xs\">\n            <span className=\"text-mint\">\n              <span className=\"text-lg font-bold text-white\">{f.points}</span> points · Level {f.level.level}\n            </span>\n            {f.streak > 0 && (\n              <span className=\"flex items-center gap-1 rounded-full bg-white/10 px-2.5 py-1 font-semibold\">\n                <Flame size={13} className=\"text-mint-strong\" />\n                {f.streak} {f.streak === 1 ? \"day\" : \"days\"} in a row\n              </span>\n            )}\n          </div>\n          <p className=\"mt-2 text-[11px] text-mint/80\">\n            {f.pointsToday > 0 ? `+${f.pointsToday} today · ` : \"\"}\n            {f.level.toNext} points to Level {f.level.level + 1}\n          </p>\n        </>\n      )}\n    </section>\n  );\n}\n\nexport function ReminderCard({ f }: { f: HomeFeed }) {\n  const showToast = useToast();\n  const a = f.reminder;\n  if (!a) return null;\n  const title = f.discreet ? a.discreetTitle : a.title;\n  return (\n    <section className=\"rounded-3xl bg-surface p-5 ring-1 ring-line\">\n      <p className=\"flex items-center gap-1.5 text-xs font-medium text-forest\">\n        <Clock size={13} /> Now · {f.slot}\n      </p>\n      <div className=\"mt-1 flex items-center justify-between gap-3\">\n        <div className=\"min-w-0\">\n          <p className=\"font-semibold\">{title}</p>\n          <p className=\"text-xs text-ink-soft\">{a.detail}</p>\n        </div>\n        {a.tracker ? (\n          <a href={`#${a.tracker}`} className=\"shrink-0 rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white\">\n            Start\n          </a>\n        ) : (\n          <button\n            onClick={() => {\n              feedStore.setChoice(a.id, \"done\");\n              showToast(`+${a.points} points`);\n            }}\n            className=\"shrink-0 rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white transition-transform active:scale-95\"\n          >\n            Done\n          </button>\n        )}\n      </div>\n      <Why text={f.isNew ? NEW_USER_WHY : a.why} />\n    </section>\n  );\n}\n\nexport function LessonCard({ f }: { f: HomeFeed }) {\n  const l = f.lesson;\n  const read = f.lessonRead(l.id);\n  return (\n    <Link href={`/learn/${l.id}`} className=\"block rounded-3xl bg-surface p-5 ring-1 ring-line transition-transform active:scale-[0.99]\">\n      <p className=\"flex items-center gap-1.5 text-xs text-ink-soft\">\n        <BookOpen size={13} /> Lesson · {l.minutes} min · {l.topic}\n      </p>\n      <p className=\"mt-1 font-semibold\">{l.title}</p>\n      <p className=\"mt-1 text-sm text-ink-soft\">{l.summary}</p>\n      <p className=\"mt-3 text-xs font-semibold text-forest\">{read ? \"Read ✓ · Open again\" : `Read now · +${l.points} points`}</p>\n    </Link>\n  );\n}\n\nexport function TipCard({ f }: { f: HomeFeed }) {\n  return (\n    <section className=\"rounded-3xl bg-mint p-5\">\n      <p className=\"flex items-center gap-1.5 text-xs font-medium text-forest\">\n        <Lightbulb size={13} /> Quick tip\n      </p>\n      <p className=\"mt-1 text-sm font-medium text-forest-deep\">{f.tip}</p>\n    </section>\n  );\n}\n\nexport function EndCard() {\n  return (\n    <section className=\"rounded-3xl bg-surface p-6 text-center ring-1 ring-line\">\n      <PartyPopper className=\"mx-auto text-forest\" size={28} />\n      <p className=\"mt-2 text-lg font-bold\">You&apos;re all set for today</p>\n      <p className=\"mt-1 text-sm text-ink-soft\">Come back tomorrow for a fresh start. Your trends are below.</p>\n      <div className=\"mt-4 flex justify-center gap-2\">\n        <Link href=\"/social\" className=\"rounded-full px-4 py-2.5 text-sm font-semibold ring-1 ring-line\">\n          Explore Social\n        </Link>\n        <Link href=\"/learn\" className=\"rounded-full bg-forest px-4 py-2.5 text-sm font-semibold text-white\">\n          Browse lessons\n        </Link>\n      </div>\n    </section>\n  );\n}\n",
  "src/components/feed/TopBar.tsx": "\"use client\";\n\nimport { Bell, ShoppingBag } from \"lucide-react\";\nimport { useToast } from \"@/components/motion/Toast\";\n\nexport default function TopBar() {\n  const showToast = useToast();\n  return (\n    <header className=\"flex items-center justify-between\">\n      <div className=\"flex items-center gap-2\">\n        <div className=\"flex h-9 w-9 items-center justify-center rounded-xl bg-forest text-sm font-bold text-mint\">MS</div>\n        <span className=\"text-base font-semibold\">Men&apos;s Social</span>\n      </div>\n      <div className=\"flex gap-2\">\n        <button\n          aria-label=\"Shop\"\n          onClick={() => showToast(\"The shop is coming soon\")}\n          className=\"flex h-10 w-10 items-center justify-center rounded-full bg-surface ring-1 ring-line transition-transform active:scale-95\"\n        >\n          <ShoppingBag size={18} />\n        </button>\n        <button\n          aria-label=\"Notifications\"\n          onClick={() => showToast(\"No notifications yet\")}\n          className=\"flex h-10 w-10 items-center justify-center rounded-full bg-surface ring-1 ring-line transition-transform active:scale-95\"\n        >\n          <Bell size={18} />\n        </button>\n      </div>\n    </header>\n  );\n}\n",
  "src/components/feed/TrendsSection.tsx": "\"use client\";\n\nimport { useState } from \"react\";\nimport CheckInCard from \"@/components/progress/CheckInCard\";\nimport HydrationCard from \"@/components/progress/HydrationCard\";\nimport SleepCard from \"@/components/progress/SleepCard\";\nimport type { Period } from \"@/lib/progress/types\";\n\nconst METRICS = [\n  { id: \"mood\", label: \"Energy & mood\" },\n  { id: \"water\", label: \"Water\" },\n  { id: \"sleep\", label: \"Sleep\" },\n] as const;\n\nconst PERIODS: { value: Exclude<Period, 1>; label: string }[] = [\n  { value: 7, label: \"7 days\" },\n  { value: 30, label: \"30 days\" },\n  { value: 90, label: \"90 days\" },\n];\n\n/** One place for all charts: pick what to look at and over how long. */\nexport default function TrendsSection() {\n  const [metric, setMetric] = useState<(typeof METRICS)[number][\"id\"]>(\"mood\");\n  const [period, setPeriod] = useState<Exclude<Period, 1>>(7);\n\n  return (\n    <section id=\"trends\" className=\"scroll-mt-4 space-y-3\">\n      <div>\n        <h2 className=\"text-lg font-bold\">Your trends</h2>\n        <p className=\"text-xs text-ink-soft\">Built only from what you have logged.</p>\n      </div>\n\n      <div className=\"flex gap-2 overflow-x-auto pb-1\" role=\"tablist\" aria-label=\"What to show\">\n        {METRICS.map((m) => (\n          <button\n            key={m.id}\n            role=\"tab\"\n            aria-selected={metric === m.id}\n            onClick={() => setMetric(m.id)}\n            className={`shrink-0 rounded-full px-4 py-2 text-xs font-semibold transition-colors ${\n              metric === m.id ? \"bg-forest-deep text-white\" : \"bg-surface text-ink-soft ring-1 ring-line\"\n            }`}\n          >\n            {m.label}\n          </button>\n        ))}\n      </div>\n\n      <div className=\"flex rounded-full bg-surface p-1 ring-1 ring-line\" role=\"tablist\" aria-label=\"Period\">\n        {PERIODS.map((p) => (\n          <button\n            key={p.value}\n            role=\"tab\"\n            aria-selected={period === p.value}\n            onClick={() => setPeriod(p.value)}\n            className={`flex-1 rounded-full py-2 text-xs font-semibold transition-colors ${\n              period === p.value ? \"bg-forest text-white\" : \"text-ink-soft\"\n            }`}\n          >\n            {p.label}\n          </button>\n        ))}\n      </div>\n\n      <div key={`${metric}-${period}`} className=\"page-enter\">\n        {metric === \"mood\" && <CheckInCard period={period} />}\n        {metric === \"water\" && <HydrationCard period={period} />}\n        {metric === \"sleep\" && <SleepCard period={period} />}\n      </div>\n    </section>\n  );\n}\n",
  "src/components/feed/useHomeFeed.ts": "\"use client\";\n\nimport { ACTIVITIES, LESSONS, TIPS } from \"@/lib/feed/catalog\";\nimport {\n  activeDays,\n  activityStatus,\n  dayPoints,\n  forgivingStreak,\n  greeting,\n  levelFor,\n  orderForSlot,\n  pickForDay,\n  timeSlot,\n  totalPoints,\n  type ActivityStatus,\n} from \"@/lib/feed/engine\";\nimport { useFeed } from \"@/lib/feed/store\";\nimport { dateKey } from \"@/lib/progress/dates\";\nimport { useProgress } from \"@/lib/progress/store\";\n\n/** Everything the Home feed shows, worked out from his real records and choices. */\nexport function useHomeFeed() {\n  const feed = useFeed();\n  const progress = useProgress();\n  const ready = feed.ready && progress.ready;\n\n  const now = new Date();\n  const today = dateKey(now);\n  const slot = timeSlot(now);\n  const { records, goals } = progress;\n\n  const statuses: Record<string, ActivityStatus> = {};\n  for (const a of ACTIVITIES) statuses[a.id] = activityStatus(a, feed, records, goals, today);\n\n  const activities = orderForSlot(ACTIVITIES, statuses, slot);\n  const doneCount = ACTIVITIES.filter((a) => statuses[a.id] === \"done\").length;\n  const closedCount = ACTIVITIES.filter((a) => statuses[a.id] === \"done\" || statuses[a.id] === \"skipped\").length;\n\n  const pointsToday = dayPoints(ACTIVITIES, LESSONS, feed, records, goals, today);\n  const points = totalPoints(ACTIVITIES, LESSONS, feed, records, goals);\n  const pointDays = new Set(\n    activeDays(feed, records).filter((k) => dayPoints(ACTIVITIES, LESSONS, feed, records, goals, k) > 0),\n  );\n  const streak = forgivingStreak(pointDays, today);\n\n  // The one thing to do now: first pending item that fits this time of day (or any time)\n  const reminder =\n    activities.find((a) => statuses[a.id] === \"pending\" && (a.slot === slot || a.slot === \"any\")) ?? null;\n\n  return {\n    ready,\n    today,\n    slot,\n    greeting: greeting(slot),\n    discreet: feed.settings.discreet,\n    activities,\n    statuses,\n    doneCount,\n    total: ACTIVITIES.length,\n    allClosed: closedCount === ACTIVITIES.length,\n    pointsToday,\n    points,\n    level: levelFor(points),\n    streak,\n    isNew: points === 0,\n    reminder,\n    lesson: pickForDay(LESSONS, today),\n    lessonRead: (id: string) => Boolean(feed.lessons[id]),\n    tip: pickForDay(TIPS, today),\n    waterToday: records.filter((r) => r.metric === \"water\" && r.localDate === today).reduce((s, r) => s + r.value, 0),\n    waterGoal: goals.find((g) => g.metric === \"water\")?.target ?? null,\n  };\n}\n\nexport type HomeFeed = ReturnType<typeof useHomeFeed>;\n",
  "src/components/progress/CheckInCard.tsx": "\"use client\";\n\nimport { Smile } from \"lucide-react\";\nimport DayBars from \"./DayBars\";\nimport StatusBadge from \"./StatusBadge\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { progressStore, useProgress } from \"@/lib/progress/store\";\nimport { dateKey, lastNDays, shiftKey } from \"@/lib/progress/dates\";\nimport { averageRecorded, dayLatest, dayLatestValues, periodChange } from \"@/lib/progress/calc\";\nimport { RATING_LABELS, score, signed } from \"@/lib/progress/format\";\nimport type { Period } from \"@/lib/progress/types\";\n\nconst QUESTIONS = [\n  { metric: \"energy\", title: \"Energy\", ask: \"How is your energy today?\" },\n  { metric: \"mood\", title: \"Mood\", ask: \"How is your mood today?\" },\n] as const;\n\nexport default function CheckInCard({ period }: { period: Period }) {\n  const { records, ready } = useProgress();\n  const showToast = useToast();\n  const today = dateKey(new Date());\n\n  const answered = QUESTIONS.filter((q) => dayLatest(records, q.metric, today)).length;\n  const status = answered === 0 ? \"not_recorded\" : \"tracked\";\n  const badge = answered === 0 ? \"Not yet today\" : answered === 2 ? \"Checked in\" : \"1 of 2 answered\";\n\n  const days = period === 1 ? 7 : period;\n  const keys = lastNDays(days);\n  const prevKeys = keys.map((k) => shiftKey(k, -days));\n\n  function answer(metric: \"energy\" | \"mood\", value: number) {\n    progressStore.setDailyValue({ metric, value, unit: \"score\", source: \"manual\" });\n    showToast(`${metric === \"energy\" ? \"Energy\" : \"Mood\"}: ${RATING_LABELS[value - 1]}`);\n  }\n\n  if (!ready) return <div className=\"h-56 animate-pulse rounded-3xl bg-surface ring-1 ring-line\" />;\n\n  return (\n    <section className=\"rounded-3xl bg-surface p-5 ring-1 ring-line\">\n      <div className=\"flex items-center justify-between\">\n        <div className=\"flex items-center gap-2\">\n          <span className=\"flex h-9 w-9 items-center justify-center rounded-xl bg-mint text-forest\">\n            <Smile size={18} />\n          </span>\n          <div>\n            <p className=\"font-semibold\">Energy and mood</p>\n            <p className=\"text-xs text-ink-soft\">Daily check-in · 1 to 5</p>\n          </div>\n        </div>\n        <StatusBadge status={status} text={badge} />\n      </div>\n\n      {QUESTIONS.map((q) => {\n        const todayValue = dayLatest(records, q.metric, today)?.value ?? null;\n        const values = dayLatestValues(records, q.metric, keys);\n        const avg = averageRecorded(values);\n        const prevAvg = averageRecorded(dayLatestValues(records, q.metric, prevKeys));\n        const change = periodChange(avg, prevAvg);\n        const recorded = values.filter((v) => v !== null).length;\n\n        return (\n          <div key={q.metric} className=\"mt-5 border-t border-line pt-4\">\n            {period === 1 ? (\n              <>\n                <p className=\"text-sm font-medium\">{q.ask}</p>\n                <div className=\"mt-2 grid grid-cols-5 gap-1.5\" role=\"radiogroup\" aria-label={q.title}>\n                  {RATING_LABELS.map((label, i) => {\n                    const selected = todayValue === i + 1;\n                    return (\n                      <button\n                        key={label}\n                        role=\"radio\"\n                        aria-checked={selected}\n                        onClick={() => answer(q.metric, i + 1)}\n                        className={`flex flex-col items-center gap-0.5 rounded-xl py-2 transition-all active:scale-95 ${\n                          selected ? \"bg-forest text-white\" : \"ring-1 ring-line\"\n                        }`}\n                      >\n                        <span className=\"text-sm font-bold\">{i + 1}</span>\n                        <span className={`text-[9px] ${selected ? \"text-mint\" : \"text-ink-soft\"}`}>{label}</span>\n                      </button>\n                    );\n                  })}\n                </div>\n              </>\n            ) : (\n              <div className=\"flex items-end justify-between\">\n                <div>\n                  <p className=\"text-sm font-medium\">{q.title}</p>\n                  <p className=\"text-2xl font-bold\">\n                    {avg === null ? <span className=\"text-ink-soft\">—</span> : score(avg)}\n                    <span className=\"text-sm font-medium text-ink-soft\"> / 5 average</span>\n                  </p>\n                  <p className=\"text-[11px] text-ink-soft\">\n                    {recorded} of {days} days answered\n                    {change !== null && ` · ${signed(change)} vs previous ${days} days`}\n                  </p>\n                </div>\n              </div>\n            )}\n            {period !== 1 && (\n              <div className=\"mt-3\">\n                <DayBars keys={keys} values={values} target={null} scaleMax={5} format={(v) => `${v}/5`} compact />\n              </div>\n            )}\n          </div>\n        );\n      })}\n\n      <p className=\"mt-4 text-[11px] text-ink-soft\">\n        These are your own ratings. They help you notice patterns over time — they are not a medical measurement.\n      </p>\n    </section>\n  );\n}\n",
  "src/components/progress/HydrationCard.tsx": "\"use client\";\n\nimport { useState } from \"react\";\nimport { Droplet, GlassWater, Milk, Plus, Pencil } from \"lucide-react\";\nimport ProgressBar from \"./ProgressBar\";\nimport DayBars from \"./DayBars\";\nimport StatusBadge from \"./StatusBadge\";\nimport Sheet from \"@/components/motion/Sheet\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { goalFor, progressStore, useProgress } from \"@/lib/progress/store\";\nimport { dateKey, lastNDays } from \"@/lib/progress/dates\";\nimport {\n  averageRecorded,\n  dayTotal,\n  dayTotals,\n  daysGoalMet,\n  goalStreak,\n  metricStatus,\n  targetProgress,\n} from \"@/lib/progress/calc\";\nimport { litres } from \"@/lib/progress/format\";\nimport type { Period, RecordSource, TrackingRecord } from \"@/lib/progress/types\";\n\nconst QUICK = [\n  { ml: 250, label: \"Glass\", Icon: GlassWater },\n  { ml: 500, label: \"Bottle\", Icon: Milk },\n];\n\nconst SOURCE_LABEL: Record<RecordSource, string> = {\n  manual: \"Entered\",\n  quick_add: \"Quick add\",\n  ai_estimate: \"AI estimate\",\n  device_sync: \"Synced\",\n  calculated: \"Calculated\",\n};\n\ntype SheetMode = { kind: \"custom\" } | { kind: \"edit\"; record: TrackingRecord } | { kind: \"goal\" } | null;\n\nexport default function HydrationCard({ period }: { period: Period }) {\n  const { records, goals, ready } = useProgress();\n  const showToast = useToast();\n  const [sheet, setSheet] = useState<SheetMode>(null);\n  const [input, setInput] = useState(\"\");\n  const [error, setError] = useState(\"\");\n  const [showAll, setShowAll] = useState(false);\n\n  const goal = goalFor(goals, \"water\")?.target ?? null;\n  const today = dateKey(new Date());\n  const todayTotal = dayTotal(records, \"water\", today);\n  const status = metricStatus(todayTotal, goal);\n  const pct = targetProgress(todayTotal, goal);\n\n  const keys = lastNDays(period === 1 ? 7 : period);\n  const totals = dayTotals(records, \"water\", keys);\n  const recordedDays = totals.filter((v) => v !== null).length;\n  const avg = averageRecorded(totals);\n  const met = daysGoalMet(totals, goal);\n  const streak = goalStreak(dayTotals(records, \"water\", lastNDays(90)), goal);\n\n  const todayEntries = records\n    .filter((r) => r.metric === \"water\" && r.localDate === today)\n    .sort((a, b) => b.recordedAt.localeCompare(a.recordedAt));\n\n  function quickAdd(ml: number) {\n    progressStore.addRecord({ metric: \"water\", value: ml, unit: \"ml\", source: \"quick_add\" });\n    showToast(`+${ml} ml water logged`);\n  }\n\n  function openSheet(mode: SheetMode) {\n    setError(\"\");\n    setInput(\n      mode?.kind === \"edit\" ? String(mode.record.value) : mode?.kind === \"goal\" && goal ? String(goal) : \"\",\n    );\n    setSheet(mode);\n  }\n\n  function submit() {\n    const n = Number(input);\n    const max = sheet?.kind === \"goal\" ? 10000 : 5000;\n    if (!input.trim() || !Number.isFinite(n) || n <= 0) return setError(\"Enter an amount in ml, like 300\");\n    if (n > max) return setError(`That's more than ${litres(max)}. Check the amount.`);\n    if (sheet?.kind === \"custom\") {\n      progressStore.addRecord({ metric: \"water\", value: n, unit: \"ml\", source: \"manual\" });\n      showToast(`+${Math.round(n)} ml water logged`);\n    } else if (sheet?.kind === \"edit\") {\n      progressStore.updateRecord(sheet.record.id, n);\n      showToast(\"Entry updated\");\n    } else if (sheet?.kind === \"goal\") {\n      progressStore.setGoal(\"water\", n, \"ml\");\n      showToast(`Daily goal set to ${litres(n)}`);\n    }\n    setSheet(null);\n  }\n\n  function remove(record: TrackingRecord) {\n    progressStore.deleteRecord(record.id);\n    setSheet(null);\n    showToast(`Removed ${record.value} ml`);\n  }\n\n  if (!ready) {\n    return <div className=\"h-64 animate-pulse rounded-3xl bg-surface ring-1 ring-line\" />;\n  }\n\n  return (\n    <>\n      <section className=\"rounded-3xl bg-surface p-5 ring-1 ring-line\">\n        {/* Header */}\n        <div className=\"flex items-center justify-between\">\n          <div className=\"flex items-center gap-2\">\n            <span className=\"flex h-9 w-9 items-center justify-center rounded-xl bg-mint text-forest\">\n              <Droplet size={18} />\n            </span>\n            <div>\n              <p className=\"font-semibold\">Water</p>\n              <button onClick={() => openSheet({ kind: \"goal\" })} className=\"flex items-center gap-1 text-xs text-ink-soft\">\n                Daily goal {goal ? litres(goal) : \"not set\"} <Pencil size={11} />\n              </button>\n            </div>\n          </div>\n          <StatusBadge status={status} />\n        </div>\n\n        {period === 1 ? (\n          <>\n            {/* Today */}\n            <p className=\"mt-5 text-3xl font-bold\">\n              {todayTotal === null ? (\n                <span className=\"text-ink-soft\">—</span>\n              ) : (\n                litres(todayTotal)\n              )}\n              <span className=\"text-base font-medium text-ink-soft\"> / {goal ? litres(goal) : \"—\"}</span>\n            </p>\n            <div className=\"mt-3\">\n              <ProgressBar percent={pct} status={status} label=\"Water today\" />\n            </div>\n            <p className=\"mt-2 text-xs text-ink-soft\">\n              {status === \"not_recorded\"\n                ? \"Nothing recorded yet today.\"\n                : status === \"goal_achieved\"\n                  ? \"Goal reached today. Well done.\"\n                  : `${Math.round(pct ?? 0)}% · ${litres(Math.max((goal ?? 0) - (todayTotal ?? 0), 0))} to go`}\n            </p>\n\n            {/* Quick add */}\n            <div className=\"mt-4 grid grid-cols-3 gap-2\">\n              {QUICK.map(({ ml, label, Icon }) => (\n                <button\n                  key={ml}\n                  onClick={() => quickAdd(ml)}\n                  className=\"flex flex-col items-center gap-1 rounded-2xl bg-mint/60 py-3 text-forest transition-transform active:scale-[0.96]\"\n                >\n                  <Icon size={18} />\n                  <span className=\"text-xs font-semibold\">+{ml} ml</span>\n                  <span className=\"text-[10px] text-ink-soft\">{label}</span>\n                </button>\n              ))}\n              <button\n                onClick={() => openSheet({ kind: \"custom\" })}\n                className=\"flex flex-col items-center gap-1 rounded-2xl py-3 ring-1 ring-line transition-transform active:scale-[0.96]\"\n              >\n                <Plus size={18} />\n                <span className=\"text-xs font-semibold\">Custom</span>\n                <span className=\"text-[10px] text-ink-soft\">Any amount</span>\n              </button>\n            </div>\n\n            {/* Today's entries */}\n            {todayEntries.length > 0 && (\n              <ul className=\"mt-4 divide-y divide-line border-t border-line\">\n                {(showAll ? todayEntries : todayEntries.slice(0, 3)).map((r) => (\n                  <li key={r.id}>\n                    <button\n                      onClick={() => openSheet({ kind: \"edit\", record: r })}\n                      className=\"flex w-full items-center justify-between py-2.5 text-left text-sm\"\n                    >\n                      <span>\n                        {r.value} ml\n                        <span className=\"ml-2 text-[11px] text-ink-soft\">{SOURCE_LABEL[r.source]}</span>\n                      </span>\n                      <span className=\"text-xs text-ink-soft\">\n                        {new Date(r.recordedAt).toLocaleTimeString([], { hour: \"2-digit\", minute: \"2-digit\" })}\n                      </span>\n                    </button>\n                  </li>\n                ))}\n                {todayEntries.length > 3 && (\n                  <li>\n                    <button\n                      onClick={() => setShowAll(!showAll)}\n                      className=\"w-full pt-2.5 text-left text-xs font-semibold text-forest\"\n                    >\n                      {showAll ? \"Show less\" : `Show all ${todayEntries.length} entries`}\n                    </button>\n                  </li>\n                )}\n              </ul>\n            )}\n          </>\n        ) : (\n          <>\n            {/* Period summary */}\n            <div className=\"mt-5 grid grid-cols-3 gap-2 text-center\">\n              <Stat label=\"Daily average\" value={avg === null ? \"—\" : litres(Math.round(avg))} hint=\"recorded days\" />\n              <Stat label=\"Goal reached\" value={`${met}`} hint={`of ${recordedDays} recorded`} />\n              <Stat label=\"Streak\" value={`${streak}`} hint={streak === 1 ? \"day\" : \"days\"} />\n            </div>\n            {recordedDays === 0 && (\n              <p className=\"mt-3 text-xs text-ink-soft\">No water recorded in the last {period} days.</p>\n            )}\n          </>\n        )}\n\n        {/* Chart (trends view only — the daily view stays short) */}\n        {period !== 1 && (\n          <div className=\"mt-5 border-t border-line pt-4\">\n            <p className=\"mb-3 text-xs font-medium text-ink-soft\">Last {period} days</p>\n            <DayBars keys={keys} values={totals} target={goal} format={litres} />\n          </div>\n        )}\n      </section>\n\n      {/* Add / edit / goal sheet */}\n      <Sheet\n        open={sheet !== null}\n        onClose={() => setSheet(null)}\n        title={sheet?.kind === \"goal\" ? \"Daily water goal\" : sheet?.kind === \"edit\" ? \"Edit entry\" : \"Add water\"}\n      >\n        <label htmlFor=\"water-ml\" className=\"text-xs text-ink-soft\">\n          Amount in ml\n        </label>\n        <input\n          id=\"water-ml\"\n          autoFocus\n          inputMode=\"numeric\"\n          value={input}\n          onChange={(e) => {\n            setInput(e.target.value.replace(/[^\\d.]/g, \"\"));\n            setError(\"\");\n          }}\n          onKeyDown={(e) => e.key === \"Enter\" && submit()}\n          placeholder={sheet?.kind === \"goal\" ? \"2500\" : \"300\"}\n          className={`mt-1 w-full rounded-2xl px-4 py-3 text-sm outline-none ring-1 focus:ring-2 ${\n            error ? \"ring-red-500 focus:ring-red-500\" : \"ring-line focus:ring-forest\"\n          }`}\n        />\n        {error && <p className=\"mt-1.5 text-xs text-red-600\">{error}</p>}\n        {sheet?.kind === \"goal\" && (\n          <p className=\"mt-2 text-xs text-ink-soft\">A common starting point is 2,000–3,000 ml. Choose what suits you.</p>\n        )}\n        <div className=\"mt-5 flex items-center justify-between gap-2\">\n          {sheet?.kind === \"edit\" ? (\n            <button onClick={() => remove(sheet.record)} className=\"text-sm font-semibold text-red-600\">\n              Delete\n            </button>\n          ) : (\n            <span />\n          )}\n          <div className=\"flex gap-2\">\n            <button onClick={() => setSheet(null)} className=\"rounded-full px-5 py-2.5 text-sm font-semibold ring-1 ring-line\">\n              Cancel\n            </button>\n            <button onClick={submit} className=\"rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white\">\n              Save\n            </button>\n          </div>\n        </div>\n      </Sheet>\n    </>\n  );\n}\n\nfunction Stat({ label, value, hint }: { label: string; value: string; hint: string }) {\n  return (\n    <div className=\"rounded-2xl bg-bg p-3\">\n      <p className=\"text-lg font-bold\">{value}</p>\n      <p className=\"text-[11px] font-medium\">{label}</p>\n      <p className=\"text-[10px] text-ink-soft\">{hint}</p>\n    </div>\n  );\n}\n",
  "src/components/progress/SleepCard.tsx": "\"use client\";\n\nimport { useState } from \"react\";\nimport { Moon, Pencil } from \"lucide-react\";\nimport ProgressBar from \"./ProgressBar\";\nimport DayBars from \"./DayBars\";\nimport StatusBadge from \"./StatusBadge\";\nimport Sheet from \"@/components/motion/Sheet\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { goalFor, progressStore, useProgress } from \"@/lib/progress/store\";\nimport { dateKey, lastNDays } from \"@/lib/progress/dates\";\nimport { averageRecorded, dayLatest, dayLatestValues, daysGoalMet, metricStatus, sleepMinutes, targetProgress } from \"@/lib/progress/calc\";\nimport { duration, RATING_LABELS, score } from \"@/lib/progress/format\";\nimport type { Period } from \"@/lib/progress/types\";\n\ntype Mode = \"log\" | \"goal\" | null;\n\nexport default function SleepCard({ period }: { period: Period }) {\n  const { records, goals, ready } = useProgress();\n  const showToast = useToast();\n  const [mode, setMode] = useState<Mode>(null);\n  const [bed, setBed] = useState(\"22:30\");\n  const [wake, setWake] = useState(\"06:30\");\n  const [quality, setQuality] = useState<number | null>(null);\n  const [goalHours, setGoalHours] = useState(\"\");\n  const [error, setError] = useState(\"\");\n\n  const goal = goalFor(goals, \"sleep\")?.target ?? null;\n  const today = dateKey(new Date());\n  const lastNight = dayLatest(records, \"sleep\", today);\n  const lastValue = lastNight?.value ?? null;\n  const status = metricStatus(lastValue, goal);\n  const pct = targetProgress(lastValue, goal);\n\n  const keys = lastNDays(period === 1 ? 7 : period);\n  const values = dayLatestValues(records, \"sleep\", keys);\n  const recorded = values.filter((v) => v !== null).length;\n  const avg = averageRecorded(values);\n  const met = daysGoalMet(values, goal);\n  const qualities = keys.map((k) => dayLatest(records, \"sleep\", k)?.meta?.quality ?? null);\n  const avgQuality = averageRecorded(qualities);\n\n  const preview = sleepMinutes(bed, wake);\n\n  function openLog() {\n    setError(\"\");\n    setBed(lastNight?.meta?.bedtime ?? \"22:30\");\n    setWake(lastNight?.meta?.wakeTime ?? \"06:30\");\n    setQuality(lastNight?.meta?.quality ?? null);\n    setMode(\"log\");\n  }\n\n  function openGoal() {\n    setError(\"\");\n    setGoalHours(goal ? String(goal / 60) : \"\");\n    setMode(\"goal\");\n  }\n\n  function saveLog() {\n    const mins = sleepMinutes(bed, wake);\n    if (mins === null) return setError(\"Choose a bedtime and a wake-up time.\");\n    if (mins < 60 || mins > 960) return setError(\"That's under 1 hour or over 16 hours. Check the times.\");\n    const meta = { bedtime: bed, wakeTime: wake, quality: quality ?? undefined };\n    if (lastNight) {\n      progressStore.updateRecord(lastNight.id, mins, meta);\n      showToast(\"Sleep updated\");\n    } else {\n      progressStore.addRecord({ metric: \"sleep\", value: mins, unit: \"min\", source: \"manual\", meta });\n      showToast(`${duration(mins)} of sleep logged`);\n    }\n    setMode(null);\n  }\n\n  function saveGoal() {\n    const h = Number(goalHours);\n    if (!goalHours.trim() || !Number.isFinite(h) || h < 3 || h > 12) return setError(\"Enter hours between 3 and 12, like 7.5\");\n    progressStore.setGoal(\"sleep\", h * 60, \"min\");\n    showToast(`Sleep goal set to ${duration(h * 60)}`);\n    setMode(null);\n  }\n\n  function remove() {\n    if (!lastNight) return;\n    progressStore.deleteRecord(lastNight.id);\n    setMode(null);\n    showToast(\"Sleep entry removed\");\n  }\n\n  if (!ready) return <div className=\"h-56 animate-pulse rounded-3xl bg-surface ring-1 ring-line\" />;\n\n  return (\n    <>\n      <section className=\"rounded-3xl bg-surface p-5 ring-1 ring-line\">\n        <div className=\"flex items-center justify-between\">\n          <div className=\"flex items-center gap-2\">\n            <span className=\"flex h-9 w-9 items-center justify-center rounded-xl bg-mint text-forest\">\n              <Moon size={18} />\n            </span>\n            <div>\n              <p className=\"font-semibold\">Sleep</p>\n              <button onClick={openGoal} className=\"flex items-center gap-1 text-xs text-ink-soft\">\n                Goal {goal ? duration(goal) : \"not set\"} <Pencil size={11} />\n              </button>\n            </div>\n          </div>\n          <StatusBadge status={status} />\n        </div>\n\n        {period === 1 ? (\n          <>\n            <p className=\"mt-5 text-xs font-medium text-ink-soft\">Last night</p>\n            <p className=\"text-3xl font-bold\">\n              {lastValue === null ? <span className=\"text-ink-soft\">—</span> : duration(lastValue)}\n              <span className=\"text-base font-medium text-ink-soft\"> / {goal ? duration(goal) : \"—\"}</span>\n            </p>\n            <div className=\"mt-3\">\n              <ProgressBar percent={pct} status={status} label=\"Sleep last night\" />\n            </div>\n            {lastNight ? (\n              <p className=\"mt-2 text-xs text-ink-soft\">\n                {lastNight.meta?.bedtime} → {lastNight.meta?.wakeTime}\n                {lastNight.meta?.quality ? ` · Quality: ${RATING_LABELS[lastNight.meta.quality - 1]}` : \"\"}\n              </p>\n            ) : (\n              <p className=\"mt-2 text-xs text-ink-soft\">Not logged yet for last night.</p>\n            )}\n            <button\n              onClick={openLog}\n              className=\"mt-4 w-full rounded-full bg-forest py-3 text-sm font-semibold text-white transition-transform active:scale-[0.98]\"\n            >\n              {lastNight ? \"Edit last night\" : \"Log last night\"}\n            </button>\n          </>\n        ) : (\n          <div className=\"mt-5 grid grid-cols-3 gap-2 text-center\">\n            <Stat label=\"Average\" value={avg === null ? \"—\" : duration(avg)} hint=\"recorded nights\" />\n            <Stat label=\"Goal reached\" value={`${met}`} hint={`of ${recorded} nights`} />\n            <Stat label=\"Quality\" value={avgQuality === null ? \"—\" : `${score(avgQuality)}/5`} hint=\"average\" />\n          </div>\n        )}\n\n        {period !== 1 && (\n          <div className=\"mt-5 border-t border-line pt-4\">\n            <p className=\"mb-3 text-xs font-medium text-ink-soft\">Last {period} nights</p>\n            <DayBars keys={keys} values={values} target={goal} format={duration} />\n          </div>\n        )}\n      </section>\n\n      <Sheet open={mode !== null} onClose={() => setMode(null)} title={mode === \"goal\" ? \"Sleep goal\" : \"Last night's sleep\"}>\n        {mode === \"goal\" ? (\n          <>\n            <label htmlFor=\"sleep-goal\" className=\"text-xs text-ink-soft\">Hours per night</label>\n            <input\n              id=\"sleep-goal\"\n              autoFocus\n              inputMode=\"decimal\"\n              value={goalHours}\n              onChange={(e) => {\n                setGoalHours(e.target.value.replace(/[^\\d.]/g, \"\"));\n                setError(\"\");\n              }}\n              placeholder=\"7\"\n              className={`mt-1 w-full rounded-2xl px-4 py-3 text-sm outline-none ring-1 focus:ring-2 ${error ? \"ring-red-500\" : \"ring-line focus:ring-forest\"}`}\n            />\n            <p className=\"mt-2 text-xs text-ink-soft\">Most adults do well with 7–9 hours. Choose what suits you.</p>\n          </>\n        ) : (\n          <>\n            <div className=\"grid grid-cols-2 gap-3\">\n              <label className=\"text-xs text-ink-soft\">\n                Went to bed\n                <input\n                  type=\"time\"\n                  value={bed}\n                  onChange={(e) => {\n                    setBed(e.target.value);\n                    setError(\"\");\n                  }}\n                  className=\"mt-1 w-full rounded-2xl px-3 py-3 text-sm text-ink outline-none ring-1 ring-line focus:ring-2 focus:ring-forest\"\n                />\n              </label>\n              <label className=\"text-xs text-ink-soft\">\n                Woke up\n                <input\n                  type=\"time\"\n                  value={wake}\n                  onChange={(e) => {\n                    setWake(e.target.value);\n                    setError(\"\");\n                  }}\n                  className=\"mt-1 w-full rounded-2xl px-3 py-3 text-sm text-ink outline-none ring-1 ring-line focus:ring-2 focus:ring-forest\"\n                />\n              </label>\n            </div>\n            <p className=\"mt-2 text-sm font-semibold text-forest\">{preview ? `${duration(preview)} of sleep` : \"—\"}</p>\n            <p className=\"mt-4 text-xs text-ink-soft\">How well did you sleep? (optional)</p>\n            <div className=\"mt-2 grid grid-cols-5 gap-1.5\">\n              {RATING_LABELS.map((label, i) => (\n                <button\n                  key={label}\n                  onClick={() => setQuality(quality === i + 1 ? null : i + 1)}\n                  className={`rounded-xl py-2 text-[10px] font-semibold transition-colors ${\n                    quality === i + 1 ? \"bg-forest text-white\" : \"ring-1 ring-line\"\n                  }`}\n                >\n                  {label}\n                </button>\n              ))}\n            </div>\n          </>\n        )}\n        {error && <p className=\"mt-2 text-xs text-red-600\">{error}</p>}\n        <div className=\"mt-5 flex items-center justify-between gap-2\">\n          {mode === \"log\" && lastNight ? (\n            <button onClick={remove} className=\"text-sm font-semibold text-red-600\">Delete</button>\n          ) : (\n            <span />\n          )}\n          <div className=\"flex gap-2\">\n            <button onClick={() => setMode(null)} className=\"rounded-full px-5 py-2.5 text-sm font-semibold ring-1 ring-line\">\n              Cancel\n            </button>\n            <button onClick={mode === \"goal\" ? saveGoal : saveLog} className=\"rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white\">\n              Save\n            </button>\n          </div>\n        </div>\n      </Sheet>\n    </>\n  );\n}\n\nfunction Stat({ label, value, hint }: { label: string; value: string; hint: string }) {\n  return (\n    <div className=\"rounded-2xl bg-bg p-3\">\n      <p className=\"text-lg font-bold\">{value}</p>\n      <p className=\"text-[11px] font-medium\">{label}</p>\n      <p className=\"text-[10px] text-ink-soft\">{hint}</p>\n    </div>\n  );\n}\n",
  "src/components/social/BookmarkButton.tsx": "\"use client\";\n\nimport { Bookmark } from \"lucide-react\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { socialStore, useSocial } from \"@/lib/social/store\";\n\nexport default function BookmarkButton({\n  contentId,\n  variant = \"light\",\n  size = 18,\n}: {\n  contentId: string;\n  variant?: \"light\" | \"dark\" | \"plain\";\n  size?: number;\n}) {\n  const { bookmarks, ready } = useSocial();\n  const showToast = useToast();\n  const saved = Boolean(bookmarks[contentId]);\n\n  const styles = {\n    light: \"bg-surface text-ink ring-1 ring-line\",\n    dark: \"bg-white/15 text-white\",\n    plain: \"text-ink-soft\",\n  }[variant];\n\n  return (\n    <button\n      type=\"button\"\n      disabled={!ready}\n      aria-pressed={saved}\n      aria-label={saved ? \"Remove from saved\" : \"Save for later\"}\n      onClick={(e) => {\n        e.preventDefault();\n        e.stopPropagation();\n        const nowSaved = socialStore.toggleBookmark(contentId);\n        showToast(nowSaved ? \"Saved\" : \"Removed from saved\");\n      }}\n      className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-full transition-transform active:scale-90 ${styles}`}\n    >\n      <Bookmark size={size} fill={saved ? \"currentColor\" : \"none\"} strokeWidth={2} />\n    </button>\n  );\n}\n",
  "src/components/social/Community.tsx": "\"use client\";\n\nimport { useState } from \"react\";\nimport Link from \"next/link\";\nimport { PenLine, ShieldCheck, Stethoscope } from \"lucide-react\";\nimport PostCard from \"./PostCard\";\nimport ComposeSheet from \"./ComposeSheet\";\nimport { useCommunity } from \"./useCommunity\";\nimport { COMMUNITY_TOPICS } from \"@/lib/social/community\";\n\nexport function CommunitySkeleton() {\n  return (\n    <div className=\"space-y-3\" aria-busy=\"true\" aria-label=\"Loading\">\n      {[0, 1, 2].map((i) => (\n        <div key={i} className=\"h-36 animate-pulse rounded-3xl bg-surface ring-1 ring-line\" />\n      ))}\n    </div>\n  );\n}\n\nexport default function Community() {\n  const c = useCommunity();\n  const [topic, setTopic] = useState<string>(\"all\");\n  const [sort, setSort] = useState<\"new\" | \"active\">(\"active\");\n  const [asking, setAsking] = useState(false);\n\n  if (!c.ready) return <CommunitySkeleton />;\n  const items = c.list(sort, topic);\n\n  return (\n    <div className=\"space-y-4\">\n      {/* Ask */}\n      <button\n        onClick={() => setAsking(true)}\n        className=\"flex w-full items-center gap-3 rounded-3xl bg-forest-deep p-4 text-left text-white transition-transform active:scale-[0.99]\"\n      >\n        <span className=\"flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-white/15\">\n          <PenLine size={18} />\n        </span>\n        <span className=\"flex-1\">\n          <span className=\"block font-semibold\">Ask a question</span>\n          <span className=\"block text-xs text-mint\">Anonymous by default. Men here have been there too.</span>\n        </span>\n      </button>\n\n      {/* Expert Q&A status — honest until verified professionals are onboarded */}\n      <div className=\"flex items-start gap-3 rounded-2xl px-4 py-3 ring-1 ring-line\">\n        <Stethoscope size={18} className=\"mt-0.5 shrink-0 text-forest\" />\n        <p className=\"text-xs text-ink-soft\">\n          <span className=\"font-semibold text-ink\">Expert Q&amp;A is coming.</span> Verified doctors aren&apos;t on the\n          app yet. Questions marked for an expert are queued for when they join. Meanwhile, see{\" \"}\n          <Link href=\"/social/topic/expert\" className=\"font-semibold text-forest underline\">\n            Expert answers\n          </Link>{\" \"}\n          in Discover.\n        </p>\n      </div>\n\n      {/* Topic filter + sort */}\n      <div className=\"-mx-5 flex gap-2 overflow-x-auto px-5 pb-1 [scrollbar-width:none]\" role=\"tablist\" aria-label=\"Topic\">\n        {[{ id: \"all\", label: \"All\" }, ...COMMUNITY_TOPICS].map((t) => (\n          <button\n            key={t.id}\n            role=\"tab\"\n            aria-selected={topic === t.id}\n            onClick={() => setTopic(t.id)}\n            className={`shrink-0 rounded-full px-3.5 py-2 text-xs font-semibold transition-colors ${\n              topic === t.id ? \"bg-forest-deep text-white\" : \"bg-surface text-ink-soft ring-1 ring-line\"\n            }`}\n          >\n            {t.label}\n          </button>\n        ))}\n      </div>\n      <div className=\"flex items-center justify-between text-xs\">\n        <span className=\"text-ink-soft\">\n          {items.length} {items.length === 1 ? \"conversation\" : \"conversations\"}\n        </span>\n        <div className=\"flex rounded-full bg-surface p-0.5 ring-1 ring-line\">\n          {([\"active\", \"new\"] as const).map((s) => (\n            <button\n              key={s}\n              aria-pressed={sort === s}\n              onClick={() => setSort(s)}\n              className={`rounded-full px-3 py-1 font-semibold ${sort === s ? \"bg-forest text-white\" : \"text-ink-soft\"}`}\n            >\n              {s === \"active\" ? \"Most active\" : \"Newest\"}\n            </button>\n          ))}\n        </div>\n      </div>\n\n      {/* Feed */}\n      {items.length === 0 ? (\n        <div className=\"rounded-3xl bg-surface p-8 text-center ring-1 ring-line\">\n          <p className=\"font-semibold\">No conversations here yet</p>\n          <p className=\"mt-1 text-sm text-ink-soft\">Be the first to ask. Anonymous is fine.</p>\n          <button onClick={() => setAsking(true)} className=\"mt-4 rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white\">\n            Ask a question\n          </button>\n        </div>\n      ) : (\n        <div className=\"stagger space-y-3\">\n          {items.map(({ post, replyCount }) => (\n            <PostCard key={post.id} post={post} replyCount={replyCount} />\n          ))}\n        </div>\n      )}\n\n      <p className=\"flex items-start justify-center gap-1.5 px-2 text-center text-[11px] text-ink-soft\">\n        <ShieldCheck size={12} className=\"mt-px shrink-0\" />\n        Be kind. No selling, phone numbers or links. Posts marked &quot;Sample&quot; are examples. Until the server is\n        connected, your posts are saved on this phone only.\n      </p>\n\n      <ComposeSheet open={asking} onClose={() => setAsking(false)} />\n    </div>\n  );\n}\n",
  "src/components/social/ComposeSheet.tsx": "\"use client\";\n\nimport { useState } from \"react\";\nimport { useRouter } from \"next/navigation\";\nimport { Lock } from \"lucide-react\";\nimport Sheet from \"@/components/motion/Sheet\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { checkPost, COMMUNITY_TOPICS, LIMITS, type CommunityTopic } from \"@/lib/social/community\";\nimport { socialStore, useSocial } from \"@/lib/social/store\";\n\n/** Ask a question. Anonymous by default. */\nexport default function ComposeSheet({ open, onClose }: { open: boolean; onClose: () => void }) {\n  const router = useRouter();\n  const showToast = useToast();\n  const { nickname } = useSocial();\n  const [topic, setTopic] = useState<CommunityTopic>(\"general\");\n  const [title, setTitle] = useState(\"\");\n  const [body, setBody] = useState(\"\");\n  const [anonymous, setAnonymous] = useState(true);\n  const [wantsExpert, setWantsExpert] = useState(false);\n  const [name, setName] = useState(nickname);\n  const [error, setError] = useState(\"\");\n\n  function submit() {\n    const problem = checkPost(title, body);\n    if (problem) return setError(problem);\n    if (!anonymous) {\n      const n = name.trim();\n      if (n.length < 3) return setError(\"Choose a nickname of at least 3 letters, or post anonymously.\");\n      socialStore.setNickname(n);\n    }\n    const post = socialStore.addPost({ topic, title, body, anonymous, wantsExpert });\n    setTitle(\"\");\n    setBody(\"\");\n    setWantsExpert(false);\n    onClose();\n    showToast(\"Posted\");\n    router.push(`/social/post/${post.id}`);\n  }\n\n  return (\n    <Sheet open={open} onClose={onClose} title=\"Ask the community\">\n      <div className=\"max-h-[70dvh] space-y-3 overflow-y-auto pr-1\">\n        <div>\n          <p className=\"text-xs text-ink-soft\">Topic</p>\n          <div className=\"mt-1.5 flex flex-wrap gap-1.5\">\n            {COMMUNITY_TOPICS.map((t) => (\n              <button\n                key={t.id}\n                aria-pressed={topic === t.id}\n                onClick={() => setTopic(t.id)}\n                className={`rounded-full px-3 py-1.5 text-xs font-semibold ${\n                  topic === t.id ? \"bg-forest text-white\" : \"ring-1 ring-line\"\n                }`}\n              >\n                {t.label}\n              </button>\n            ))}\n          </div>\n        </div>\n\n        <label className=\"block text-xs text-ink-soft\">\n          Your question\n          <input\n            value={title}\n            maxLength={LIMITS.titleMax}\n            onChange={(e) => {\n              setTitle(e.target.value);\n              setError(\"\");\n            }}\n            placeholder=\"How do you deal with nerves with a new partner?\"\n            className=\"mt-1 w-full rounded-2xl px-4 py-3 text-sm text-ink outline-none ring-1 ring-line focus:ring-2 focus:ring-forest\"\n          />\n        </label>\n\n        <label className=\"block text-xs text-ink-soft\">\n          Details (optional)\n          <textarea\n            value={body}\n            maxLength={LIMITS.bodyMax}\n            rows={3}\n            onChange={(e) => {\n              setBody(e.target.value);\n              setError(\"\");\n            }}\n            placeholder=\"Share only what you're comfortable with.\"\n            className=\"mt-1 w-full resize-none rounded-2xl px-4 py-3 text-sm text-ink outline-none ring-1 ring-line focus:ring-2 focus:ring-forest\"\n          />\n        </label>\n\n        <label className=\"flex items-center justify-between gap-3 rounded-2xl bg-mint/50 px-4 py-3\">\n          <span>\n            <span className=\"block text-sm font-semibold text-forest-deep\">Post anonymously</span>\n            <span className=\"block text-[11px] text-forest\">No name or number is shown.</span>\n          </span>\n          <input\n            type=\"checkbox\"\n            checked={anonymous}\n            onChange={(e) => setAnonymous(e.target.checked)}\n            className=\"h-5 w-5 accent-[var(--forest)]\"\n          />\n        </label>\n\n        {!anonymous && (\n          <label className=\"block text-xs text-ink-soft\">\n            Nickname\n            <input\n              value={name}\n              maxLength={24}\n              onChange={(e) => {\n                setName(e.target.value);\n                setError(\"\");\n              }}\n              placeholder=\"Baraka_DSM\"\n              className=\"mt-1 w-full rounded-2xl px-4 py-3 text-sm text-ink outline-none ring-1 ring-line focus:ring-2 focus:ring-forest\"\n            />\n            <span className=\"mt-1 block text-[11px]\">Don&apos;t use your real full name.</span>\n          </label>\n        )}\n\n        <label className=\"flex items-center justify-between gap-3 rounded-2xl px-4 py-3 ring-1 ring-line\">\n          <span>\n            <span className=\"block text-sm font-semibold\">Ask for an expert answer</span>\n            <span className=\"block text-[11px] text-ink-soft\">\n              Verified professionals aren&apos;t available yet. Your question will be queued for when they join.\n            </span>\n          </span>\n          <input\n            type=\"checkbox\"\n            checked={wantsExpert}\n            onChange={(e) => setWantsExpert(e.target.checked)}\n            className=\"h-5 w-5 accent-[var(--forest)]\"\n          />\n        </label>\n\n        <p className=\"flex items-start gap-1.5 text-[11px] text-ink-soft\">\n          <Lock size={12} className=\"mt-px shrink-0\" />\n          Your Man tab records and check-ins are never shared here. No phone numbers, links or selling.\n        </p>\n        {error && (\n          <p role=\"alert\" className=\"text-xs font-medium text-red-600\">\n            {error}\n          </p>\n        )}\n      </div>\n\n      <div className=\"mt-4 flex justify-end gap-2\">\n        <button onClick={onClose} className=\"rounded-full px-5 py-2.5 text-sm font-semibold ring-1 ring-line\">\n          Cancel\n        </button>\n        <button onClick={submit} className=\"rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white\">\n          Post\n        </button>\n      </div>\n    </Sheet>\n  );\n}\n",
  "src/components/social/ContentCards.tsx": "\"use client\";\n\nimport Link from \"next/link\";\nimport { ChevronRight } from \"lucide-react\";\nimport Cover from \"./Cover\";\nimport BookmarkButton from \"./BookmarkButton\";\nimport { KIND_LABEL } from \"@/lib/content/select\";\nimport type { ContentItem } from \"@/lib/content/types\";\n\nexport const contentHref = (id: string) => `/social/c/${id}`;\n\n/** Small card for horizontal rows on Discover. */\nexport function ContentCard({ item }: { item: ContentItem }) {\n  return (\n    <Link\n      href={contentHref(item.id)}\n      className=\"block w-44 shrink-0 snap-start overflow-hidden rounded-3xl bg-surface ring-1 ring-line transition-transform active:scale-[0.98]\"\n    >\n      <Cover item={item} className=\"h-24 w-full\" />\n      <div className=\"p-3\">\n        <p className=\"text-[10px] font-semibold uppercase tracking-wide text-forest\">\n          {KIND_LABEL[item.kind]} · {item.minutes} min\n        </p>\n        <p className=\"mt-1 line-clamp-3 text-[13px] font-semibold leading-snug\">{item.title}</p>\n      </div>\n    </Link>\n  );\n}\n\n/** Row for lists: search results, saved, topic pages. */\nexport function ContentRow({ item }: { item: ContentItem }) {\n  return (\n    <Link href={contentHref(item.id)} className=\"flex items-center gap-3 rounded-3xl bg-surface p-3 ring-1 ring-line\">\n      <Cover item={item} className=\"h-16 w-16 shrink-0 rounded-2xl\" showPlay={false} />\n      <div className=\"min-w-0 flex-1\">\n        <p className=\"text-[10px] font-semibold uppercase tracking-wide text-forest\">\n          {KIND_LABEL[item.kind]} · {item.minutes} min\n        </p>\n        <p className=\"line-clamp-2 text-sm font-semibold leading-snug\">{item.title}</p>\n      </div>\n      <BookmarkButton contentId={item.id} variant=\"plain\" />\n    </Link>\n  );\n}\n\n/** A Discover section: title, \"See all\", and a horizontal row of cards. */\nexport function SectionRow({\n  id,\n  title,\n  blurb,\n  items,\n}: {\n  id: string;\n  title: string;\n  blurb?: string;\n  items: ContentItem[];\n}) {\n  if (items.length === 0) return null;\n  return (\n    <section aria-labelledby={`sec-${id}`}>\n      <div className=\"flex items-end justify-between gap-3\">\n        <div>\n          <h2 id={`sec-${id}`} className=\"text-base font-bold\">\n            {title}\n          </h2>\n          {blurb && <p className=\"text-xs text-ink-soft\">{blurb}</p>}\n        </div>\n        <Link href={`/social/topic/${id}`} className=\"flex shrink-0 items-center text-xs font-semibold text-forest\">\n          See all <ChevronRight size={14} />\n        </Link>\n      </div>\n      <div className=\"-mx-5 mt-3 flex snap-x gap-3 overflow-x-auto px-5 pb-1 [scrollbar-width:none]\">\n        {items.map((c) => (\n          <ContentCard key={c.id} item={c} />\n        ))}\n      </div>\n    </section>\n  );\n}\n",
  "src/components/social/ContentDetail.tsx": "\"use client\";\n\nimport { useState } from \"react\";\nimport Link from \"next/link\";\nimport { ArrowLeft, Check, ExternalLink, MessageCircle, PlayCircle, ShieldCheck } from \"lucide-react\";\nimport Cover from \"./Cover\";\nimport BookmarkButton from \"./BookmarkButton\";\nimport { ContentRow } from \"./ContentCards\";\nimport { DoctorCheck, PelvicFloorTrainer, QuizRunner } from \"./ContentTools\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { LIBRARY, TOPICS } from \"@/lib/content/library\";\nimport { getContent, KIND_LABEL } from \"@/lib/content/select\";\nimport { feedStore, useFeed } from \"@/lib/feed/store\";\n\n/** Full page for any piece of content: guide, article, video, quiz, tool or expert answer. */\nexport default function ContentDetail({ id, back }: { id: string; back: { href: string; label: string } }) {\n  const item = getContent(id);\n  const feed = useFeed();\n  const showToast = useToast();\n  const [lang, setLang] = useState<\"en\" | \"sw\">(\"en\");\n\n  if (!item) {\n    return (\n      <div className=\"space-y-4\">\n        <Link href={back.href} className=\"flex items-center gap-1 text-sm text-ink-soft\">\n          <ArrowLeft size={16} /> {back.label}\n        </Link>\n        <div className=\"rounded-3xl bg-surface p-8 text-center ring-1 ring-line\">\n          <p className=\"font-semibold\">This content isn&apos;t available</p>\n          <p className=\"mt-1 text-sm text-ink-soft\">It may have been moved or removed.</p>\n          <Link href=\"/social\" className=\"mt-4 inline-block rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white\">\n            Go to Discover\n          </Link>\n        </div>\n      </div>\n    );\n  }\n\n  const topic = TOPICS.find((t) => t.id === item.topic);\n  const sw = lang === \"sw\" && Boolean(item.bodySw);\n  const title = sw && item.titleSw ? item.titleSw : item.title;\n  const body = sw ? item.bodySw : item.body;\n  const read = Boolean(feed.lessons[item.id]);\n  const related = LIBRARY.filter((c) => c.topic === item.topic && c.id !== item.id)\n    .sort((a, b) => b.priority - a.priority)\n    .slice(0, 3);\n\n  return (\n    <article className=\"stagger space-y-5\">\n      <div className=\"flex items-center justify-between\">\n        <Link href={back.href} className=\"flex items-center gap-1 text-sm text-ink-soft\">\n          <ArrowLeft size={16} /> {back.label}\n        </Link>\n        <BookmarkButton contentId={item.id} />\n      </div>\n\n      <div className=\"overflow-hidden rounded-[28px]\">\n        {item.kind === \"video\" ? (\n          <div className=\"relative\">\n            <Cover item={item} className=\"aspect-video w-full\" showPlay={false} />\n            <div className=\"absolute inset-0 flex flex-col items-center justify-center gap-2 bg-black/30 text-white\">\n              <PlayCircle size={44} />\n              <p className=\"text-sm font-semibold\">Video coming soon</p>\n              <p className=\"text-xs text-white/80\">Key points are below</p>\n            </div>\n          </div>\n        ) : (\n          <Cover item={item} className=\"aspect-[16/9] w-full\" />\n        )}\n      </div>\n\n      <header>\n        <p className=\"text-[11px] font-semibold uppercase tracking-wider text-forest\">\n          <Link href={`/social/topic/${item.topic}`} className=\"underline-offset-2 hover:underline\">\n            {topic?.title}\n          </Link>{\" \"}\n          · {KIND_LABEL[item.kind]} · {item.minutes} min\n        </p>\n        <h1 className=\"mt-2 text-[26px] font-bold leading-tight\">{title}</h1>\n        {!sw && <p className=\"mt-2 text-[15px] leading-relaxed text-ink-soft\">{item.summary}</p>}\n        <p className=\"mt-3 flex items-start gap-1.5 rounded-2xl bg-bg px-3 py-2 text-[11px] leading-snug text-ink-soft ring-1 ring-line\">\n          <ShieldCheck size={13} className=\"mt-px shrink-0 text-forest\" />\n          <span>\n            {item.source}\n            {item.fixture && \" · Sample content for development\"}\n          </span>\n        </p>\n        {(item.bodySw || item.origin) && (\n          <div className=\"mt-3 flex items-center justify-between gap-2\">\n            {item.bodySw ? (\n              <div className=\"inline-flex rounded-full bg-surface p-1 text-xs font-semibold ring-1 ring-line\" role=\"tablist\" aria-label=\"Language\">\n                {([\"en\", \"sw\"] as const).map((l) => (\n                  <button\n                    key={l}\n                    role=\"tab\"\n                    aria-selected={lang === l}\n                    onClick={() => setLang(l)}\n                    className={`rounded-full px-3 py-1.5 ${lang === l ? \"bg-forest text-white\" : \"text-ink-soft\"}`}\n                  >\n                    {l === \"en\" ? \"English\" : \"Kiswahili\"}\n                  </button>\n                ))}\n              </div>\n            ) : (\n              <span />\n            )}\n            {item.origin && (\n              <a\n                href={item.origin.url}\n                target=\"_blank\"\n                rel=\"noopener noreferrer\"\n                className=\"flex items-center gap-1 text-xs font-semibold text-forest\"\n              >\n                {item.origin.format === \"reel\" ? \"Watch on Instagram\" : \"View on Instagram\"} <ExternalLink size={12} />\n              </a>\n            )}\n          </div>\n        )}\n      </header>\n\n      {item.kind === \"expert\" && item.question && (\n        <blockquote className=\"flex gap-3 rounded-3xl bg-mint/60 p-4\">\n          <MessageCircle size={18} className=\"mt-0.5 shrink-0 text-forest\" />\n          <p className=\"text-sm font-medium italic text-forest-deep\">&ldquo;{item.question}&rdquo;</p>\n        </blockquote>\n      )}\n\n      {body && (\n        <div lang={sw ? \"sw\" : \"en\"} className=\"space-y-3 rounded-3xl bg-surface p-5 text-[15px] leading-relaxed ring-1 ring-line\">\n          {body.map((p, i) =>\n            p.startsWith(\"## \") ? (\n              <h2 key={i} className=\"pt-2 text-lg font-bold\">\n                {p.slice(3)}\n              </h2>\n            ) : (\n              <p key={i}>{p}</p>\n            ),\n          )}\n        </div>\n      )}\n\n      {item.keyPoints && (\n        <div className=\"rounded-3xl bg-surface p-5 ring-1 ring-line\">\n          <h2 className=\"font-bold\">Key points</h2>\n          <ol className=\"mt-3 space-y-2\">\n            {item.keyPoints.map((k, i) => (\n              <li key={i} className=\"flex gap-3 text-sm\">\n                <span className=\"flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-mint text-xs font-bold text-forest\">\n                  {i + 1}\n                </span>\n                {k}\n              </li>\n            ))}\n          </ol>\n        </div>\n      )}\n\n      {item.quiz && <QuizRunner questions={item.quiz} />}\n      {item.tool === \"pelvic-floor\" && <PelvicFloorTrainer />}\n      {item.tool === \"doctor-check\" && <DoctorCheck />}\n\n      {item.inManFeed && feed.ready && (\n        <button\n          onClick={() => {\n            if (read) return;\n            feedStore.markLessonRead(item.id);\n            showToast(`Lesson read · +${item.points ?? 10} points`);\n          }}\n          className={`flex w-full items-center justify-center gap-2 rounded-full py-3.5 text-sm font-semibold transition-transform active:scale-[0.98] ${\n            read ? \"bg-mint text-forest\" : \"bg-forest text-white\"\n          }`}\n        >\n          {read ? (\n            <>\n              <Check size={16} /> You&apos;ve read this\n            </>\n          ) : (\n            `Mark as read · +${item.points ?? 10} points`\n          )}\n        </button>\n      )}\n\n      <p className=\"px-2 text-center text-[11px] text-ink-soft\">General education, not medical advice.</p>\n\n      {related.length > 0 && (\n        <section className=\"space-y-3 pt-2\">\n          <h2 className=\"text-base font-bold\">More on {topic?.title.toLowerCase()}</h2>\n          {related.map((r) => (\n            <ContentRow key={r.id} item={r} />\n          ))}\n        </section>\n      )}\n    </article>\n  );\n}\n",
  "src/components/social/ContentTools.tsx": "\"use client\";\n\nimport { useEffect, useState } from \"react\";\nimport { Check, Pause, Play, RotateCcw, X } from \"lucide-react\";\nimport type { QuizQuestion } from \"@/lib/content/types\";\n\n/* ───────────── Quiz ───────────── */\nexport function QuizRunner({ questions }: { questions: QuizQuestion[] }) {\n  const [i, setI] = useState(0);\n  const [picked, setPicked] = useState<number | null>(null);\n  const [score, setScore] = useState(0);\n  const done = i >= questions.length;\n\n  if (done) {\n    return (\n      <div className=\"rounded-3xl bg-forest-deep p-6 text-center text-white\">\n        <p className=\"text-sm text-mint\">Your score</p>\n        <p className=\"mt-1 text-4xl font-bold\">\n          {score} / {questions.length}\n        </p>\n        <p className=\"mt-2 text-sm text-mint\">\n          {score === questions.length ? \"Excellent — you know your facts.\" : \"Good effort. Every answer above explains why.\"}\n        </p>\n        <button\n          onClick={() => {\n            setI(0);\n            setPicked(null);\n            setScore(0);\n          }}\n          className=\"mt-4 inline-flex items-center gap-2 rounded-full bg-white px-5 py-2.5 text-sm font-bold text-forest-deep\"\n        >\n          <RotateCcw size={15} /> Try again\n        </button>\n      </div>\n    );\n  }\n\n  const q = questions[i];\n  const answered = picked !== null;\n  return (\n    <div className=\"rounded-3xl bg-surface p-5 ring-1 ring-line\">\n      <div className=\"flex items-center justify-between text-xs text-ink-soft\">\n        <span>\n          Question {i + 1} of {questions.length}\n        </span>\n        <span>Score {score}</span>\n      </div>\n      <div className=\"mt-2 h-1.5 overflow-hidden rounded-full bg-mint\">\n        <div className=\"h-full rounded-full bg-forest transition-[width] duration-500\" style={{ width: `${(i / questions.length) * 100}%` }} />\n      </div>\n      <p className=\"mt-4 text-base font-semibold leading-snug\">{q.q}</p>\n      <div className=\"mt-3 grid grid-cols-2 gap-2\">\n        {q.options.map((o, idx) => {\n          const correct = idx === q.answer;\n          const chosen = picked === idx;\n          return (\n            <button\n              key={o}\n              disabled={answered}\n              onClick={() => {\n                setPicked(idx);\n                if (correct) setScore((s) => s + 1);\n              }}\n              className={`flex items-center justify-center gap-1.5 rounded-2xl py-3 text-sm font-semibold transition-colors ${\n                !answered\n                  ? \"ring-1 ring-line active:bg-mint\"\n                  : correct\n                    ? \"bg-forest text-white\"\n                    : chosen\n                      ? \"bg-red-50 text-red-700 ring-1 ring-red-200\"\n                      : \"text-ink-soft ring-1 ring-line\"\n              }`}\n            >\n              {answered && correct && <Check size={15} />}\n              {answered && chosen && !correct && <X size={15} />}\n              {o}\n            </button>\n          );\n        })}\n      </div>\n      {answered && (\n        <div className=\"page-enter mt-4\">\n          <p className=\"text-sm\">\n            <span className=\"font-semibold\">{picked === q.answer ? \"Correct. \" : \"Not quite. \"}</span>\n            {q.explain}\n          </p>\n          <button\n            onClick={() => {\n              setI((n) => n + 1);\n              setPicked(null);\n            }}\n            className=\"mt-4 w-full rounded-full bg-forest py-3 text-sm font-semibold text-white\"\n          >\n            {i + 1 === questions.length ? \"See my score\" : \"Next question\"}\n          </button>\n        </div>\n      )}\n    </div>\n  );\n}\n\n/* ───────────── Pelvic floor trainer ───────────── */\nconst HOLD = 3; // seconds squeeze, then seconds relax\nconst REPS = 10;\nconst TOTAL = REPS * HOLD * 2;\n\nexport function PelvicFloorTrainer() {\n  const [running, setRunning] = useState(false);\n  const [elapsed, setElapsed] = useState(0); // everything else is worked out from this\n\n  useEffect(() => {\n    if (!running) return;\n    const t = setInterval(() => setElapsed((e) => Math.min(e + 1, TOTAL)), 1000);\n    return () => clearInterval(t);\n  }, [running]);\n\n  const finished = elapsed >= TOTAL;\n  useEffect(() => {\n    if (finished) setRunning(false);\n  }, [finished]);\n\n  const rep = Math.min(Math.floor(elapsed / (HOLD * 2)) + 1, REPS);\n  const inCycle = elapsed % (HOLD * 2);\n  const phase = inCycle < HOLD ? \"Squeeze\" : \"Relax\";\n  const left = HOLD - (inCycle % HOLD);\n  const squeezing = running && phase === \"Squeeze\";\n\n  return (\n    <div className=\"rounded-3xl bg-surface p-6 text-center ring-1 ring-line\">\n      <div\n        className={`mx-auto flex h-40 w-40 items-center justify-center rounded-full transition-all duration-[2500ms] ease-in-out ${\n          squeezing ? \"scale-90 bg-forest text-white\" : \"scale-100 bg-mint text-forest-deep\"\n        }`}\n        aria-live=\"polite\"\n      >\n        <div>\n          <p className=\"text-lg font-bold\">{finished ? \"Done\" : running ? phase : elapsed ? \"Paused\" : \"Ready\"}</p>\n          {!finished && running && <p className=\"text-3xl font-bold tabular-nums\">{left}</p>}\n        </div>\n      </div>\n      <p className=\"mt-4 text-sm text-ink-soft\">\n        {finished ? \"Great work. Once or twice a day is plenty to start.\" : `Rep ${rep} of ${REPS}`}\n      </p>\n      <div className=\"mt-4 flex justify-center gap-2\">\n        {finished ? (\n          <button\n            onClick={() => setElapsed(0)}\n            className=\"inline-flex items-center gap-2 rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white\"\n          >\n            <RotateCcw size={15} /> Again\n          </button>\n        ) : (\n          <button\n            onClick={() => setRunning((r) => !r)}\n            className=\"inline-flex items-center gap-2 rounded-full bg-forest px-6 py-2.5 text-sm font-semibold text-white\"\n          >\n            {running ? <Pause size={15} /> : <Play size={15} />} {running ? \"Pause\" : elapsed ? \"Resume\" : \"Start\"}\n          </button>\n        )}\n      </div>\n      <ul className=\"mt-5 space-y-1 text-left text-xs text-ink-soft\">\n        <li>• Squeeze as if stopping yourself passing wind. Keep breathing.</li>\n        <li>• Don&apos;t tighten your stomach, legs or bottom.</li>\n        <li>• Stop if you feel pain, and speak to a doctor.</li>\n      </ul>\n    </div>\n  );\n}\n\n/* ───────────── Doctor check ───────────── */\nconst CHECKS = [\n  { q: \"Have erection or ejaculation problems lasted more than 3 months?\", weight: 1 },\n  { q: \"Did the problem start suddenly?\", weight: 1 },\n  { q: \"Do you have diabetes, high blood pressure or heart problems?\", weight: 2 },\n  { q: \"Do you get chest pain or get short of breath easily?\", weight: 3 },\n  { q: \"Is it causing you or your partner a lot of worry?\", weight: 1 },\n  { q: \"Do you take regular medicines that started around the same time?\", weight: 1 },\n];\n\nexport function DoctorCheck() {\n  const [answers, setAnswers] = useState<(boolean | null)[]>(CHECKS.map(() => null));\n  const complete = answers.every((a) => a !== null);\n  const urgent = answers[3] === true;\n  const score = answers.reduce((s, a, i) => s + (a ? CHECKS[i].weight : 0), 0);\n\n  return (\n    <div className=\"space-y-3\">\n      {CHECKS.map((c, i) => (\n        <div key={c.q} className=\"rounded-2xl bg-surface p-4 ring-1 ring-line\">\n          <p className=\"text-sm font-medium\">{c.q}</p>\n          <div className=\"mt-2 flex gap-2\">\n            {[true, false].map((v) => (\n              <button\n                key={String(v)}\n                aria-pressed={answers[i] === v}\n                onClick={() => setAnswers((a) => a.map((x, j) => (j === i ? v : x)))}\n                className={`flex-1 rounded-full py-2 text-sm font-semibold ${\n                  answers[i] === v ? \"bg-forest text-white\" : \"ring-1 ring-line\"\n                }`}\n              >\n                {v ? \"Yes\" : \"No\"}\n              </button>\n            ))}\n          </div>\n        </div>\n      ))}\n      {complete && (\n        <div\n          role=\"status\"\n          className={`page-enter rounded-3xl p-5 ${urgent ? \"bg-red-50 text-red-900 ring-1 ring-red-200\" : \"bg-forest-deep text-white\"}`}\n        >\n          <p className=\"font-bold\">\n            {urgent ? \"Please see a doctor soon\" : score >= 2 ? \"A check-up is a good idea\" : \"Keep an eye on it\"}\n          </p>\n          <p className={`mt-1 text-sm ${urgent ? \"\" : \"text-mint\"}`}>\n            {urgent\n              ? \"Chest pain or breathlessness should be checked by a doctor soon. If the pain is severe or sudden, go to a hospital straight away.\"\n              : score >= 2\n                ? \"Based on your answers, talking to a doctor could help find the cause and the right support. It's common and confidential.\"\n                : \"Small changes in sleep, stress and exercise often help. If things don't improve in a few weeks, see a doctor.\"}\n          </p>\n          <p className={`mt-3 text-[11px] ${urgent ? \"\" : \"text-mint/80\"}`}>\n            This is a simple guide, not a diagnosis. Your answers aren&apos;t saved.\n          </p>\n        </div>\n      )}\n    </div>\n  );\n}\n",
  "src/components/social/Cover.tsx": "import { Play } from \"lucide-react\";\nimport type { ContentItem } from \"@/lib/content/types\";\n\n// Editorial cover art drawn in brand colours. Placeholder until real photography\n// is uploaded through the Content Studio — then this is swapped for the image.\n\nconst TONES = {\n  forest: { bg: \"#0f5c46\", a: \"#1d7a5f\", b: \"#5dcaa5\", c: \"#dff3ea\" },\n  night: { bg: \"#06261d\", a: \"#0f4a39\", b: \"#2f9d78\", c: \"#9fe1cb\" },\n  mint: { bg: \"#dff3ea\", a: \"#bfe8d6\", b: \"#5dcaa5\", c: \"#0f5c46\" },\n  sand: { bg: \"#f1e8d8\", a: \"#e3d3b5\", b: \"#c9a86d\", c: \"#6b4f22\" },\n  clay: { bg: \"#efdcd0\", a: \"#e2bfa9\", b: \"#c98f6e\", c: \"#6e3519\" },\n} as const;\n\nexport default function Cover({\n  item,\n  className = \"\",\n  showPlay = true,\n}: {\n  item: Pick<ContentItem, \"cover\" | \"kind\" | \"id\">;\n  className?: string;\n  showPlay?: boolean;\n}) {\n  const t = TONES[item.cover.tone];\n  // small variation per item so covers with the same motif don't look identical\n  const seed = [...item.id].reduce((s, ch) => s + ch.charCodeAt(0), 0);\n  const shift = (seed % 40) - 20;\n\n  return (\n    <div className={`relative overflow-hidden ${className}`} style={{ background: t.bg }} aria-hidden=\"true\">\n      <svg viewBox=\"0 0 400 300\" preserveAspectRatio=\"xMidYMid slice\" className=\"absolute inset-0 h-full w-full\">\n        {item.cover.motif === \"rings\" && (\n          <g fill=\"none\" strokeWidth=\"18\">\n            <circle cx={290 + shift} cy=\"120\" r=\"150\" stroke={t.a} />\n            <circle cx={290 + shift} cy=\"120\" r=\"100\" stroke={t.b} opacity=\"0.7\" />\n            <circle cx={290 + shift} cy=\"120\" r=\"50\" stroke={t.c} opacity=\"0.85\" />\n          </g>\n        )}\n        {item.cover.motif === \"waves\" && (\n          <g fill=\"none\" strokeWidth=\"14\" strokeLinecap=\"round\">\n            {[0, 1, 2, 3].map((i) => (\n              <path\n                key={i}\n                d={`M-20 ${150 + i * 38} C 80 ${100 + i * 38 + shift}, 180 ${210 + i * 38}, 420 ${130 + i * 38}`}\n                stroke={i % 2 ? t.b : t.a}\n                opacity={1 - i * 0.12}\n              />\n            ))}\n            <circle cx={320 + shift} cy=\"70\" r=\"26\" fill={t.c} stroke=\"none\" />\n          </g>\n        )}\n        {item.cover.motif === \"arc\" && (\n          <g>\n            <path d={`M-40 300 A 260 260 0 0 1 ${440 + shift} 300`} fill={t.a} />\n            <path d={`M40 300 A 180 180 0 0 1 ${360 + shift} 300`} fill={t.b} opacity=\"0.8\" />\n            <circle cx={300 + shift} cy=\"70\" r=\"34\" fill={t.c} />\n          </g>\n        )}\n        {item.cover.motif === \"grid\" && (\n          <g>\n            {Array.from({ length: 6 }).map((_, r) =>\n              Array.from({ length: 8 }).map((__, c) => (\n                <circle key={`${r}-${c}`} cx={40 + c * 48} cy={30 + r * 48} r=\"5\" fill={t.a} />\n              )),\n            )}\n            <rect x={210 + shift} y=\"80\" width=\"150\" height=\"150\" rx=\"36\" fill={t.b} opacity=\"0.85\" />\n            <rect x={250 + shift} y=\"120\" width=\"70\" height=\"70\" rx=\"18\" fill={t.c} />\n          </g>\n        )}\n        {item.cover.motif === \"dots\" && (\n          <g>\n            <circle cx={90 + shift} cy=\"210\" r=\"120\" fill={t.a} />\n            <circle cx={300} cy={90 + shift} r=\"70\" fill={t.b} opacity=\"0.85\" />\n            <circle cx={330} cy=\"230\" r=\"28\" fill={t.c} />\n            <circle cx={200 + shift} cy=\"60\" r=\"12\" fill={t.c} opacity=\"0.8\" />\n          </g>\n        )}\n      </svg>\n      {showPlay && item.kind === \"video\" && (\n        <span className=\"absolute inset-0 flex items-center justify-center\">\n          <span className=\"flex h-12 w-12 items-center justify-center rounded-full bg-white/90 text-forest-deep shadow-lg\">\n            <Play size={20} fill=\"currentColor\" />\n          </span>\n        </span>\n      )}\n    </div>\n  );\n}\n",
  "src/components/social/Discover.tsx": "\"use client\";\n\nimport { useState } from \"react\";\nimport { SlidersHorizontal } from \"lucide-react\";\nimport FeaturedCard from \"./FeaturedCard\";\nimport { SectionRow } from \"./ContentCards\";\nimport InterestsSheet from \"./InterestsSheet\";\nimport { LIBRARY, TOPICS } from \"@/lib/content/library\";\nimport { orderSections, pickFeatured, sectionItems } from \"@/lib/content/select\";\nimport { useSocial } from \"@/lib/social/store\";\n\nexport function DiscoverSkeleton() {\n  return (\n    <div className=\"space-y-4\" aria-busy=\"true\" aria-label=\"Loading\">\n      <div className=\"h-[460px] animate-pulse rounded-[28px] bg-forest-deep/15\" />\n      <div className=\"h-5 w-40 animate-pulse rounded-full bg-line\" />\n      <div className=\"flex gap-3\">\n        <div className=\"h-44 w-44 animate-pulse rounded-3xl bg-surface ring-1 ring-line\" />\n        <div className=\"h-44 w-44 animate-pulse rounded-3xl bg-surface ring-1 ring-line\" />\n      </div>\n    </div>\n  );\n}\n\nexport default function Discover() {\n  const { interests, ready } = useSocial();\n  const [pickTopics, setPickTopics] = useState(false);\n\n  if (!ready) return <DiscoverSkeleton />;\n\n  const featured = pickFeatured(interests, LIBRARY);\n  if (!featured) {\n    return (\n      <div className=\"rounded-3xl bg-surface p-8 text-center ring-1 ring-line\">\n        <p className=\"font-semibold\">No content yet</p>\n        <p className=\"mt-1 text-sm text-ink-soft\">New guides and answers will appear here soon.</p>\n      </div>\n    );\n  }\n\n  const followed = TOPICS.filter((t) => interests.includes(t.id) && t.id === featured.topic);\n  const reason = followed.length\n    ? `Picked for you because you follow ${followed[0].title}.`\n    : \"Picked by our editors as this week's most useful read.\";\n\n  return (\n    <div className=\"stagger space-y-7\">\n      <FeaturedCard item={featured} reason={reason} />\n\n      {/* Personalise */}\n      <button\n        onClick={() => setPickTopics(true)}\n        className=\"flex w-full items-center justify-between rounded-2xl bg-mint/60 px-4 py-3 text-left\"\n      >\n        <span>\n          <span className=\"block text-sm font-semibold text-forest-deep\">\n            {interests.length ? `Following ${interests.length} ${interests.length === 1 ? \"topic\" : \"topics\"}` : \"Make Discover yours\"}\n          </span>\n          <span className=\"block text-xs text-forest\">\n            {interests.length\n              ? TOPICS.filter((t) => interests.includes(t.id)).map((t) => t.short).join(\" · \")\n              : \"Choose the topics you care about\"}\n          </span>\n        </span>\n        <SlidersHorizontal size={18} className=\"shrink-0 text-forest\" />\n      </button>\n\n      {orderSections(interests).map((s) => (\n        <SectionRow key={s.id} id={s.id} title={s.title} blurb={s.blurb} items={sectionItems(s.id, featured.id)} />\n      ))}\n\n      <p className=\"px-2 text-center text-[11px] leading-relaxed text-ink-soft\">\n        All content here is general education, not medical advice. Items marked &quot;Sample&quot; are drafts that will be\n        reviewed by a qualified health professional before launch.\n      </p>\n\n      <InterestsSheet open={pickTopics} onClose={() => setPickTopics(false)} current={interests} />\n    </div>\n  );\n}\n",
  "src/components/social/FeaturedCard.tsx": "\"use client\";\n\nimport Link from \"next/link\";\nimport { ArrowRight, ShieldCheck } from \"lucide-react\";\nimport Cover from \"./Cover\";\nimport BookmarkButton from \"./BookmarkButton\";\nimport { contentHref } from \"./ContentCards\";\nimport { CTA_LABEL, KIND_LABEL } from \"@/lib/content/select\";\nimport { TOPICS } from \"@/lib/content/library\";\nimport type { ContentItem } from \"@/lib/content/types\";\n\n/** The one big piece of content at the top of Discover. */\nexport default function FeaturedCard({ item, reason }: { item: ContentItem; reason: string }) {\n  const topic = TOPICS.find((t) => t.id === item.topic)?.title;\n  return (\n    <article className=\"overflow-hidden rounded-[28px] bg-forest-deep text-white\">\n      <Link href={contentHref(item.id)} className=\"block\" aria-label={item.title}>\n        <div className=\"relative\">\n          <Cover item={item} className=\"aspect-[4/3] w-full\" />\n          <div className=\"absolute left-4 top-4 flex gap-2\">\n            <span className=\"rounded-full bg-white/90 px-3 py-1 text-[11px] font-bold text-forest-deep\">Featured</span>\n            {item.fixture && (\n              <span className=\"rounded-full bg-black/35 px-3 py-1 text-[11px] font-semibold text-white backdrop-blur\">\n                Sample content\n              </span>\n            )}\n          </div>\n        </div>\n      </Link>\n\n      <div className=\"p-5\">\n        <p className=\"text-[11px] font-semibold uppercase tracking-wider text-mint-strong\">\n          {topic} · {KIND_LABEL[item.kind]} · {item.minutes} min read\n        </p>\n        <Link href={contentHref(item.id)}>\n          <h2 className=\"mt-2 text-[24px] font-bold leading-tight\">{item.title}</h2>\n        </Link>\n        <p className=\"mt-2 text-sm leading-relaxed text-mint\">{item.summary}</p>\n\n        <p className=\"mt-3 flex items-start gap-1.5 text-[11px] leading-snug text-mint/80\">\n          <ShieldCheck size={13} className=\"mt-px shrink-0\" />\n          {item.source}\n        </p>\n\n        <div className=\"mt-4 flex items-center gap-2\">\n          <Link\n            href={contentHref(item.id)}\n            className=\"flex flex-1 items-center justify-center gap-2 rounded-full bg-white py-3 text-sm font-bold text-forest-deep transition-transform active:scale-[0.98]\"\n          >\n            {CTA_LABEL[item.kind]} <ArrowRight size={16} />\n          </Link>\n          <BookmarkButton contentId={item.id} variant=\"dark\" />\n        </div>\n        <p className=\"mt-3 text-[11px] text-mint/70\">{reason}</p>\n      </div>\n    </article>\n  );\n}\n",
  "src/components/social/InterestsSheet.tsx": "\"use client\";\n\nimport { useEffect, useState } from \"react\";\nimport { Check } from \"lucide-react\";\nimport Sheet from \"@/components/motion/Sheet\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { TOPICS } from \"@/lib/content/library\";\nimport type { TopicId } from \"@/lib/content/types\";\nimport { socialStore } from \"@/lib/social/store\";\n\nexport default function InterestsSheet({\n  open,\n  onClose,\n  current,\n}: {\n  open: boolean;\n  onClose: () => void;\n  current: TopicId[];\n}) {\n  const showToast = useToast();\n  const [picked, setPicked] = useState<TopicId[]>(current);\n  useEffect(() => {\n    if (open) setPicked(current);\n  }, [open, current]);\n\n  const toggle = (id: TopicId) => setPicked((p) => (p.includes(id) ? p.filter((x) => x !== id) : [...p, id]));\n\n  return (\n    <Sheet open={open} onClose={onClose} title=\"Topics you care about\">\n      <p className=\"text-xs text-ink-soft\">\n        We use these to choose what to feature first. Saved on this phone only and never shared.\n      </p>\n      <div className=\"mt-4 flex flex-wrap gap-2\">\n        {TOPICS.map((t) => {\n          const on = picked.includes(t.id);\n          return (\n            <button\n              key={t.id}\n              aria-pressed={on}\n              onClick={() => toggle(t.id)}\n              className={`flex items-center gap-1.5 rounded-full px-3.5 py-2 text-xs font-semibold transition-colors ${\n                on ? \"bg-forest text-white\" : \"ring-1 ring-line\"\n              }`}\n            >\n              {on && <Check size={13} />} {t.title}\n            </button>\n          );\n        })}\n      </div>\n      <div className=\"mt-5 flex justify-end gap-2\">\n        <button onClick={onClose} className=\"rounded-full px-5 py-2.5 text-sm font-semibold ring-1 ring-line\">\n          Cancel\n        </button>\n        <button\n          onClick={() => {\n            socialStore.setInterests(picked);\n            showToast(picked.length ? \"Discover updated for your topics\" : \"Showing editor's picks\");\n            onClose();\n          }}\n          className=\"rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white\"\n        >\n          Save\n        </button>\n      </div>\n    </Sheet>\n  );\n}\n",
  "src/components/social/PostCard.tsx": "\"use client\";\n\nimport { useState } from \"react\";\nimport Link from \"next/link\";\nimport { Flag, MessageCircle, Stethoscope, UserRound, VenetianMask } from \"lucide-react\";\nimport ReactionBar from \"./ReactionBar\";\nimport ReportSheet from \"./ReportSheet\";\nimport { timeAgo, topicLabel, type Author, type Post } from \"@/lib/social/community\";\n\nexport function AuthorLine({ author, at, fixture, mine }: { author: Author; at: string; fixture?: boolean; mine?: boolean }) {\n  return (\n    <p className=\"flex flex-wrap items-center gap-x-1.5 gap-y-1 text-[11px] text-ink-soft\">\n      <span className=\"flex h-5 w-5 items-center justify-center rounded-full bg-mint text-forest\">\n        {author.anonymous ? <VenetianMask size={11} /> : <UserRound size={11} />}\n      </span>\n      <span className=\"font-semibold text-ink\">{mine ? `${author.name} (you)` : author.name}</span>\n      <span>· {timeAgo(at)}</span>\n      {fixture && <span className=\"rounded-full bg-bg px-2 py-0.5 font-semibold ring-1 ring-line\">Sample</span>}\n    </p>\n  );\n}\n\nexport default function PostCard({ post, replyCount }: { post: Post; replyCount: number }) {\n  const [reporting, setReporting] = useState(false);\n  return (\n    <article className=\"rounded-3xl bg-surface p-4 ring-1 ring-line\">\n      <div className=\"flex items-start justify-between gap-2\">\n        <AuthorLine author={post.author} at={post.createdAt} fixture={post.fixture} mine={post.mine} />\n        {!post.mine && (\n          <button\n            aria-label=\"Report post\"\n            onClick={() => setReporting(true)}\n            className=\"-mr-1 -mt-1 flex h-8 w-8 items-center justify-center rounded-full text-ink-soft\"\n          >\n            <Flag size={14} />\n          </button>\n        )}\n      </div>\n\n      <Link href={`/social/post/${post.id}`} className=\"mt-2 block\">\n        <p className=\"text-[11px] font-semibold uppercase tracking-wide text-forest\">{topicLabel(post.topic)}</p>\n        <h3 className=\"mt-0.5 text-[15px] font-bold leading-snug\">{post.title}</h3>\n        {post.body && <p className=\"mt-1 line-clamp-3 text-sm text-ink-soft\">{post.body}</p>}\n        {post.wantsExpert && (\n          <p className=\"mt-2 inline-flex items-center gap-1 rounded-full bg-bg px-2.5 py-1 text-[11px] font-medium text-ink-soft ring-1 ring-line\">\n            <Stethoscope size={12} /> Waiting for a verified expert\n          </p>\n        )}\n      </Link>\n\n      <div className=\"mt-3 flex items-center justify-between gap-2\">\n        <ReactionBar targetId={post.id} base={post.baseReactions} compact />\n        <Link\n          href={`/social/post/${post.id}`}\n          className=\"flex shrink-0 items-center gap-1 rounded-full px-2.5 py-1 text-[11px] font-semibold text-forest ring-1 ring-line\"\n        >\n          <MessageCircle size={13} /> {replyCount ? `${replyCount} ${replyCount === 1 ? \"reply\" : \"replies\"}` : \"Reply\"}\n        </Link>\n      </div>\n\n      <ReportSheet targetId={post.id} open={reporting} onClose={() => setReporting(false)} />\n    </article>\n  );\n}\n",
  "src/components/social/ReactionBar.tsx": "\"use client\";\n\nimport { reactionCount, REACTIONS, type ReactionKind } from \"@/lib/social/community\";\nimport { socialStore, useSocial } from \"@/lib/social/store\";\n\nexport default function ReactionBar({\n  targetId,\n  base,\n  compact = false,\n}: {\n  targetId: string;\n  base?: Partial<Record<ReactionKind, number>>;\n  compact?: boolean;\n}) {\n  const { reactions } = useSocial();\n  const mine = reactions[targetId];\n  return (\n    <div className=\"flex flex-wrap gap-1.5\">\n      {REACTIONS.map((r) => {\n        const on = Boolean(mine?.includes(r.kind));\n        const n = reactionCount(base, mine, r.kind);\n        return (\n          <button\n            key={r.kind}\n            aria-pressed={on}\n            aria-label={`${r.label}${n ? `, ${n}` : \"\"}`}\n            onClick={(e) => {\n              e.preventDefault();\n              e.stopPropagation();\n              socialStore.react(targetId, r.kind);\n            }}\n            className={`flex items-center gap-1 rounded-full px-2.5 py-1 text-[11px] font-semibold transition-all active:scale-95 ${\n              on ? \"bg-mint text-forest-deep ring-1 ring-mint-strong\" : \"text-ink-soft ring-1 ring-line\"\n            }`}\n          >\n            <span aria-hidden=\"true\">{r.emoji}</span>\n            {!compact && <span>{r.label}</span>}\n            {n > 0 && <span className=\"tabular-nums\">{n}</span>}\n          </button>\n        );\n      })}\n    </div>\n  );\n}\n",
  "src/components/social/ReportSheet.tsx": "\"use client\";\n\nimport { useState } from \"react\";\nimport Sheet from \"@/components/motion/Sheet\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { REPORT_REASONS } from \"@/lib/social/community\";\nimport { socialStore } from \"@/lib/social/store\";\n\n/** Report a post or reply. It's hidden for him straight away and queued for moderators. */\nexport default function ReportSheet({\n  targetId,\n  open,\n  onClose,\n  onReported,\n}: {\n  targetId: string;\n  open: boolean;\n  onClose: () => void;\n  onReported?: () => void;\n}) {\n  const showToast = useToast();\n  const [reason, setReason] = useState<string>(\"\");\n  const [error, setError] = useState(\"\");\n\n  return (\n    <Sheet open={open} onClose={onClose} title=\"Report\">\n      <p className=\"text-xs text-ink-soft\">\n        Tell us what&apos;s wrong. It will be hidden for you now and sent to our moderators. The person won&apos;t know who\n        reported it.\n      </p>\n      <div className=\"mt-3 space-y-1.5\" role=\"radiogroup\" aria-label=\"Reason\">\n        {REPORT_REASONS.map((r) => (\n          <button\n            key={r}\n            role=\"radio\"\n            aria-checked={reason === r}\n            onClick={() => {\n              setReason(r);\n              setError(\"\");\n            }}\n            className={`w-full rounded-2xl px-4 py-2.5 text-left text-sm ${\n              reason === r ? \"bg-forest text-white\" : \"ring-1 ring-line\"\n            }`}\n          >\n            {r}\n          </button>\n        ))}\n      </div>\n      {error && <p className=\"mt-2 text-xs text-red-600\">{error}</p>}\n      <div className=\"mt-4 flex justify-end gap-2\">\n        <button onClick={onClose} className=\"rounded-full px-5 py-2.5 text-sm font-semibold ring-1 ring-line\">\n          Cancel\n        </button>\n        <button\n          onClick={() => {\n            if (!reason) return setError(\"Choose a reason first.\");\n            socialStore.report(targetId, reason);\n            showToast(\"Reported. Thanks for keeping the community safe.\");\n            setReason(\"\");\n            onClose();\n            onReported?.();\n          }}\n          className=\"rounded-full bg-red-600 px-5 py-2.5 text-sm font-semibold text-white\"\n        >\n          Report\n        </button>\n      </div>\n    </Sheet>\n  );\n}\n",
  "src/components/social/SearchPanel.tsx": "\"use client\";\n\nimport { useEffect, useRef, useState } from \"react\";\nimport { Search, X } from \"lucide-react\";\nimport { ContentRow } from \"./ContentCards\";\nimport PostCard from \"./PostCard\";\nimport { useCommunity } from \"./useCommunity\";\nimport { searchContent } from \"@/lib/content/select\";\nimport { topicLabel } from \"@/lib/social/community\";\nimport { TOPICS } from \"@/lib/content/library\";\n\nconst norm = (s: string) => s.toLowerCase();\n\n/** Search Discover content or Community posts, depending on the tab he's on. */\nexport default function SearchPanel({ tab, onClose }: { tab: \"discover\" | \"community\"; onClose: () => void }) {\n  const [q, setQ] = useState(\"\");\n  const input = useRef<HTMLInputElement>(null);\n  const c = useCommunity();\n  useEffect(() => input.current?.focus(), []);\n\n  const words = norm(q).split(/\\s+/).filter((w) => w.length > 1);\n  const content = tab === \"discover\" ? searchContent(q) : [];\n  const posts =\n    tab === \"community\" && words.length\n      ? c\n          .list(\"active\", \"all\")\n          .filter(({ post }) => {\n            const text = norm(`${post.title} ${post.body} ${topicLabel(post.topic)}`);\n            return words.every((w) => text.includes(w));\n          })\n      : [];\n\n  const results = tab === \"discover\" ? content.length : posts.length;\n\n  return (\n    <div className=\"space-y-4\">\n      <div className=\"flex items-center gap-2\">\n        <label className=\"flex flex-1 items-center gap-2 rounded-full bg-surface px-4 ring-1 ring-line focus-within:ring-2 focus-within:ring-forest\">\n          <Search size={16} className=\"text-ink-soft\" />\n          <input\n            ref={input}\n            value={q}\n            onChange={(e) => setQ(e.target.value)}\n            onKeyDown={(e) => e.key === \"Escape\" && onClose()}\n            placeholder={tab === \"discover\" ? \"Search guides, answers, tools\" : \"Search conversations\"}\n            aria-label=\"Search\"\n            className=\"h-11 flex-1 bg-transparent text-sm outline-none\"\n          />\n          {q && (\n            <button aria-label=\"Clear search\" onClick={() => setQ(\"\")} className=\"text-ink-soft\">\n              <X size={16} />\n            </button>\n          )}\n        </label>\n        <button onClick={onClose} className=\"text-sm font-semibold text-forest\">\n          Cancel\n        </button>\n      </div>\n\n      {!words.length ? (\n        tab === \"discover\" ? (\n          <div>\n            <p className=\"text-xs font-semibold text-ink-soft\">Try a topic</p>\n            <div className=\"mt-2 flex flex-wrap gap-2\">\n              {[...TOPICS.map((t) => t.short), \"Pelvic floor\", \"Fertility\", \"Sleep\"].map((s) => (\n                <button key={s} onClick={() => setQ(s)} className=\"rounded-full px-3 py-1.5 text-xs font-semibold ring-1 ring-line\">\n                  {s}\n                </button>\n              ))}\n            </div>\n          </div>\n        ) : (\n          <p className=\"text-sm text-ink-soft\">Type a word, like &quot;nerves&quot; or &quot;walking&quot;.</p>\n        )\n      ) : results === 0 ? (\n        <div className=\"rounded-3xl bg-surface p-8 text-center ring-1 ring-line\">\n          <p className=\"font-semibold\">No results for &quot;{q.trim()}&quot;</p>\n          <p className=\"mt-1 text-sm text-ink-soft\">\n            {tab === \"discover\" ? \"Try a simpler word, or browse the topics.\" : \"Try another word, or ask the community.\"}\n          </p>\n        </div>\n      ) : (\n        <div className=\"space-y-3\">\n          <p className=\"text-xs text-ink-soft\" aria-live=\"polite\">\n            {results} {results === 1 ? \"result\" : \"results\"}\n          </p>\n          {tab === \"discover\"\n            ? content.map((item) => <ContentRow key={item.id} item={item} />)\n            : posts.map(({ post, replyCount }) => <PostCard key={post.id} post={post} replyCount={replyCount} />)}\n        </div>\n      )}\n    </div>\n  );\n}\n",
  "src/components/social/useCommunity.ts": "\"use client\";\n\nimport { activityScore, reactionCount, REACTIONS, type Post, type Reply } from \"@/lib/social/community\";\nimport { SAMPLE_POSTS, SAMPLE_REPLIES } from \"@/lib/social/fixtures\";\nimport { useSocial } from \"@/lib/social/store\";\n\n/** His posts + sample posts, minus anything he reported, with reply and reaction counts. */\nexport function useCommunity() {\n  const s = useSocial();\n\n  const replies: Reply[] = [...SAMPLE_REPLIES, ...s.replies].filter((r) => !s.reports[r.id]);\n  const posts: Post[] = [...s.posts, ...SAMPLE_POSTS].filter((p) => !s.reports[p.id]);\n\n  const repliesFor = (postId: string) =>\n    replies.filter((r) => r.postId === postId).sort((a, b) => a.createdAt.localeCompare(b.createdAt));\n\n  const totalReactions = (id: string, base: Post[\"baseReactions\"]) =>\n    REACTIONS.reduce((n, r) => n + reactionCount(base, s.reactions[id], r.kind), 0);\n\n  const withCounts = posts.map((p) => ({\n    post: p,\n    replyCount: repliesFor(p.id).length,\n    reactionTotal: totalReactions(p.id, p.baseReactions),\n  }));\n\n  return {\n    ready: s.ready,\n    nickname: s.nickname,\n    myReactions: s.reactions,\n    reportedCount: Object.keys(s.reports).length,\n    list(sort: \"new\" | \"active\", topic: string | \"all\") {\n      return withCounts\n        .filter((x) => topic === \"all\" || x.post.topic === topic)\n        .sort((a, b) =>\n          sort === \"new\"\n            ? b.post.createdAt.localeCompare(a.post.createdAt)\n            : activityScore(b.replyCount, b.reactionTotal) - activityScore(a.replyCount, a.reactionTotal),\n        );\n    },\n    getPost: (id: string) => posts.find((p) => p.id === id),\n    repliesFor,\n    isReported: (id: string) => Boolean(s.reports[id]),\n  };\n}\n\nexport type CommunityData = ReturnType<typeof useCommunity>;\n",
  "src/lib/content/instagram.ts": "// Content adapted from the Kayani Herbs Instagram page (account \"Mimea Tiba\").\n// Rules applied to every post before it goes in the app:\n// - Keep the useful education; remove product promotion, prices, phone numbers and testimonials\n// - Remove cure claims (\"unatibu kabisa\", \"huponya\") and anything not supported by evidence\n// - Add when to see a doctor\n// - Marked draft until reviewed by a qualified health professional\n\nimport type { ContentItem } from \"./types\";\n\nconst IG_SOURCE = \"Adapted from Kayani Herbs on Instagram · Draft, pending review by a qualified health professional\";\n\nexport const INSTAGRAM_CONTENT: ContentItem[] = [\n  {\n    id: \"ig-eating-day-calm-stomach\",\n    kind: \"guide\",\n    topic: \"wellbeing\",\n    title: \"A simple eating day for a calmer stomach\",\n    titleSw: \"Ratiba rahisi ya kula kwa tumbo lililotulia\",\n    summary: \"Rumbling, gas and feeling full all day? Start with what you eat and when. A practical day plan using everyday Tanzanian food.\",\n    minutes: 4,\n    priority: 82,\n    tags: [\"digestion\", \"gas\", \"bloating\", \"constipation\", \"meal plan\", \"tumbo\", \"chakula\"],\n    source: IG_SOURCE,\n    review: \"draft\",\n    fixture: false,\n    origin: { platform: \"instagram\", url: \"https://www.instagram.com/reel/DeMpLfKCb4B/\", postedAt: \"2026-10-07\", format: \"reel\" },\n    cover: { tone: \"sand\", motif: \"grid\" },\n    body: [\n      \"A stomach that rumbles, fills with gas, or doesn't empty properly can leave you tired and uncomfortable all day. Before looking for medicine, start with what goes into your stomach every day.\",\n      \"## Morning (6–7 am)\",\n      \"Drink water first, before tea full of sugar and mandazi. Then eat: 1–2 eggs, avocado, papaya or another fruit, and uji of millet or sorghum. Eat slowly and chew well — the aim is not to stuff yourself.\",\n      \"## Mid-morning (10–11 am), if hungry\",\n      \"Skip chips, soda and biscuits. Have one fruit, such as papaya, an orange or a ripe banana, and keep sipping water.\",\n      \"## Lunch (12–2 pm)\",\n      \"Build your plate: half vegetables, a quarter protein (fish, chicken, eggs or beans if they suit you), and a quarter rice, ugali, potatoes or plantain. Eat until you're comfortably full — not until you can't walk. Afterwards, don't lie down: walk for 10–15 minutes.\",\n      \"## Late afternoon (4–5 pm)\",\n      \"If you're hungry, keep it light: fruit, avocado, a few groundnuts, or low-sugar yoghurt if your stomach handles it.\",\n      \"## Evening (7–8 pm)\",\n      \"Let your stomach rest. Fish, chicken or eggs with vegetables, or a small portion of ugali or potatoes with vegetables and protein. Try to leave 2–3 hours before you sleep.\",\n      \"## Cut down on\",\n      \"Lots of soda, alcohol, chips and deep-fried food, too much sugar, fast food, very big meals, eating fast, and heavy food late at night.\",\n      \"## Every body is different\",\n      \"Don't blame yourself if a food like beans, milk or onions gives you gas. Notice which foods affect you and adjust.\",\n      \"## When to see a doctor\",\n      \"See a doctor if you have blood in your stool, black stools, weight loss without trying, vomiting, strong pain that doesn't go away, or if these problems last more than a few weeks.\",\n    ],\n    bodySw: [\n      \"Tumbo linalounguruma, kujaa gesi au choo kutotoka vizuri kunaweza kukufanya uchoke na usijisikie vizuri siku nzima. Kabla ya kutafuta dawa, anza na kile unachokiingiza tumboni kila siku.\",\n      \"## Asubuhi (saa 12–1)\",\n      \"Kunywa maji kwanza, kabla ya chai yenye sukari nyingi na maandazi. Kisha kula: mayai 1–2, parachichi, papai au tunda lingine, na uji wa ulezi au mtama. Kula taratibu na tafuna vizuri — lengo si kushiba kupita kiasi.\",\n      \"## Saa 4–5 asubuhi, kama una njaa\",\n      \"Usikimbilie chipsi, soda au biskuti. Chukua tunda moja, kama papai, chungwa au ndizi mbivu, na endelea kunywa maji kidogo kidogo.\",\n      \"## Mchana (saa 6–8)\",\n      \"Panga sahani yako: nusu mboga, robo protini (samaki, kuku, mayai au maharage kama yanakufaa), na robo wali, ugali, viazi au ndizi. Kula mpaka ushibe vizuri — si mpaka ushindwe kutembea. Baada ya kula usilale: tembea dakika 10–15.\",\n      \"## Jioni (saa 10–11)\",\n      \"Kama una njaa, kula kitu chepesi: tunda, parachichi, karanga kiasi, au mtindi usio na sukari nyingi kama tumbo lako linauvumilia.\",\n      \"## Usiku (saa 1–2)\",\n      \"Acha tumbo lipumzike. Samaki, kuku au mayai pamoja na mboga, au ugali/viazi kidogo pamoja na mboga na protini. Jaribu kuacha masaa 2–3 kabla ya kulala.\",\n      \"## Punguza\",\n      \"Soda nyingi, pombe, chipsi na vyakula vya kukaanga sana, sukari nyingi, fast food, milo mikubwa sana, kula kwa haraka, na chakula kizito usiku.\",\n      \"## Kila mwili ni tofauti\",\n      \"Usijilaumu kama chakula fulani kama maharage, maziwa au vitunguu kinakupa gesi. Angalia vyakula vinavyokuathiri na ubadilishe.\",\n      \"## Wakati wa kumwona daktari\",\n      \"Mwone daktari ukiona damu kwenye choo, choo cheusi, kupungua uzito bila sababu, kutapika, maumivu makali yasiyoisha, au kama tatizo linaendelea zaidi ya wiki chache.\",\n    ],\n  },\n  {\n    id: \"ig-strength-starts-daily\",\n    kind: \"article\",\n    topic: \"erection\",\n    title: \"Sexual strength starts with your daily health\",\n    titleSw: \"Nguvu za kiume zinaanzia kwenye afya yako ya kila siku\",\n    summary: \"Low desire, weak erections or tiring quickly often start outside the bedroom. Here's where to begin.\",\n    minutes: 2,\n    priority: 78,\n    tags: [\"nguvu za kiume\", \"erection\", \"desire\", \"lifestyle\", \"stamina\"],\n    source: IG_SOURCE,\n    review: \"draft\",\n    fixture: false,\n    origin: { platform: \"instagram\", url: \"https://www.instagram.com/p/DdyoemfghfF/\", postedAt: \"2026-09-27\", format: \"carousel\" },\n    cover: { tone: \"forest\", motif: \"arc\" },\n    body: [\n      \"Sexual strength doesn't start in the bedroom — it starts with how you live every day.\",\n      \"If desire has dropped, erections are weaker, or you tire quickly, begin with the basics: eat well, drink enough water, move your body, sleep enough, and cut down on alcohol and heavily processed food.\",\n      \"Don't ignore other health problems that may be going on. Blood pressure, blood sugar, stress and stomach problems can all affect how you feel.\",\n      \"If things don't improve after a few weeks of better habits, or if problems started suddenly, see a doctor. It's common, and doctors deal with it every day.\",\n      \"Good health begins with the small things you do each day.\",\n    ],\n    bodySw: [\n      \"Nguvu za kiume hazianzi chumbani — zinaanzia kwenye jinsi unavyoishi kila siku.\",\n      \"Kama hamu ya tendo imepungua, uume unasimama legelege au unachoka haraka, anza na misingi: kula vizuri, kunywa maji ya kutosha, fanya mazoezi, pata usingizi wa kutosha, na punguza pombe na vyakula vilivyosindikwa sana.\",\n      \"Usipuuze changamoto nyingine za kiafya zinazoendelea. Presha, sukari, msongo wa mawazo na matatizo ya tumbo vinaweza kuathiri jinsi unavyojisikia.\",\n      \"Kama hali haibadiliki baada ya wiki kadhaa za kuboresha tabia hizi, au kama tatizo lilianza ghafla, mwone daktari. Ni jambo la kawaida, na madaktari wanalishughulikia kila siku.\",\n      \"Afya nzuri huanzia kwenye mambo madogo unayofanya kila siku.\",\n    ],\n  },\n  {\n    id: \"ig-second-round\",\n    kind: \"guide\",\n    topic: \"ejaculation\",\n    title: \"Going again: the time between rounds\",\n    titleSw: \"Kurudia tendo: muda kati ya raundi\",\n    summary: \"Why your body needs a break after finishing, and five simple things that help you be ready again.\",\n    minutes: 3,\n    priority: 74,\n    tags: [\"round two\", \"kurudia tendo\", \"stamina\", \"recovery\", \"raundi\"],\n    source: IG_SOURCE,\n    review: \"draft\",\n    fixture: false,\n    origin: { platform: \"instagram\", url: \"https://www.instagram.com/p/DeKaV0iAuai/\", postedAt: \"2026-10-06\", format: \"carousel\" },\n    cover: { tone: \"night\", motif: \"waves\" },\n    body: [\n      \"After finishing, every man's body needs a rest before it can respond again. This pause is normal. It's usually shorter for younger men and gets longer with age.\",\n      \"## 1. Rest, but stay close\",\n      \"Don't turn over and sleep straight away. Keep touching, kissing and enjoying your partner while your body recovers. Closeness helps you both.\",\n      \"## 2. Drink water and breathe calmly\",\n      \"Being well hydrated and breathing slowly helps you feel refreshed.\",\n      \"## 3. Slow down in the first round\",\n      \"Learning to control your excitement in the first round — for example with the stop-start technique — can leave you less exhausted.\",\n      \"## 4. Fitness and sleep build stamina\",\n      \"Regular exercise, good sleep and good food all support your energy in bed.\",\n      \"## 5. A calm, confident mind\",\n      \"Pressure and worry make it harder to get aroused again. Focus on enjoyment, not performance.\",\n      \"If you used to recover easily and this has changed a lot, or you also have erection problems, it's worth talking to a doctor.\",\n    ],\n    bodySw: [\n      \"Baada ya kumaliza, mwili wa kila mwanaume unahitaji kupumzika kabla ya kuweza kusisimka tena. Mapumziko haya ni ya kawaida. Kwa kawaida huwa mafupi kwa vijana na huongezeka kadiri umri unavyoongezeka.\",\n      \"## 1. Pumzika, lakini baki karibu\",\n      \"Usigeuke na kulala moja kwa moja. Endelea kumshika, kumbusu na kufurahia mwenzako wakati mwili unajirudisha. Ukaribu huu unawasaidia nyote.\",\n      \"## 2. Kunywa maji na pumua kwa utulivu\",\n      \"Kuwa na maji ya kutosha mwilini na kupumua taratibu kunakusaidia kujisikia mpya tena.\",\n      \"## 3. Punguza kasi kwenye raundi ya kwanza\",\n      \"Ukijifunza kudhibiti msisimko kwenye raundi ya kwanza — kwa mfano kwa mbinu ya kusimama na kuendelea — hutachoka sana.\",\n      \"## 4. Mazoezi na usingizi huongeza stamina\",\n      \"Mazoezi ya mara kwa mara, usingizi mzuri na chakula bora vinasaidia nguvu zako.\",\n      \"## 5. Akili tulivu yenye kujiamini\",\n      \"Presha na wasiwasi hufanya iwe vigumu kusisimka tena. Lenga kufurahia, si kuonyesha uwezo.\",\n      \"Kama zamani ulikuwa unarudi haraka na sasa imebadilika sana, au una pia changamoto ya uume kusimama, ni vizuri kuongea na daktari.\",\n    ],\n  },\n  {\n    id: \"ig-gas-bloating-habits\",\n    kind: \"article\",\n    topic: \"wellbeing\",\n    title: \"Gas and bloating: three habits to start with\",\n    titleSw: \"Gesi na tumbo kujaa: tabia tatu za kuanza nazo\",\n    summary: \"Simple daily changes that often help a noisy, bloated stomach — and the signs that need a doctor.\",\n    minutes: 2,\n    priority: 66,\n    tags: [\"gas\", \"bloating\", \"digestion\", \"gesi\", \"tumbo\"],\n    source: IG_SOURCE,\n    review: \"draft\",\n    fixture: false,\n    origin: { platform: \"instagram\", url: \"https://www.instagram.com/p/DdqbtIeAsdU/\", postedAt: \"2026-09-24\", format: \"carousel\" },\n    cover: { tone: \"mint\", motif: \"waves\" },\n    body: [\n      \"Is your stomach rumbling, full of gas, or are you struggling to pass stool? Start with three habits:\",\n      \"Eat your evening meal earlier, so your stomach has time to rest before sleep.\",\n      \"Walk for at least 10 minutes after eating.\",\n      \"Cut down on fatty, fried and heavily processed food.\",\n      \"Drinking enough water and eating more vegetables, fruit and whole grains also helps many people.\",\n      \"See a doctor if you notice blood in your stool, black stools, weight loss, ongoing pain, or if the problem lasts more than a few weeks.\",\n    ],\n    bodySw: [\n      \"Tumbo linaunguruma, linajaa gesi, au unapata choo kwa shida? Anza na tabia tatu:\",\n      \"Kula chakula cha jioni mapema, ili tumbo lipate muda wa kupumzika kabla ya kulala.\",\n      \"Tembea angalau dakika 10 baada ya kula.\",\n      \"Punguza vyakula vya mafuta mengi, vya kukaanga na vilivyosindikwa sana.\",\n      \"Kunywa maji ya kutosha na kula mboga, matunda na nafaka zisizokobolewa zaidi pia huwasaidia watu wengi.\",\n      \"Mwone daktari ukiona damu kwenye choo, choo cheusi, kupungua uzito, maumivu yasiyoisha, au kama tatizo linaendelea zaidi ya wiki chache.\",\n    ],\n  },\n  {\n    id: \"ig-beetroot-blood-flow\",\n    kind: \"article\",\n    topic: \"erection\",\n    title: \"Food for healthy blood flow: a beetroot drink\",\n    titleSw: \"Chakula kwa mzunguko mzuri wa damu: kinywaji cha beetroot\",\n    summary: \"Good blood flow matters for men's health. A simple drink using beetroot, pomegranate, honey and turmeric — as part of a healthy diet.\",\n    minutes: 2,\n    priority: 64,\n    tags: [\"beetroot\", \"blood flow\", \"nutrition\", \"lishe\", \"mzunguko wa damu\"],\n    source: IG_SOURCE,\n    review: \"draft\",\n    fixture: false,\n    origin: { platform: \"instagram\", url: \"https://www.instagram.com/p/DdiS5Gygsb2/\", postedAt: \"2026-09-21\", format: \"carousel\" },\n    cover: { tone: \"clay\", motif: \"dots\" },\n    body: [\n      \"Men's health starts with good food. Healthy blood vessels and good circulation are important for erections and for the body as a whole.\",\n      \"Beetroot naturally contains nitrates, which the body can use to help blood vessels relax. Some studies suggest this supports blood flow. It's a helpful food, not a treatment.\",\n      \"## The drink\",\n      \"Mix 100–150 ml of beetroot juice with 1 tablespoon of pomegranate juice, 1 teaspoon of pure honey and a quarter to half a teaspoon of turmeric powder. Drink it in the morning or 30 minutes before a meal, 3–4 times a week.\",\n      \"## Take care\",\n      \"If you take medicine for blood pressure or diabetes, or blood thinners, check with a doctor or pharmacist first. Beetroot can turn urine pink or red — this is harmless.\",\n      \"If you have ongoing erection problems, food alone may not be enough. A doctor can check for causes like high blood pressure or diabetes.\",\n    ],\n    bodySw: [\n      \"Afya ya mwanaume huanza na lishe bora. Mishipa ya damu yenye afya na mzunguko mzuri wa damu ni muhimu kwa uume kusimama na kwa mwili mzima.\",\n      \"Beetroot (kiazi chekundu) kina nitrates kwa asili, ambazo mwili unaweza kuzitumia kusaidia mishipa ya damu kulegea. Baadhi ya tafiti zinaonyesha hii inasaidia mzunguko wa damu. Ni chakula chenye manufaa, si tiba.\",\n      \"## Kinywaji\",\n      \"Changanya juisi ya beetroot ml 100–150, kijiko 1 cha chakula cha juisi ya komamanga, kijiko 1 cha chai cha asali halisi, na robo hadi nusu kijiko cha chai cha binzari manjano. Kunywa asubuhi au dakika 30 kabla ya kula, mara 3–4 kwa wiki.\",\n      \"## Tahadhari\",\n      \"Kama unatumia dawa za presha, kisukari au za kuzuia damu kuganda, ongea na daktari au mfamasia kwanza. Beetroot inaweza kufanya mkojo kuwa wa pinki au mwekundu — hii haina madhara.\",\n      \"Kama una changamoto ya muda mrefu ya uume kusimama, chakula pekee kinaweza kisitoshe. Daktari anaweza kuchunguza visababishi kama presha au kisukari.\",\n    ],\n  },\n  {\n    id: \"ig-fertility-smoothie\",\n    kind: \"article\",\n    topic: \"libido\",\n    title: \"A fertility-friendly smoothie\",\n    titleSw: \"Smoothie rafiki kwa afya ya uzazi\",\n    summary: \"Banana, almonds, avocado and milk bring nutrients sperm need — as part of a healthy lifestyle.\",\n    minutes: 2,\n    priority: 56,\n    tags: [\"fertility\", \"sperm\", \"smoothie\", \"mbegu za kiume\", \"uzazi\"],\n    source: IG_SOURCE,\n    review: \"draft\",\n    fixture: false,\n    origin: { platform: \"instagram\", url: \"https://www.instagram.com/p/DdiTOo6qIo_/\", postedAt: \"2026-09-21\", format: \"post\" },\n    cover: { tone: \"mint\", motif: \"rings\" },\n    body: [\n      \"Healthy sperm need good nutrition over time — especially zinc, vitamin E, folate and antioxidants. This smoothie is an easy way to get some of them.\",\n      \"## Ingredients\",\n      \"1 large ripe banana, a handful of almonds, half an avocado and 1 glass of milk. Blend together. Add a little honey if you like.\",\n      \"## What each brings\",\n      \"Almonds: vitamin E and zinc. Avocado: healthy fats and folate. Banana: vitamin B6. Milk: calcium and protein.\",\n      \"## Keep it in perspective\",\n      \"No single food boosts fertility on its own. Sperm take about three months to develop, so steady habits matter: no smoking, less alcohol, a healthy weight and avoiding too much heat around the testicles.\",\n      \"If you and your partner have been trying for a year without success — or six months if she is over 35 — see a doctor together. A semen test is simple.\",\n    ],\n    bodySw: [\n      \"Mbegu za kiume zenye afya zinahitaji lishe bora kwa muda — hasa zinc, vitamini E, folate na antioxidants. Smoothie hii ni njia rahisi ya kupata baadhi yake.\",\n      \"## Mahitaji\",\n      \"Ndizi mbivu 1 kubwa, kiganja kimoja cha almond, nusu parachichi na glasi 1 ya maziwa. Saga pamoja kwenye blender. Ongeza asali kidogo ukipenda.\",\n      \"## Kila kimoja kinaleta nini\",\n      \"Almond: vitamini E na zinc. Parachichi: mafuta mazuri na folate. Ndizi: vitamini B6. Maziwa: calcium na protini.\",\n      \"## Kumbuka\",\n      \"Hakuna chakula kimoja kinachoongeza uwezo wa kuzaa peke yake. Mbegu huchukua takriban miezi mitatu kukua, hivyo tabia za kila siku ni muhimu: usivute sigara, punguza pombe, kuwa na uzito mzuri, na epuka joto kali karibu na korodani.\",\n      \"Kama wewe na mwenzako mmejaribu kwa mwaka mmoja bila mafanikio — au miezi sita kama yeye ana zaidi ya miaka 35 — mwoneni daktari pamoja. Kipimo cha mbegu ni rahisi.\",\n    ],\n  },\n];\n",
  "src/lib/content/library.ts": "// DEVELOPMENT FIXTURES — sample content until the Content Studio and database exist.\n// Every item is marked fixture: true and review: \"draft\". The UI shows this to readers.\n// Health wording rules: no cure claims, no guaranteed results, always say when to see a doctor.\n\nimport type { ContentItem, Topic } from \"./types\";\nimport { INSTAGRAM_CONTENT } from \"./instagram\";\n\nexport const TOPICS: Topic[] = [\n  { id: \"erection\", title: \"Erection health\", short: \"Erections\" },\n  { id: \"ejaculation\", title: \"Ejaculation and satisfaction\", short: \"Lasting longer\" },\n  { id: \"libido\", title: \"Libido and reproductive health\", short: \"Desire and fertility\" },\n  { id: \"confidence\", title: \"Confidence and performance anxiety\", short: \"Confidence\" },\n  { id: \"intimacy\", title: \"Intimacy and relationships\", short: \"Intimacy\" },\n  { id: \"wellbeing\", title: \"Sleep, stress and physical wellbeing\", short: \"Body and mind\" },\n];\n\nconst DRAFT = \"Men's Social editorial · Draft, pending review by a qualified health professional\";\n\nconst EDITORIAL_SAMPLES: ContentItem[] = [\n  // ───────────── Erection health ─────────────\n  {\n    id: \"erection-guide\",\n    kind: \"guide\",\n    topic: \"erection\",\n    title: \"Erection health: what actually helps\",\n    summary: \"Understand what affects erections and the everyday changes with real evidence behind them — plus when to get checked.\",\n    minutes: 6,\n    priority: 100,\n    tags: [\"erectile dysfunction\", \"ED\", \"lifestyle\", \"blood flow\", \"heart\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"night\", motif: \"rings\" },\n    body: [\n      \"Almost every man has times when erections are weaker or don't last. One difficult night is normal. If it keeps happening for several weeks, it's worth paying attention — not with shame, but the way you would with any other health signal.\",\n      \"## How an erection works\",\n      \"An erection depends on healthy blood vessels, nerves, hormones and a relaxed mind working together. When any of these is under strain — from poor circulation, stress, tiredness, alcohol or some medicines — erections can be affected.\",\n      \"## Changes with good evidence\",\n      \"Regular physical activity: studies link moderate exercise, such as brisk walking several times a week, with better erectile function. It supports blood flow, weight and mood.\",\n      \"Stopping smoking: smoking damages blood vessels, including the small ones the penis depends on. Quitting helps your whole body.\",\n      \"Less alcohol: heavy drinking can make erections harder to get and keep, in the moment and over time.\",\n      \"Sleep and stress: long-term short sleep and constant stress can lower energy and desire. Small daily habits here often help more than people expect.\",\n      \"Managing health conditions: diabetes, high blood pressure and high cholesterol are common causes of erection problems. Keeping them under control matters.\",\n      \"## Be careful with 'instant' products\",\n      \"Be cautious with any product that promises instant or guaranteed results. Health authorities in several countries have found unregistered 'natural' sexual products that secretly contained prescription medicines, which can be dangerous — especially for men taking heart medicines.\",\n      \"## When to see a doctor\",\n      \"See a doctor if problems continue for more than a few weeks, if they started suddenly, or if you also have chest pain, shortness of breath, diabetes or high blood pressure. Erection problems can sometimes be an early sign of heart or blood-vessel disease, so a check-up is a smart move — and doctors deal with this every day.\",\n    ],\n  },\n  {\n    id: \"ed-heart-signal\",\n    kind: \"article\",\n    topic: \"erection\",\n    title: \"Why erection problems can be an early health signal\",\n    summary: \"The link between erections and heart health — and why a check-up can protect more than your sex life.\",\n    minutes: 3,\n    priority: 70,\n    tags: [\"heart\", \"blood pressure\", \"diabetes\", \"check-up\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"clay\", motif: \"arc\" },\n    body: [\n      \"The blood vessels in the penis are small. When blood vessels around the body start to narrow, the small ones can show problems first.\",\n      \"That's why doctors often ask about erections when checking heart health — and why erection problems can sometimes appear years before other signs of heart disease.\",\n      \"A simple check-up can include blood pressure, blood sugar and cholesterol. If something is found early, it's usually easier to manage.\",\n      \"If you have erection problems together with chest pain, shortness of breath or swelling in the legs, see a doctor soon.\",\n    ],\n  },\n  {\n    id: \"quiz-erection-myths\",\n    kind: \"quiz\",\n    topic: \"erection\",\n    title: \"Erection health: myth or fact?\",\n    summary: \"Five quick questions. See what you know — and learn something new in two minutes.\",\n    minutes: 2,\n    priority: 60,\n    tags: [\"quiz\", \"myths\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"mint\", motif: \"dots\" },\n    quiz: [\n      {\n        q: \"Occasional difficulty getting an erection means something is seriously wrong.\",\n        options: [\"Myth\", \"Fact\"],\n        answer: 0,\n        explain: \"Occasional difficulty is common and often linked to tiredness, stress or alcohol. Ongoing problems for several weeks are worth checking.\",\n      },\n      {\n        q: \"Regular exercise like brisk walking can support erection health.\",\n        options: [\"Myth\", \"Fact\"],\n        answer: 1,\n        explain: \"Studies link regular physical activity with better erectile function, partly through better blood flow.\",\n      },\n      {\n        q: \"Erection problems can sometimes be an early sign of heart disease.\",\n        options: [\"Myth\", \"Fact\"],\n        answer: 1,\n        explain: \"The small blood vessels in the penis can show problems early. That's why a check-up is a good idea.\",\n      },\n      {\n        q: \"Products that promise 'instant results' are always safe because they are natural.\",\n        options: [\"Myth\", \"Fact\"],\n        answer: 0,\n        explain: \"Some unregistered 'natural' products have been found to contain hidden medicines. Natural doesn't automatically mean safe.\",\n      },\n      {\n        q: \"Smoking can make erection problems more likely.\",\n        options: [\"Myth\", \"Fact\"],\n        answer: 1,\n        explain: \"Smoking damages blood vessels, including those needed for an erection.\",\n      },\n    ],\n  },\n  {\n    id: \"tool-doctor-check\",\n    kind: \"tool\",\n    topic: \"erection\",\n    title: \"Should I see a doctor? A quick check\",\n    summary: \"Answer a few yes/no questions to see whether a check-up is a good next step. Private — nothing is saved.\",\n    minutes: 1,\n    priority: 55,\n    tags: [\"doctor\", \"check-up\", \"tool\"],\n    tool: \"doctor-check\",\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"forest\", motif: \"grid\" },\n  },\n  {\n    id: \"expert-instant-boosters\",\n    kind: \"expert\",\n    topic: \"erection\",\n    title: \"Are 'instant' sex boosters safe?\",\n    question: \"I see adverts for pills and powders that promise instant strength in bed. Are they safe to try?\",\n    summary: \"A clear answer on what to watch out for before you buy.\",\n    minutes: 2,\n    priority: 65,\n    tags: [\"supplements\", \"safety\", \"pills\"],\n    source: \"Drafted answer · awaiting review by a verified professional\",\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"sand\", motif: \"waves\" },\n    body: [\n      \"Be careful. Products that promise instant or guaranteed results are a warning sign.\",\n      \"Health authorities in several countries have found unregistered sexual-enhancement products — including some sold as 'herbal' — that secretly contained prescription medicines. These can cause dangerous drops in blood pressure, especially in men who take heart medicines called nitrates.\",\n      \"Before trying any product: check that it is registered with the national regulator (in Tanzania, TMDA), read the ingredients, and ask a pharmacist or doctor if you take any other medicines.\",\n      \"If erection problems are ongoing, a doctor can look for the cause and offer treatments that have been properly tested.\",\n    ],\n  },\n\n  // ───────────── Ejaculation and satisfaction ─────────────\n  {\n    id: \"lasting-longer\",\n    kind: \"guide\",\n    topic: \"ejaculation\",\n    title: \"Lasting longer: techniques with evidence\",\n    summary: \"Practical techniques you can try at home, explained simply — and what doctors can offer if you need more.\",\n    minutes: 5,\n    priority: 90,\n    tags: [\"premature ejaculation\", \"PE\", \"stop-start\", \"squeeze\", \"pelvic floor\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"forest\", motif: \"waves\" },\n    body: [\n      \"Finishing earlier than you or your partner would like is one of the most common sexual concerns men have. It is not a sign of weakness, and it often improves with practice.\",\n      \"## The stop-start technique\",\n      \"During stimulation (alone or with a partner), stop when you feel you're getting close. Wait until the urge settles, then start again. Repeat a few times before allowing yourself to finish. Over time, many men learn to recognise and control the build-up better.\",\n      \"## The squeeze technique\",\n      \"Similar to stop-start, but when you're close, you or your partner gently squeeze the head of the penis for several seconds until the urge passes, then continue.\",\n      \"## Pelvic floor exercises\",\n      \"The pelvic floor muscles help control ejaculation. Some studies suggest that training them regularly can help. Try the Pelvic floor trainer tool in Discover.\",\n      \"## The mind matters\",\n      \"Anxiety can make finishing early more likely, and finishing early can increase anxiety. Slow breathing, focusing on touch and sensation, and talking openly with your partner can break that cycle.\",\n      \"## When to see a doctor\",\n      \"If it's causing you real distress, has always happened, or started suddenly, talk to a doctor. There are medical treatments, including medicines and numbing creams, that a doctor can discuss with you.\",\n    ],\n  },\n  {\n    id: \"too-early-myths\",\n    kind: \"article\",\n    topic: \"ejaculation\",\n    title: \"What counts as 'too early'? Common myths\",\n    summary: \"Films and friends set unrealistic expectations. Here's what's actually normal.\",\n    minutes: 3,\n    priority: 50,\n    tags: [\"myths\", \"normal\", \"expectations\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"mint\", motif: \"arc\" },\n    body: [\n      \"Many men believe sex should last much longer than it usually does. Films and stories from friends often give a false picture.\",\n      \"What matters most is whether you and your partner are satisfied — not a number on a clock.\",\n      \"Finishing quickly from time to time, especially after a long break, when very excited, or with a new partner, is common.\",\n      \"If it happens almost every time and causes you or your partner distress, that's worth addressing. Start with the techniques in 'Lasting longer', and see a doctor if it continues.\",\n    ],\n  },\n  {\n    id: \"tool-pelvic-floor\",\n    kind: \"tool\",\n    topic: \"ejaculation\",\n    title: \"Pelvic floor trainer\",\n    summary: \"A guided timer for pelvic floor exercises: squeeze, hold, relax. Takes about three minutes.\",\n    minutes: 3,\n    priority: 58,\n    tags: [\"kegel\", \"pelvic floor\", \"exercise\", \"tool\"],\n    tool: \"pelvic-floor\",\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"night\", motif: \"dots\" },\n  },\n  {\n    id: \"video-pelvic-floor\",\n    kind: \"video\",\n    topic: \"ejaculation\",\n    title: \"Pelvic floor muscles, explained\",\n    summary: \"Where these muscles are, how to find them, and why they matter for control.\",\n    minutes: 2,\n    priority: 52,\n    tags: [\"video\", \"pelvic floor\", \"kegel\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"clay\", motif: \"rings\" },\n    keyPoints: [\n      \"The pelvic floor is a group of muscles under your bladder and bowel.\",\n      \"To find them, imagine stopping yourself from passing wind — that's the squeeze.\",\n      \"Don't hold your breath or tighten your stomach, legs or bottom.\",\n      \"Start with a few short squeezes and build up slowly.\",\n      \"Stop and see a doctor if you feel pain.\",\n    ],\n  },\n  {\n    id: \"expert-normal-quickly\",\n    kind: \"expert\",\n    topic: \"ejaculation\",\n    title: \"Is it normal to finish quickly sometimes?\",\n    question: \"Sometimes I finish within a minute, other times it's fine. Should I be worried?\",\n    summary: \"What a changing pattern usually means, and when it's worth getting help.\",\n    minutes: 2,\n    priority: 48,\n    tags: [\"premature ejaculation\", \"normal\"],\n    source: \"Drafted answer · awaiting review by a verified professional\",\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"sand\", motif: \"grid\" },\n    body: [\n      \"Yes, it's common for timing to vary. Excitement, a long break, a new partner, stress or alcohol can all change it.\",\n      \"Because it's fine at other times, this is usually not a fixed problem. Techniques like stop-start and pelvic floor exercises can help you feel more in control.\",\n      \"If it starts happening almost every time, or it's causing you or your partner real distress, it's worth speaking to a doctor.\",\n    ],\n  },\n\n  // ───────────── Libido and reproductive health ─────────────\n  {\n    id: \"low-desire\",\n    kind: \"article\",\n    topic: \"libido\",\n    title: \"Low desire: common causes and what to check\",\n    summary: \"Why interest in sex changes, what you can look at yourself, and when a blood test makes sense.\",\n    minutes: 4,\n    priority: 75,\n    tags: [\"libido\", \"desire\", \"testosterone\", \"stress\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"clay\", motif: \"waves\" },\n    body: [\n      \"Desire goes up and down for every man. Work pressure, money worries, poor sleep, relationship tension and tiredness are some of the most common reasons it drops.\",\n      \"## Things you can look at\",\n      \"Sleep, stress, alcohol, exercise and how things are in your relationship. Tracking your energy and sleep in the Man tab can help you spot patterns.\",\n      \"## Medicines and health\",\n      \"Some medicines, including some for blood pressure and depression, can affect desire. Don't stop a prescribed medicine on your own — talk to your doctor about options.\",\n      \"## What about testosterone?\",\n      \"Low testosterone can reduce desire, but it can only be confirmed with a blood test, usually taken in the morning. Taking testosterone or 'booster' products without a doctor can cause side effects and can reduce fertility.\",\n      \"If low desire lasts for months or worries you, a doctor can help find the cause.\",\n    ],\n  },\n  {\n    id: \"fertility-basics\",\n    kind: \"article\",\n    topic: \"libido\",\n    title: \"Fertility basics for men\",\n    summary: \"Simple facts about male fertility and the everyday habits that help protect it.\",\n    minutes: 4,\n    priority: 62,\n    tags: [\"fertility\", \"sperm\", \"children\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"mint\", motif: \"rings\" },\n    body: [\n      \"When a couple has difficulty having a baby, the cause is linked to the man in a large share of cases. Checking both partners is normal and sensible.\",\n      \"## Habits that help protect sperm\",\n      \"Avoid smoking, limit alcohol, keep a healthy weight, and avoid long periods of heat around the testicles, such as very hot baths or a laptop on your lap.\",\n      \"Muscle-building steroids and testosterone products can seriously reduce sperm production.\",\n      \"## When to get checked\",\n      \"If you and your partner have been trying for a year without success — or six months if she is over 35 — see a doctor together. A semen test is simple and gives useful information.\",\n    ],\n  },\n  {\n    id: \"expert-masturbation\",\n    kind: \"expert\",\n    topic: \"libido\",\n    title: \"Does masturbation cause erection problems?\",\n    question: \"People say masturbating too much makes you weak. Is that true?\",\n    summary: \"A calm, honest answer to one of the most common questions men ask.\",\n    minutes: 2,\n    priority: 68,\n    tags: [\"masturbation\", \"myths\", \"habits\"],\n    source: \"Drafted answer · awaiting review by a verified professional\",\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"forest\", motif: \"arc\" },\n    body: [\n      \"Masturbation is a normal part of sexual health for many men, and there's no good evidence that it causes erection problems or physical weakness.\",\n      \"What can matter is the pattern. If it feels out of control, gets in the way of daily life or your relationship, or if you rely on very specific content to get aroused, it may affect how you respond with a partner.\",\n      \"If you'd like to change a habit, that's a personal choice and it's fine. Small steps work better than guilt. If erection problems continue, see a doctor to check for other causes.\",\n    ],\n  },\n\n  // ───────────── Confidence and performance anxiety ─────────────\n  {\n    id: \"performance-anxiety\",\n    kind: \"guide\",\n    topic: \"confidence\",\n    title: \"Performance anxiety: breaking the cycle\",\n    summary: \"Why worrying about sex can make things harder — and practical ways to get out of your head.\",\n    minutes: 5,\n    priority: 85,\n    tags: [\"anxiety\", \"confidence\", \"nerves\", \"pressure\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"night\", motif: \"waves\" },\n    body: [\n      \"One bad experience can make you worry about the next time. That worry puts your body on alert, which makes it harder to relax and respond — and the cycle continues.\",\n      \"## Shift the focus\",\n      \"Focus on touch, closeness and enjoyment rather than 'performing'. Sex doesn't have to follow a script or end in a particular way.\",\n      \"## Calm the body first\",\n      \"A few minutes of slow breathing — in for 4 seconds, out for 6 — can calm the alert response. Try the 2-minute breathing video in Discover.\",\n      \"## Talk about it\",\n      \"Telling your partner you've been feeling pressure often takes much of the weight away. Most partners care more about connection than performance.\",\n      \"## Get support if it continues\",\n      \"If anxiety is affecting your relationships or daily life, a doctor or counsellor can help. Asking for help is a strong move.\",\n    ],\n  },\n  {\n    id: \"stress-and-performance\",\n    kind: \"article\",\n    topic: \"confidence\",\n    title: \"Stress, worry and performance\",\n    summary: \"How a busy mind can affect confidence in the bedroom, and what helps.\",\n    minutes: 4,\n    priority: 45,\n    tags: [\"stress\", \"anxiety\", \"performance\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    inManFeed: true,\n    points: 10,\n    cover: { tone: \"sand\", motif: \"dots\" },\n    body: [\n      \"Many men go through periods where worry or stress affects their confidence or sexual performance. It is common and nothing to be ashamed of.\",\n      \"When you are anxious, your body goes into 'alert' mode. That can make it harder to relax and stay in the moment.\",\n      \"Calming habits can help: slow breathing, regular exercise, enough sleep, and talking openly with your partner.\",\n      \"If problems with erections or finishing too early continue for several weeks, speak with a doctor. These can sometimes be linked to blood pressure, diabetes or other conditions that are worth checking.\",\n    ],\n  },\n  {\n    id: \"video-breathing-reset\",\n    kind: \"video\",\n    topic: \"confidence\",\n    title: \"A 2-minute breathing reset\",\n    summary: \"A simple breathing pattern to calm nerves before an important moment.\",\n    minutes: 2,\n    priority: 50,\n    tags: [\"video\", \"breathing\", \"calm\", \"nerves\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"forest\", motif: \"rings\" },\n    keyPoints: [\n      \"Sit or lie comfortably and relax your shoulders.\",\n      \"Breathe in through your nose for 4 seconds.\",\n      \"Breathe out slowly through your mouth for 6 seconds.\",\n      \"Repeat for about 2 minutes.\",\n      \"A longer out-breath helps the body switch out of 'alert' mode.\",\n    ],\n  },\n\n  // ───────────── Intimacy and relationships ─────────────\n  {\n    id: \"talk-to-partner\",\n    kind: \"guide\",\n    topic: \"intimacy\",\n    title: \"How to talk to your partner about sex and health\",\n    summary: \"Simple ways to start a difficult conversation — without blame, and without it turning into a fight.\",\n    minutes: 4,\n    priority: 72,\n    tags: [\"communication\", \"partner\", \"relationship\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"clay\", motif: \"grid\" },\n    body: [\n      \"Many couples never talk about sex directly. Small worries then grow into distance.\",\n      \"## Choose the moment\",\n      \"Talk at a calm time — not in bed straight after something went wrong, and not when either of you is tired or angry.\",\n      \"## Start with 'I', not 'you'\",\n      \"'I've been feeling stressed and it's affecting me' is easier to hear than 'You make me nervous'.\",\n      \"## Listen as much as you talk\",\n      \"Ask what she enjoys and what she'd like more of. Intimacy is a shared thing.\",\n      \"## Make a plan together\",\n      \"Agreeing on small changes — more time together, less pressure, seeing a doctor together — can bring you closer.\",\n    ],\n  },\n  {\n    id: \"expert-partner-reaction\",\n    kind: \"expert\",\n    topic: \"intimacy\",\n    title: \"How do I tell my partner I'm seeing a doctor about this?\",\n    question: \"I want to see a doctor about erection problems but I'm embarrassed to tell my wife. How should I bring it up?\",\n    summary: \"Ideas for an honest conversation that brings you closer.\",\n    minutes: 2,\n    priority: 40,\n    tags: [\"partner\", \"doctor\", \"communication\"],\n    source: \"Drafted answer · awaiting review by a verified professional\",\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"mint\", motif: \"waves\" },\n    body: [\n      \"Seeing a doctor shows that you care about your health and your relationship. Many partners feel relieved, because they may have been worrying it was about them.\",\n      \"You could say: 'I've noticed things haven't been easy for me lately, and I want to get it checked so we can enjoy each other more.'\",\n      \"Some couples choose to go to the appointment together. That's completely fine and can help.\",\n    ],\n  },\n\n  // ───────────── Sleep, stress and physical wellbeing ─────────────\n  {\n    id: \"sleep-and-energy\",\n    kind: \"article\",\n    topic: \"wellbeing\",\n    title: \"How sleep shapes your energy\",\n    summary: \"Why a few short nights can leave you drained, and simple ways to sleep better.\",\n    minutes: 3,\n    priority: 60,\n    tags: [\"sleep\", \"energy\", \"rest\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    inManFeed: true,\n    points: 10,\n    cover: { tone: \"night\", motif: \"arc\" },\n    body: [\n      \"Sleep is when your body recovers. After several short nights, many men notice lower energy, a shorter temper and less interest in exercise or intimacy.\",\n      \"Research has linked ongoing short sleep with changes in hormones and mood. Everyone is different, but most adults feel best with around 7 to 9 hours.\",\n      \"Small habits help: going to bed at a similar time each night, keeping the room dark and cool, and putting screens away before bed.\",\n      \"Track your sleep for a couple of weeks and compare it with your energy check-ins. Patterns are often easier to see than to feel.\",\n      \"See a doctor if you snore loudly, stop breathing during sleep, or feel exhausted even after a full night. These can be signs of a sleep condition.\",\n    ],\n  },\n  {\n    id: \"how-much-water\",\n    kind: \"article\",\n    topic: \"wellbeing\",\n    title: \"How much water do you need?\",\n    summary: \"There's no single number. Here's how to find what works for you.\",\n    minutes: 2,\n    priority: 35,\n    tags: [\"water\", \"hydration\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    inManFeed: true,\n    points: 10,\n    cover: { tone: \"mint\", motif: \"dots\" },\n    body: [\n      \"Your water needs depend on your body size, how active you are and the weather. Hot days and exercise mean you need more.\",\n      \"Many adults aim for around 2 to 3 litres a day from drinks, but food provides some water too.\",\n      \"A simple check: pale yellow urine usually means you're drinking enough. Dark urine, headaches or feeling tired can be signs you need more.\",\n      \"If you have kidney or heart problems, ask a doctor how much you should drink.\",\n    ],\n  },\n  {\n    id: \"walking-benefits\",\n    kind: \"article\",\n    topic: \"wellbeing\",\n    title: \"The 20-minute walk: small habit, big return\",\n    summary: \"Why a daily walk is one of the simplest things you can do for energy, mood and circulation.\",\n    minutes: 3,\n    priority: 42,\n    tags: [\"walking\", \"exercise\", \"circulation\"],\n    source: DRAFT,\n    review: \"draft\",\n    fixture: true,\n    cover: { tone: \"forest\", motif: \"grid\" },\n    body: [\n      \"You don't need a gym to look after your body. Regular walking supports heart health, circulation, weight and mood.\",\n      \"Aim for a pace where you can talk but not sing. Twenty minutes most days is a great start.\",\n      \"If walking alone is hard to keep up, make it social: walk with a friend, or after dinner with your family.\",\n      \"If you have chest pain or feel very short of breath when walking, stop and see a doctor.\",\n    ],\n  },\n];\n\n/** Everything in Discover: real content adapted from Instagram, plus editorial samples. */\nexport const LIBRARY: ContentItem[] = [...INSTAGRAM_CONTENT, ...EDITORIAL_SAMPLES];\n",
  "src/lib/content/select.test.ts": "import { describe, expect, it } from \"vitest\";\nimport { LIBRARY } from \"./library\";\nimport { orderSections, pickFeatured, searchContent, sectionAll, sectionItems, SECTIONS } from \"./select\";\nimport type { ContentItem } from \"./types\";\n\ndescribe(\"content library\", () => {\n  it(\"has unique ids, and every item shows its source and draft status\", () => {\n    const ids = LIBRARY.map((c) => c.id);\n    expect(new Set(ids).size).toBe(ids.length);\n    expect(LIBRARY.every((c) => c.review === \"draft\" && c.source.length > 0)).toBe(true);\n  });\n  it(\"real (non-sample) items link back to where they came from, with a Kiswahili version\", () => {\n    for (const c of LIBRARY.filter((x) => !x.fixture)) {\n      expect(c.origin?.url, c.id).toMatch(/^https:\\/\\/www\\.instagram\\.com\\//);\n      expect(c.bodySw?.length, c.id).toBe(c.body?.length);\n      expect(c.titleSw, c.id).toBeTruthy();\n    }\n  });\n  it(\"never promises cures or guaranteed results\", () => {\n    const text = JSON.stringify(LIBRARY).toLowerCase();\n    for (const banned of [\"guaranteed to\", \"guarantees\", \"100%\", \"will cure\", \"cures erectile\", \"permanent cure\", \"miracle\", \"unatibu\", \"inatibu\", \"huponya\", \"kutibu kabisa\", \"tsh\", \"0655\", \"0635\", \"kayapower\", \"whatsapp\"]) {\n      expect(text.includes(banned), banned).toBe(false);\n    }\n  });\n  it(\"quizzes have valid answers and tools have a tool id\", () => {\n    for (const c of LIBRARY) {\n      if (c.kind === \"quiz\") c.quiz!.forEach((q) => expect(q.answer).toBeLessThan(q.options.length));\n      if (c.kind === \"tool\") expect(c.tool).toBeTruthy();\n    }\n  });\n  it(\"fills all nine Discover sections\", () => {\n    expect(SECTIONS).toHaveLength(9);\n    for (const s of SECTIONS) expect(sectionItems(s.id).length, s.id).toBeGreaterThan(0);\n  });\n});\n\ndescribe(\"featured content\", () => {\n  it(\"prefers real content over samples when he has no interests\", () => {\n    expect(pickFeatured([])?.fixture).toBe(false);\n  });\n  it(\"uses samples only when there is no real content\", () => {\n    expect(pickFeatured([], LIBRARY.filter((c) => c.fixture))?.id).toBe(\"erection-guide\");\n  });\n  it(\"favours a topic he chose\", () => {\n    expect(pickFeatured([\"intimacy\"])?.topic).toBe(\"intimacy\");\n    expect(pickFeatured([\"ejaculation\"])?.topic).toBe(\"ejaculation\");\n  });\n  it(\"only features reading content (guides and articles)\", () => {\n    expect([\"guide\", \"article\"]).toContain(pickFeatured([\"libido\"])?.kind);\n  });\n  it(\"returns null when there is no content\", () => {\n    expect(pickFeatured([], [])).toBeNull();\n  });\n  it(\"does not repeat the featured item in its section row\", () => {\n    expect(sectionItems(\"erection\", \"erection-guide\").some((c) => c.id === \"erection-guide\")).toBe(false);\n  });\n});\n\ndescribe(\"sections and search\", () => {\n  it(\"topic pages include every format for that topic\", () => {\n    const kinds = new Set(sectionAll(\"erection\").map((c) => c.kind));\n    expect(kinds.has(\"quiz\") && kinds.has(\"tool\") && kinds.has(\"expert\")).toBe(true);\n  });\n  it(\"puts his chosen topics first\", () => {\n    expect(orderSections([\"intimacy\"])[0].id).toBe(\"intimacy\");\n  });\n  it(\"finds content by words in titles, tags and text\", () => {\n    expect(searchContent(\"pelvic floor\").map((c) => c.id)).toContain(\"tool-pelvic-floor\");\n    expect(searchContent(\"fertility\")[0].id).toBe(\"fertility-basics\");\n    expect(searchContent(\"TMDA\").map((c) => c.id)).toContain(\"expert-instant-boosters\");\n  });\n  it(\"needs every word to match, and ignores empty searches\", () => {\n    expect(searchContent(\"pelvic zzzz\")).toEqual([]);\n    expect(searchContent(\"  \")).toEqual([]);\n  });\n  it(\"works on any list (e.g. a future database result)\", () => {\n    const one = [{ ...LIBRARY[0], id: \"x\", title: \"Hello world\" } as ContentItem];\n    expect(searchContent(\"hello\", one)).toHaveLength(1);\n  });\n});\n\ndescribe(\"Kiswahili search\", () => {\n  it(\"finds content by Kiswahili words\", () => {\n    const ids = searchContent(\"gesi tumbo\").map((c) => c.id);\n    expect(ids).toContain(\"ig-eating-day-calm-stomach\");\n    expect(ids).toContain(\"ig-gas-bloating-habits\");\n    expect(searchContent(\"kurudia tendo\")[0].id).toBe(\"ig-second-round\");\n  });\n});\n",
  "src/lib/content/select.ts": "// Chooses and finds content. Pure functions — no saving here, easy to test.\n\nimport type { ContentItem, ContentKind, TopicId } from \"./types\";\nimport { LIBRARY, TOPICS } from \"./library\";\n\nexport type SectionId = TopicId | \"expert\" | \"videos\" | \"tools\";\n\nexport const SECTIONS: { id: SectionId; title: string; blurb: string }[] = [\n  ...TOPICS.map((t) => ({ id: t.id as SectionId, title: t.title, blurb: \"\" })),\n  { id: \"expert\", title: \"Expert answers\", blurb: \"Real questions men ask, answered clearly.\" },\n  { id: \"videos\", title: \"Short videos\", blurb: \"Two minutes or less.\" },\n  { id: \"tools\", title: \"Quizzes and practical tools\", blurb: \"Learn by doing.\" },\n];\n\nconst READING: ContentKind[] = [\"guide\", \"article\"];\n\nexport function getContent(id: string, library: ContentItem[] = LIBRARY): ContentItem | undefined {\n  return library.find((c) => c.id === id);\n}\n\nexport function sectionTitle(id: string): string | undefined {\n  return SECTIONS.find((s) => s.id === id)?.title;\n}\n\nexport function isSectionId(id: string): id is SectionId {\n  return SECTIONS.some((s) => s.id === id);\n}\n\n/**\n * Featured item: highest editorial priority among guides/articles,\n * boosted when it matches a topic he chose, and when it's real content rather than a sample.\n * Ties broken by id so it's stable.\n */\nexport function pickFeatured(interests: TopicId[], library: ContentItem[] = LIBRARY): ContentItem | null {\n  const candidates = library.filter((c) => READING.includes(c.kind));\n  if (candidates.length === 0) return null;\n  const score = (c: ContentItem) =>\n    c.priority + (interests.includes(c.topic) ? 60 : 0) + (c.kind === \"guide\" ? 5 : 0) + (c.fixture ? 0 : 30);\n  return [...candidates].sort((a, b) => score(b) - score(a) || a.id.localeCompare(b.id))[0];\n}\n\n/** Items for a row on Discover. Topic rows show reading content; format rows show that format. */\nexport function sectionItems(id: SectionId, excludeId?: string, library: ContentItem[] = LIBRARY): ContentItem[] {\n  const pick =\n    id === \"expert\"\n      ? library.filter((c) => c.kind === \"expert\")\n      : id === \"videos\"\n        ? library.filter((c) => c.kind === \"video\")\n        : id === \"tools\"\n          ? library.filter((c) => c.kind === \"quiz\" || c.kind === \"tool\")\n          : library.filter((c) => c.topic === id && READING.includes(c.kind));\n  return pick.filter((c) => c.id !== excludeId).sort((a, b) => b.priority - a.priority);\n}\n\n/** Everything for a topic page (all formats), or a format page. */\nexport function sectionAll(id: SectionId, library: ContentItem[] = LIBRARY): ContentItem[] {\n  if (id === \"expert\" || id === \"videos\" || id === \"tools\") return sectionItems(id, undefined, library);\n  return library.filter((c) => c.topic === id).sort((a, b) => b.priority - a.priority);\n}\n\n/** Order sections so the ones he cares about come first (stable otherwise). */\nexport function orderSections(interests: TopicId[]) {\n  return [...SECTIONS].sort((a, b) => {\n    const ai = interests.includes(a.id as TopicId) ? 0 : 1;\n    const bi = interests.includes(b.id as TopicId) ? 0 : 1;\n    return ai - bi;\n  });\n}\n\nconst norm = (s: string) => s.toLowerCase().normalize(\"NFKD\").replace(/[^\\p{L}\\p{N}\\s]/gu, \" \");\n\n/** Search across titles, tags, summaries, questions and text. Every word must match somewhere. */\nexport function searchContent(query: string, library: ContentItem[] = LIBRARY): ContentItem[] {\n  const words = norm(query).split(/\\s+/).filter((w) => w.length > 1);\n  if (words.length === 0) return [];\n  const topicTitle = (id: TopicId) => TOPICS.find((t) => t.id === id)?.title ?? \"\";\n\n  const scored = library.map((c) => {\n    const title = norm(c.title);\n    const tags = norm(c.tags.join(\" \") + \" \" + topicTitle(c.topic) + \" \" + c.kind);\n    const rest = norm(\n      [c.summary, c.question ?? \"\", c.titleSw ?? \"\", ...(c.body ?? []), ...(c.bodySw ?? []), ...(c.keyPoints ?? [])].join(\" \"),\n    );\n    let score = 0;\n    for (const w of words) {\n      const s = (title.includes(w) ? 3 : 0) + (tags.includes(w) ? 2 : 0) + (rest.includes(w) ? 1 : 0);\n      if (s === 0) return { c, score: 0 };\n      score += s;\n    }\n    return { c, score: score + c.priority / 1000 };\n  });\n\n  return scored.filter((x) => x.score > 0).sort((a, b) => b.score - a.score).map((x) => x.c);\n}\n\nexport const KIND_LABEL: Record<ContentKind, string> = {\n  guide: \"Guide\",\n  article: \"Article\",\n  video: \"Video\",\n  quiz: \"Quiz\",\n  tool: \"Tool\",\n  expert: \"Expert answer\",\n};\n\nexport const CTA_LABEL: Record<ContentKind, string> = {\n  guide: \"Explore guide\",\n  article: \"Read article\",\n  video: \"Watch\",\n  quiz: \"Start quiz\",\n  tool: \"Open tool\",\n  expert: \"Read answer\",\n};\n",
  "src/lib/content/types.ts": "// Shape of every piece of educational content in Men's Social.\n// Today: sample items in library.ts. Later: rows in the Content Studio (admin) / database.\n\nexport type TopicId = \"erection\" | \"ejaculation\" | \"libido\" | \"confidence\" | \"intimacy\" | \"wellbeing\";\n\nexport type ContentKind = \"guide\" | \"article\" | \"video\" | \"quiz\" | \"tool\" | \"expert\";\n\nexport type ToolId = \"pelvic-floor\" | \"doctor-check\";\n\nexport interface QuizQuestion {\n  q: string;\n  options: string[];\n  answer: number; // index of the correct option\n  explain: string;\n}\n\nexport interface ContentItem {\n  id: string;\n  kind: ContentKind;\n  topic: TopicId;\n  title: string;\n  /** What he gains from it, in one or two short sentences. */\n  summary: string;\n  minutes: number;\n  /** Editorial priority 0–100: higher is more likely to be featured. */\n  priority: number;\n  tags: string[];\n  /** Paragraphs. A paragraph starting with \"## \" is shown as a heading. */\n  body?: string[];\n  keyPoints?: string[];\n  question?: string; // expert answers\n  quiz?: QuizQuestion[];\n  tool?: ToolId;\n  /** Who wrote it and its review state — always shown to the reader. */\n  source: string;\n  review: \"draft\" | \"reviewed\";\n  /** true = development sample, to be replaced by real content from the Content Studio. */\n  fixture: boolean;\n  /** Shown as a daily lesson on the Man tab too. */\n  inManFeed?: boolean;\n  points?: number;\n  cover: { tone: \"forest\" | \"night\" | \"mint\" | \"sand\" | \"clay\"; motif: \"rings\" | \"waves\" | \"arc\" | \"grid\" | \"dots\" };\n  /** Kiswahili version of the body (same \"## \" heading rule). */\n  bodySw?: string[];\n  titleSw?: string;\n  /** Where the content was adapted from, e.g. a Kayani Herbs Instagram post. */\n  origin?: { platform: \"instagram\"; url: string; postedAt: string; format: \"reel\" | \"post\" | \"carousel\" };\n}\n\nexport interface Topic {\n  id: TopicId;\n  title: string;\n  short: string;\n}\n",
  "src/lib/feed/catalog.ts": "// Starter content for the Home feed.\n// This is CONTENT, not user data: it moves into the Content Studio (admin) later,\n// where Daud can add, edit and schedule it. Point values are configurable there too.\n\nimport { LIBRARY } from \"../content/library\";\n\nexport type Slot = \"morning\" | \"afternoon\" | \"evening\";\n\n/** \"tracker\" activities complete themselves when the matching record exists. */\nexport type Tracker = \"checkin\" | \"sleep\" | \"water\";\n\nexport interface Activity {\n  id: string;\n  title: string;\n  discreetTitle: string; // shown when discreet mode is on\n  detail: string;\n  points: number;\n  slot: Slot | \"any\";\n  tracker?: Tracker;\n  why: string; // shown under \"Why am I seeing this?\"\n}\n\nexport const ACTIVITIES: Activity[] = [\n  {\n    id: \"checkin\",\n    title: \"Energy and mood check-in\",\n    discreetTitle: \"Daily check-in\",\n    detail: \"Two taps. Helps you notice patterns over time.\",\n    points: 10,\n    slot: \"morning\",\n    tracker: \"checkin\",\n    why: \"A daily check-in is how you and the app learn what affects your energy.\",\n  },\n  {\n    id: \"sleep\",\n    title: \"Log last night's sleep\",\n    discreetTitle: \"Log last night\",\n    detail: \"Bedtime, wake-up time and how well you slept.\",\n    points: 10,\n    slot: \"morning\",\n    tracker: \"sleep\",\n    why: \"Sleep affects energy, mood and overall wellbeing, so it's worth tracking.\",\n  },\n  {\n    id: \"water\",\n    title: \"Reach your water goal\",\n    discreetTitle: \"Water goal\",\n    detail: \"Log glasses and bottles as you drink through the day.\",\n    points: 15,\n    slot: \"any\",\n    tracker: \"water\",\n    why: \"Staying hydrated supports energy and digestion. Your goal is set by you.\",\n  },\n  {\n    id: \"walk\",\n    title: \"Take a 20-minute walk\",\n    discreetTitle: \"20-minute walk\",\n    detail: \"Any pace that feels comfortable. Outside if you can.\",\n    points: 15,\n    slot: \"afternoon\",\n    why: \"Regular walking supports circulation, mood and sleep.\",\n  },\n  {\n    id: \"breathe\",\n    title: \"5 minutes of slow breathing\",\n    discreetTitle: \"5-minute breathing\",\n    detail: \"Breathe in for 4 seconds, out for 6. Repeat for 5 minutes.\",\n    points: 10,\n    slot: \"evening\",\n    why: \"Slow breathing is a simple way to calm stress at the end of the day.\",\n  },\n  {\n    id: \"screens-off\",\n    title: \"Screens off 30 minutes before bed\",\n    discreetTitle: \"Screens off before bed\",\n    detail: \"Put the phone away and let your mind slow down.\",\n    points: 10,\n    slot: \"evening\",\n    why: \"Less screen time before bed can make it easier to fall asleep.\",\n  },\n];\n\nexport interface Lesson {\n  id: string;\n  title: string;\n  topic: string;\n  minutes: number;\n  summary: string;\n  body: string[]; // paragraphs\n  points: number;\n}\n\n// Daily lessons on the Man tab come from the shared content library (same items as in Discover).\nconst TOPIC_LABEL: Record<string, string> = {\n  erection: \"Erections\",\n  ejaculation: \"Lasting longer\",\n  libido: \"Desire\",\n  confidence: \"Confidence\",\n  intimacy: \"Intimacy\",\n  wellbeing: \"Lifestyle\",\n};\n\nexport const LESSONS: Lesson[] = LIBRARY.filter((c) => c.inManFeed).map((c) => ({\n  id: c.id,\n  title: c.title,\n  topic: TOPIC_LABEL[c.topic] ?? c.topic,\n  minutes: c.minutes,\n  summary: c.summary,\n  body: c.body ?? [],\n  points: c.points ?? 10,\n}));\n\nexport const TIPS: string[] = [\n  \"Drink a glass of water before your morning tea.\",\n  \"A short walk after a meal can help you feel lighter.\",\n  \"Go to bed at the same time tonight as last night.\",\n  \"Small steps every day beat big plans you don't keep.\",\n  \"Put your phone in another room when you sleep.\",\n  \"Take the stairs today, even for one floor.\",\n  \"Missed a day? Just start again today. No pressure.\",\n];\n",
  "src/lib/feed/engine.test.ts": "import { describe, expect, it } from \"vitest\";\nimport { ACTIVITIES, LESSONS, type Activity } from \"./catalog\";\nimport {\n  activityStatus,\n  dayPoints,\n  forgivingStreak,\n  levelFor,\n  orderForSlot,\n  pickForDay,\n  timeSlot,\n  totalPoints,\n} from \"./engine\";\nimport type { FeedDB } from \"./store\";\nimport type { Goal, TrackingRecord } from \"../progress/types\";\n\nconst DAY = \"2026-10-13\";\nconst emptyFeed = (): FeedDB => ({ days: {}, lessons: {}, settings: { discreet: false } });\nconst goals: Goal[] = [{ metric: \"water\", target: 2000, unit: \"ml\", period: \"day\", direction: \"increase\", updatedAt: \"\" }];\nconst rec = (metric: TrackingRecord[\"metric\"], value: number, localDate = DAY): TrackingRecord => ({\n  id: `${metric}-${value}-${localDate}`,\n  userId: \"local\",\n  metric,\n  value,\n  unit: metric === \"water\" ? \"ml\" : metric === \"sleep\" ? \"min\" : \"score\",\n  source: \"manual\",\n  recordedAt: `${localDate}T08:00:00Z`,\n  localDate,\n  createdAt: \"\",\n  updatedAt: `${localDate}T08:00:00Z`,\n});\nconst byId = (id: string) => ACTIVITIES.find((a) => a.id === id) as Activity;\n\ndescribe(\"activity status\", () => {\n  it(\"manual activities follow his choice\", () => {\n    const feed = emptyFeed();\n    expect(activityStatus(byId(\"walk\"), feed, [], goals, DAY)).toBe(\"pending\");\n    feed.days[DAY] = { walk: { status: \"done\", at: \"\" }, breathe: { status: \"later\", at: \"\" } };\n    expect(activityStatus(byId(\"walk\"), feed, [], goals, DAY)).toBe(\"done\");\n    expect(activityStatus(byId(\"breathe\"), feed, [], goals, DAY)).toBe(\"later\");\n  });\n  it(\"tracker activities complete only from real records\", () => {\n    const feed = emptyFeed();\n    expect(activityStatus(byId(\"checkin\"), feed, [rec(\"energy\", 3)], goals, DAY)).toBe(\"pending\");\n    expect(activityStatus(byId(\"checkin\"), feed, [rec(\"energy\", 3), rec(\"mood\", 4)], goals, DAY)).toBe(\"done\");\n    expect(activityStatus(byId(\"water\"), feed, [rec(\"water\", 1500)], goals, DAY)).toBe(\"pending\");\n    expect(activityStatus(byId(\"water\"), feed, [rec(\"water\", 1500), rec(\"water\", 500)], goals, DAY)).toBe(\"done\");\n    feed.days[DAY] = { sleep: { status: \"done\", at: \"\" } };\n    expect(activityStatus(byId(\"sleep\"), feed, [], goals, DAY)).toBe(\"pending\"); // can't fake it\n  });\n});\n\ndescribe(\"points, level and order\", () => {\n  it(\"adds points for completed activities and lessons that day\", () => {\n    const feed = emptyFeed();\n    feed.days[DAY] = { walk: { status: \"done\", at: \"\" }, breathe: { status: \"skipped\", at: \"\" } };\n    feed.lessons[LESSONS[0].id] = { localDate: DAY, at: \"\" };\n    const records = [rec(\"energy\", 3), rec(\"mood\", 3)];\n    // walk 15 + check-in 10 + lesson 10\n    expect(dayPoints(ACTIVITIES, LESSONS, feed, records, goals, DAY)).toBe(35);\n    expect(totalPoints(ACTIVITIES, LESSONS, feed, records, goals)).toBe(35);\n  });\n  it(\"points disappear if the record behind them is deleted\", () => {\n    expect(totalPoints(ACTIVITIES, LESSONS, emptyFeed(), [rec(\"energy\", 3)], goals)).toBe(0);\n  });\n  it(\"levels every 100 points\", () => {\n    expect(levelFor(0)).toEqual({ level: 1, into: 0, toNext: 100 });\n    expect(levelFor(235)).toEqual({ level: 3, into: 35, toNext: 65 });\n  });\n  it(\"puts what fits the time of day first and finished items last\", () => {\n    const statuses = { checkin: \"done\", sleep: \"pending\", water: \"pending\", walk: \"later\", breathe: \"pending\", \"screens-off\": \"skipped\" } as const;\n    const order = orderForSlot(ACTIVITIES, statuses, \"morning\").map((a) => a.id);\n    expect(order[0]).toBe(\"sleep\");\n    expect(order.slice(-2).sort()).toEqual([\"checkin\", \"screens-off\"]);\n  });\n});\n\ndescribe(\"forgiving streak\", () => {\n  const days = (...k: string[]) => new Set(k);\n  it(\"counts consecutive days\", () => {\n    expect(forgivingStreak(days(\"2026-10-11\", \"2026-10-12\", \"2026-10-13\"), \"2026-10-13\")).toBe(3);\n  });\n  it(\"an unfinished today does not break it\", () => {\n    expect(forgivingStreak(days(\"2026-10-11\", \"2026-10-12\"), \"2026-10-13\")).toBe(2);\n  });\n  it(\"forgives one missed day\", () => {\n    expect(forgivingStreak(days(\"2026-10-09\", \"2026-10-10\", \"2026-10-12\", \"2026-10-13\"), \"2026-10-13\")).toBe(4);\n  });\n  it(\"two missed days in a row end it\", () => {\n    expect(forgivingStreak(days(\"2026-10-08\", \"2026-10-09\", \"2026-10-12\", \"2026-10-13\"), \"2026-10-13\")).toBe(2);\n  });\n  it(\"is zero with no activity\", () => {\n    expect(forgivingStreak(days(), \"2026-10-13\")).toBe(0);\n  });\n});\n\ndescribe(\"time of day and daily rotation\", () => {\n  it(\"splits the day into morning, afternoon and evening\", () => {\n    expect(timeSlot(new Date(2026, 9, 13, 7))).toBe(\"morning\");\n    expect(timeSlot(new Date(2026, 9, 13, 14))).toBe(\"afternoon\");\n    expect(timeSlot(new Date(2026, 9, 13, 21))).toBe(\"evening\");\n    expect(timeSlot(new Date(2026, 9, 13, 2))).toBe(\"evening\");\n  });\n  it(\"keeps the same pick all day and changes the next day\", () => {\n    expect(pickForDay([\"a\", \"b\", \"c\"], \"2026-10-13\")).toBe(pickForDay([\"a\", \"b\", \"c\"], \"2026-10-13\"));\n    expect(pickForDay([\"a\", \"b\", \"c\"], \"2026-10-13\")).not.toBe(pickForDay([\"a\", \"b\", \"c\"], \"2026-10-14\"));\n  });\n});\n",
  "src/lib/feed/engine.ts": "// Works out the Home feed from real data: what's done, points, level and streak.\n// Pure functions (no saving here), so they're easy to test.\n\nimport { dayLatest, dayTotal } from \"../progress/calc\";\nimport { shiftKey } from \"../progress/dates\";\nimport type { Goal, TrackingRecord } from \"../progress/types\";\nimport type { Activity, Lesson, Slot } from \"./catalog\";\nimport type { FeedDB } from \"./store\";\n\nexport type ActivityStatus = \"pending\" | \"done\" | \"later\" | \"skipped\";\n\nexport function timeSlot(d: Date = new Date()): Slot {\n  const h = d.getHours();\n  if (h >= 5 && h < 12) return \"morning\";\n  if (h >= 12 && h < 17) return \"afternoon\";\n  return \"evening\";\n}\n\nexport function greeting(slot: Slot): string {\n  return slot === \"morning\" ? \"Good morning\" : slot === \"afternoon\" ? \"Good afternoon\" : \"Good evening\";\n}\n\n/** Is a tracker activity complete on this day, based on his actual records? */\nexport function trackerDone(\n  a: Activity,\n  records: TrackingRecord[],\n  goals: Goal[],\n  key: string,\n): boolean {\n  if (a.tracker === \"checkin\") {\n    return Boolean(dayLatest(records, \"energy\", key) && dayLatest(records, \"mood\", key));\n  }\n  if (a.tracker === \"sleep\") return Boolean(dayLatest(records, \"sleep\", key));\n  if (a.tracker === \"water\") {\n    const total = dayTotal(records, \"water\", key);\n    const goal = goals.find((g) => g.metric === \"water\")?.target;\n    return total !== null && goal !== undefined && total >= goal;\n  }\n  return false;\n}\n\nexport function activityStatus(\n  a: Activity,\n  feed: FeedDB,\n  records: TrackingRecord[],\n  goals: Goal[],\n  key: string,\n): ActivityStatus {\n  if (a.tracker && trackerDone(a, records, goals, key)) return \"done\";\n  const choice = feed.days[key]?.[a.id]?.status;\n  if (a.tracker && choice === \"done\") return \"pending\"; // tracker items can't be ticked by hand\n  return choice ?? \"pending\";\n}\n\n/** Today's list: what fits the time of day first, then the rest; finished items last. */\nexport function orderForSlot(\n  activities: Activity[],\n  statuses: Record<string, ActivityStatus>,\n  slot: Slot,\n): Activity[] {\n  const rank = (a: Activity) => {\n    const s = statuses[a.id];\n    if (s === \"done\" || s === \"skipped\") return 4;\n    if (s === \"later\") return 3;\n    if (a.slot === slot) return 0;\n    if (a.slot === \"any\") return 1;\n    return 2;\n  };\n  return [...activities].sort((x, y) => rank(x) - rank(y));\n}\n\n/** Points earned on one day from completed activities and lessons read that day. */\nexport function dayPoints(\n  activities: Activity[],\n  lessons: Lesson[],\n  feed: FeedDB,\n  records: TrackingRecord[],\n  goals: Goal[],\n  key: string,\n): number {\n  const fromActivities = activities\n    .filter((a) => activityStatus(a, feed, records, goals, key) === \"done\")\n    .reduce((s, a) => s + a.points, 0);\n  const fromLessons = lessons\n    .filter((l) => feed.lessons[l.id]?.localDate === key)\n    .reduce((s, l) => s + l.points, 0);\n  return fromActivities + fromLessons;\n}\n\n/** Every day he did anything (activity choice, lesson, or tracker record). */\nexport function activeDays(feed: FeedDB, records: TrackingRecord[]): string[] {\n  const set = new Set<string>();\n  Object.keys(feed.days).forEach((k) => set.add(k));\n  Object.values(feed.lessons).forEach((l) => set.add(l.localDate));\n  records.forEach((r) => set.add(r.localDate));\n  return [...set].sort();\n}\n\nexport function totalPoints(\n  activities: Activity[],\n  lessons: Lesson[],\n  feed: FeedDB,\n  records: TrackingRecord[],\n  goals: Goal[],\n): number {\n  return activeDays(feed, records).reduce(\n    (sum, k) => sum + dayPoints(activities, lessons, feed, records, goals, k),\n    0,\n  );\n}\n\n/** Level 1 at 0 points, +1 level every 100 points. */\nexport function levelFor(points: number) {\n  const level = Math.floor(points / 100) + 1;\n  return { level, into: points % 100, toNext: 100 - (points % 100) };\n}\n\n/**\n * Forgiving streak: counts days with points, going back from today.\n * One missed day is forgiven (the streak continues, that day just isn't counted).\n * Two missed days in a row end it. An unfinished today never breaks it.\n */\nexport function forgivingStreak(pointDays: Set<string>, today: string): number {\n  let streak = 0;\n  let missedInARow = 0;\n  let key = today;\n  if (!pointDays.has(key)) key = shiftKey(key, -1); // today isn't over yet\n  for (let i = 0; i < 400; i++) {\n    if (pointDays.has(key)) {\n      streak++;\n      missedInARow = 0;\n    } else {\n      missedInARow++;\n      if (missedInARow >= 2) break;\n    }\n    key = shiftKey(key, -1);\n  }\n  return streak;\n}\n\n/** Same lesson/tip all day, a different one tomorrow. */\nexport function pickForDay<T>(items: T[], key: string): T {\n  const n = key.split(\"-\").reduce((s, part) => s + Number(part), 0);\n  return items[n % items.length];\n}\n",
  "src/lib/feed/store.ts": "\"use client\";\n\n// Saves what he did with each activity (Done / Later / Skip) and which lessons he read.\n// NOW: on the phone. LATER: Supabase (same shape).\n\nimport { useSyncExternalStore } from \"react\";\nimport { dateKey } from \"../progress/dates\";\n\nexport type ChoiceStatus = \"done\" | \"later\" | \"skipped\";\n\nexport interface FeedDB {\n  /** days[\"2026-10-13\"][\"walk\"] = { status: \"done\", at: \"...\" } */\n  days: Record<string, Record<string, { status: ChoiceStatus; at: string }>>;\n  /** lessons[\"sleep-and-energy\"] = { localDate, at } */\n  lessons: Record<string, { localDate: string; at: string }>;\n  settings: { discreet: boolean };\n}\nexport type FeedState = FeedDB & { ready: boolean };\n\nconst KEY = \"ms_feed_v1\";\nconst EMPTY: FeedDB = { days: {}, lessons: {}, settings: { discreet: false } };\nconst SERVER_STATE: FeedState = { ...EMPTY, ready: false };\nlet cache: FeedState | null = null;\nconst listeners = new Set<() => void>();\n\nfunction load(): FeedState {\n  if (cache) return cache;\n  let db: FeedDB = EMPTY;\n  try {\n    const raw = localStorage.getItem(KEY);\n    if (raw) {\n      const p = JSON.parse(raw) as Partial<FeedDB>;\n      db = {\n        days: p.days && typeof p.days === \"object\" ? p.days : {},\n        lessons: p.lessons && typeof p.lessons === \"object\" ? p.lessons : {},\n        settings: { discreet: Boolean(p.settings?.discreet) },\n      };\n    }\n  } catch {\n    // Storage blocked or corrupted — start empty rather than crash\n  }\n  cache = { ...db, ready: true };\n  return cache;\n}\n\nfunction save(next: FeedDB) {\n  cache = { ...next, ready: true };\n  try {\n    localStorage.setItem(KEY, JSON.stringify(next));\n  } catch {\n    // keep working in memory\n  }\n  listeners.forEach((l) => l());\n}\n\nexport function useFeed(): FeedState {\n  return useSyncExternalStore(\n    (cb) => {\n      listeners.add(cb);\n      return () => listeners.delete(cb);\n    },\n    load,\n    () => SERVER_STATE,\n  );\n}\n\nexport const feedStore = {\n  /** Mark an activity Done / Later / Skipped for today. */\n  setChoice(activityId: string, status: ChoiceStatus) {\n    const db = load();\n    const today = dateKey(new Date());\n    save({\n      ...db,\n      days: { ...db.days, [today]: { ...db.days[today], [activityId]: { status, at: new Date().toISOString() } } },\n    });\n  },\n\n  /** Undo today's choice for an activity (back to pending). */\n  clearChoice(activityId: string) {\n    const db = load();\n    const today = dateKey(new Date());\n    const day = { ...db.days[today] };\n    delete day[activityId];\n    save({ ...db, days: { ...db.days, [today]: day } });\n  },\n\n  markLessonRead(lessonId: string) {\n    const db = load();\n    if (db.lessons[lessonId]) return;\n    const now = new Date();\n    save({ ...db, lessons: { ...db.lessons, [lessonId]: { localDate: dateKey(now), at: now.toISOString() } } });\n  },\n\n  setDiscreet(discreet: boolean) {\n    const db = load();\n    save({ ...db, settings: { ...db.settings, discreet } });\n  },\n};\n",
  "src/lib/social/community.test.ts": "import { describe, expect, it } from \"vitest\";\nimport { activityScore, checkPost, checkReply, reactionCount, timeAgo, toggleReaction } from \"./community\";\nimport { SAMPLE_POSTS, SAMPLE_REPLIES } from \"./fixtures\";\n\ndescribe(\"post safety checks\", () => {\n  it(\"accepts a normal question\", () => {\n    expect(checkPost(\"How do you calm nerves before a date?\", \"Any tips?\")).toBeNull();\n  });\n  it(\"asks for a longer question\", () => {\n    expect(checkPost(\"Help\", \"\")).toMatch(/few more words/);\n  });\n  it(\"blocks phone numbers, links and contact requests\", () => {\n    expect(checkPost(\"Call me for advice please\", \"0712 345 678\")).toMatch(/Phone numbers/);\n    expect(checkPost(\"Check this website now\", \"www.example.com\")).toMatch(/Links/);\n    expect(checkPost(\"Nipigie kwa ushauri zaidi\", \"\")).toMatch(/private contact/);\n    expect(checkPost(\"Inbox me if you need help\", \"\")).toMatch(/private contact/);\n  });\n  it(\"blocks selling and prices\", () => {\n    expect(checkPost(\"Strong dawa available for men\", \"Bei nafuu, delivery Dar\")).toMatch(/Selling/);\n    expect(checkPost(\"Good product for energy\", \"Only 20000 TZS\")).toMatch(/Selling/);\n  });\n  it(\"checks replies too\", () => {\n    expect(checkReply(\"\")).toMatch(/Write a reply/);\n    expect(checkReply(\"You're not alone, brother.\")).toBeNull();\n    expect(checkReply(\"WhatsApp me\")).toMatch(/private contact/);\n  });\n});\n\ndescribe(\"reactions\", () => {\n  it(\"toggles his reaction on and off\", () => {\n    expect(toggleReaction(undefined, \"support\")).toEqual([\"support\"]);\n    expect(toggleReaction([\"support\"], \"support\")).toEqual([]);\n    expect(toggleReaction([\"support\"], \"helpful\")).toEqual([\"support\", \"helpful\"]);\n  });\n  it(\"adds his reaction to the existing count\", () => {\n    expect(reactionCount({ support: 4 }, [\"support\"], \"support\")).toBe(5);\n    expect(reactionCount({ support: 4 }, [], \"support\")).toBe(4);\n    expect(reactionCount(undefined, undefined, \"same\")).toBe(0);\n  });\n  it(\"ranks replies above reactions for 'most active'\", () => {\n    expect(activityScore(2, 0)).toBeGreaterThan(activityScore(0, 5));\n  });\n});\n\ndescribe(\"sample posts\", () => {\n  it(\"are all labelled as samples and pass the same safety checks\", () => {\n    for (const p of SAMPLE_POSTS) {\n      expect(p.fixture).toBe(true);\n      expect(checkPost(p.title, p.body), p.id).toBeNull();\n    }\n    for (const r of SAMPLE_REPLIES) {\n      expect(r.fixture).toBe(true);\n      expect(checkReply(r.body), r.id).toBeNull();\n      expect(SAMPLE_POSTS.some((p) => p.id === r.postId)).toBe(true);\n    }\n  });\n});\n\ndescribe(\"time labels\", () => {\n  const now = new Date(\"2026-10-13T12:00:00Z\");\n  it(\"shows short relative times\", () => {\n    expect(timeAgo(\"2026-10-13T11:59:30Z\", now)).toBe(\"just now\");\n    expect(timeAgo(\"2026-10-13T11:15:00Z\", now)).toBe(\"45m ago\");\n    expect(timeAgo(\"2026-10-13T07:00:00Z\", now)).toBe(\"5h ago\");\n    expect(timeAgo(\"2026-10-11T12:00:00Z\", now)).toBe(\"2d ago\");\n  });\n});\n",
  "src/lib/social/community.ts": "// Community rules and helpers. Pure functions — easy to test, reused when the server arrives.\n\nimport type { TopicId } from \"../content/types\";\n\nexport type CommunityTopic = TopicId | \"general\";\n\nexport const COMMUNITY_TOPICS: { id: CommunityTopic; label: string }[] = [\n  { id: \"general\", label: \"General\" },\n  { id: \"erection\", label: \"Erections\" },\n  { id: \"ejaculation\", label: \"Lasting longer\" },\n  { id: \"libido\", label: \"Desire and fertility\" },\n  { id: \"confidence\", label: \"Confidence\" },\n  { id: \"intimacy\", label: \"Relationships\" },\n  { id: \"wellbeing\", label: \"Body and mind\" },\n];\n\nexport type ReactionKind = \"support\" | \"helpful\" | \"same\";\n\nexport const REACTIONS: { kind: ReactionKind; label: string; emoji: string }[] = [\n  { kind: \"support\", label: \"Support\", emoji: \"🤝\" },\n  { kind: \"helpful\", label: \"Helpful\", emoji: \"💡\" },\n  { kind: \"same\", label: \"Same here\", emoji: \"🙋\" },\n];\n\nexport interface Author {\n  name: string; // nickname, or \"Anonymous member\"\n  anonymous: boolean;\n}\n\nexport interface Post {\n  id: string;\n  topic: CommunityTopic;\n  title: string;\n  body: string;\n  author: Author;\n  createdAt: string;\n  wantsExpert?: boolean;\n  fixture?: boolean; // sample post for development\n  mine?: boolean;\n  baseReactions?: Partial<Record<ReactionKind, number>>;\n}\n\nexport interface Reply {\n  id: string;\n  postId: string;\n  body: string;\n  author: Author;\n  createdAt: string;\n  fixture?: boolean;\n  mine?: boolean;\n  baseReactions?: Partial<Record<ReactionKind, number>>;\n}\n\nexport const REPORT_REASONS = [\n  \"Selling or advertising\",\n  \"Medical misinformation\",\n  \"Harassment or disrespect\",\n  \"Sharing someone's private information\",\n  \"Sexual or explicit content\",\n  \"Something else\",\n] as const;\n\nconst PHONE = /(\\+?\\d[\\d\\s-]{7,}\\d)/;\nconst LINK = /(https?:\\/\\/|www\\.|\\.com\\b|\\.co\\.tz\\b|wa\\.me|t\\.me\\/)/i;\nconst CONTACT = /\\b(whats\\s?app|call me|inbox me|dm me|nipigie|nitumie|namba yangu|my number)\\b/i;\nconst SELLING = /\\b(tsh|tzs|shilingi|price|bei|order now|buy now|nunua|for sale|inauzwa|delivery|discount)\\b/i;\n\nexport const LIMITS = { titleMin: 8, titleMax: 120, bodyMax: 1000, replyMin: 2, replyMax: 600 };\n\n/** Returns a friendly error, or null if the post can be published. */\nexport function checkPost(title: string, body: string): string | null {\n  const t = title.trim();\n  const b = body.trim();\n  if (t.length < LIMITS.titleMin) return \"Write your question in a few more words.\";\n  if (t.length > LIMITS.titleMax) return `Keep the question under ${LIMITS.titleMax} characters. Add details below.`;\n  if (b.length > LIMITS.bodyMax) return `Details can be up to ${LIMITS.bodyMax} characters.`;\n  return checkText(`${t} ${b}`);\n}\n\nexport function checkReply(body: string): string | null {\n  const b = body.trim();\n  if (b.length < LIMITS.replyMin) return \"Write a reply first.\";\n  if (b.length > LIMITS.replyMax) return `Replies can be up to ${LIMITS.replyMax} characters.`;\n  return checkText(b);\n}\n\n/** Shared safety checks: protects members from scams and protects privacy. */\nexport function checkText(text: string): string | null {\n  if (PHONE.test(text)) return \"Phone numbers can't be shared here, to protect everyone's privacy.\";\n  if (LINK.test(text)) return \"Links can't be shared in the community.\";\n  if (CONTACT.test(text)) return \"Please keep conversations in the community — no private contact requests.\";\n  if (SELLING.test(text)) return \"Selling and prices aren't allowed in the community.\";\n  return null;\n}\n\nexport function reactionCount(\n  base: Partial<Record<ReactionKind, number>> | undefined,\n  mine: ReactionKind[] | undefined,\n  kind: ReactionKind,\n): number {\n  return (base?.[kind] ?? 0) + (mine?.includes(kind) ? 1 : 0);\n}\n\nexport function toggleReaction(mine: ReactionKind[] | undefined, kind: ReactionKind): ReactionKind[] {\n  const list = mine ?? [];\n  return list.includes(kind) ? list.filter((k) => k !== kind) : [...list, kind];\n}\n\n/** \"Most active\" = replies count most, then reactions. */\nexport function activityScore(replies: number, reactions: number): number {\n  return replies * 3 + reactions;\n}\n\nexport function timeAgo(iso: string, now: Date = new Date()): string {\n  const s = Math.max(0, (now.getTime() - new Date(iso).getTime()) / 1000);\n  if (s < 60) return \"just now\";\n  if (s < 3600) return `${Math.floor(s / 60)}m ago`;\n  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;\n  if (s < 7 * 86400) return `${Math.floor(s / 86400)}d ago`;\n  return new Date(iso).toLocaleDateString(\"en\", { day: \"numeric\", month: \"short\" });\n}\n\nexport function topicLabel(id: CommunityTopic): string {\n  return COMMUNITY_TOPICS.find((t) => t.id === id)?.label ?? \"General\";\n}\n",
  "src/lib/social/fixtures.ts": "// DEVELOPMENT FIXTURES — sample community posts so the feed isn't empty while there is no server.\n// Shown with a \"Sample\" label. Replaced by real posts when the community backend is connected.\n// No sample reply pretends to be a doctor or verified expert.\n\nimport type { Post, Reply } from \"./community\";\n\nconst hoursAgo = (h: number) => new Date(Date.now() - h * 3600_000).toISOString();\n\nexport const SAMPLE_POSTS: Post[] = [\n  {\n    id: \"sample-1\",\n    topic: \"confidence\",\n    title: \"Nervous with a new partner — how do you calm down?\",\n    body: \"Things were fine before, but with someone new I overthink everything and it affects me. Anyone been through this?\",\n    author: { name: \"Anonymous member\", anonymous: true },\n    createdAt: hoursAgo(3),\n    fixture: true,\n    baseReactions: { support: 12, same: 9, helpful: 2 },\n  },\n  {\n    id: \"sample-2\",\n    topic: \"wellbeing\",\n    title: \"Started walking every evening — energy is better\",\n    body: \"Two weeks of 20-minute walks after dinner. Sleeping better and less tired at work. Small thing but it helps.\",\n    author: { name: \"Baraka_DSM\", anonymous: false },\n    createdAt: hoursAgo(9),\n    fixture: true,\n    baseReactions: { support: 18, helpful: 7 },\n  },\n  {\n    id: \"sample-3\",\n    topic: \"erection\",\n    title: \"Is it worth seeing a doctor at 35?\",\n    body: \"For about two months it's been harder to stay hard. I feel too young for this. Should I just wait?\",\n    author: { name: \"Anonymous member\", anonymous: true },\n    createdAt: hoursAgo(20),\n    wantsExpert: true,\n    fixture: true,\n    baseReactions: { support: 15, same: 6 },\n  },\n  {\n    id: \"sample-4\",\n    topic: \"intimacy\",\n    title: \"How did you start talking to your wife about this?\",\n    body: \"I don't know how to bring it up without it becoming a fight.\",\n    author: { name: \"Anonymous member\", anonymous: true },\n    createdAt: hoursAgo(30),\n    fixture: true,\n    baseReactions: { support: 8, same: 11 },\n  },\n  {\n    id: \"sample-5\",\n    topic: \"ejaculation\",\n    title: \"Tried the stop-start technique for 3 weeks\",\n    body: \"Felt awkward at first but it's helping me notice when I'm close. Sharing in case it helps someone.\",\n    author: { name: \"Juma_77\", anonymous: false },\n    createdAt: hoursAgo(52),\n    fixture: true,\n    baseReactions: { helpful: 21, support: 9 },\n  },\n];\n\nexport const SAMPLE_REPLIES: Reply[] = [\n  {\n    id: \"sample-r1\",\n    postId: \"sample-1\",\n    body: \"Same here. Slowing down and not rushing helped me a lot. Also told her I was nervous — she was very understanding.\",\n    author: { name: \"Anonymous member\", anonymous: true },\n    createdAt: hoursAgo(2),\n    fixture: true,\n    baseReactions: { helpful: 5 },\n  },\n  {\n    id: \"sample-r2\",\n    postId: \"sample-1\",\n    body: \"The breathing video in Discover is good before a date. Sounds simple but it works for me.\",\n    author: { name: \"Mzee_Kijana\", anonymous: false },\n    createdAt: hoursAgo(1),\n    fixture: true,\n    baseReactions: { helpful: 3, support: 2 },\n  },\n  {\n    id: \"sample-r3\",\n    postId: \"sample-3\",\n    body: \"Go. I waited a year and when I finally went the doctor found my blood pressure was high. Better to know early.\",\n    author: { name: \"Anonymous member\", anonymous: true },\n    createdAt: hoursAgo(15),\n    fixture: true,\n    baseReactions: { helpful: 14, support: 6 },\n  },\n  {\n    id: \"sample-r4\",\n    postId: \"sample-4\",\n    body: \"I chose a calm evening and started with 'I've been stressed lately'. It went much better than I feared.\",\n    author: { name: \"Anonymous member\", anonymous: true },\n    createdAt: hoursAgo(26),\n    fixture: true,\n    baseReactions: { helpful: 6 },\n  },\n];\n",
  "src/lib/social/store.ts": "\"use client\";\n\n// Saves Social data: bookmarks, chosen topics, his posts and replies, reactions and reports.\n// NOW: on this phone only (localStorage). LATER: the server, so other men can see his posts.\n\nimport { useSyncExternalStore } from \"react\";\nimport type { TopicId } from \"../content/types\";\nimport { toggleReaction, type CommunityTopic, type Post, type ReactionKind, type Reply } from \"./community\";\n\nexport interface SocialDB {\n  bookmarks: Record<string, string>; // contentId → saved at\n  interests: TopicId[];\n  nickname: string;\n  posts: Post[]; // his own posts\n  replies: Reply[]; // his own replies\n  reactions: Record<string, ReactionKind[]>; // postId/replyId → his reactions\n  reports: Record<string, { reason: string; at: string }>; // reported items (hidden for him, queued for moderators)\n}\nexport type SocialState = SocialDB & { ready: boolean };\n\nconst KEY = \"ms_social_v1\";\nconst EMPTY: SocialDB = { bookmarks: {}, interests: [], nickname: \"\", posts: [], replies: [], reactions: {}, reports: {} };\nconst SERVER_STATE: SocialState = { ...EMPTY, ready: false };\nlet cache: SocialState | null = null;\nconst listeners = new Set<() => void>();\n\nconst obj = <T,>(v: unknown, fallback: T): T => (v && typeof v === \"object\" ? (v as T) : fallback);\n\nfunction load(): SocialState {\n  if (cache) return cache;\n  let db = EMPTY;\n  try {\n    const raw = localStorage.getItem(KEY);\n    if (raw) {\n      const p = JSON.parse(raw) as Partial<SocialDB>;\n      db = {\n        bookmarks: obj(p.bookmarks, {}),\n        interests: Array.isArray(p.interests) ? p.interests : [],\n        nickname: typeof p.nickname === \"string\" ? p.nickname : \"\",\n        posts: Array.isArray(p.posts) ? p.posts : [],\n        replies: Array.isArray(p.replies) ? p.replies : [],\n        reactions: obj(p.reactions, {}),\n        reports: obj(p.reports, {}),\n      };\n    }\n  } catch {\n    // Storage blocked or corrupted — start empty rather than crash\n  }\n  cache = { ...db, ready: true };\n  return cache;\n}\n\nfunction save(next: SocialDB) {\n  cache = { ...next, ready: true };\n  try {\n    localStorage.setItem(KEY, JSON.stringify(next));\n  } catch {\n    // keep working in memory\n  }\n  listeners.forEach((l) => l());\n}\n\nconst id = () =>\n  typeof crypto !== \"undefined\" && \"randomUUID\" in crypto ? crypto.randomUUID() : `${Date.now()}-${Math.random()}`;\n\nexport function useSocial(): SocialState {\n  return useSyncExternalStore(\n    (cb) => {\n      listeners.add(cb);\n      return () => listeners.delete(cb);\n    },\n    load,\n    () => SERVER_STATE,\n  );\n}\n\nexport const socialStore = {\n  toggleBookmark(contentId: string): boolean {\n    const db = load();\n    const next = { ...db.bookmarks };\n    const saved = !next[contentId];\n    if (saved) next[contentId] = new Date().toISOString();\n    else delete next[contentId];\n    save({ ...db, bookmarks: next });\n    return saved;\n  },\n\n  setInterests(interests: TopicId[]) {\n    save({ ...load(), interests });\n  },\n\n  setNickname(nickname: string) {\n    save({ ...load(), nickname: nickname.trim().slice(0, 24) });\n  },\n\n  addPost(input: { topic: CommunityTopic; title: string; body: string; anonymous: boolean; wantsExpert: boolean }): Post {\n    const db = load();\n    const post: Post = {\n      id: id(),\n      topic: input.topic,\n      title: input.title.trim(),\n      body: input.body.trim(),\n      author: input.anonymous || !db.nickname ? { name: \"Anonymous member\", anonymous: true } : { name: db.nickname, anonymous: false },\n      createdAt: new Date().toISOString(),\n      wantsExpert: input.wantsExpert,\n      mine: true,\n    };\n    save({ ...db, posts: [post, ...db.posts] });\n    return post;\n  },\n\n  deletePost(postId: string) {\n    const db = load();\n    save({ ...db, posts: db.posts.filter((p) => p.id !== postId), replies: db.replies.filter((r) => r.postId !== postId) });\n  },\n\n  addReply(postId: string, body: string, anonymous: boolean): Reply {\n    const db = load();\n    const reply: Reply = {\n      id: id(),\n      postId,\n      body: body.trim(),\n      author: anonymous || !db.nickname ? { name: \"Anonymous member\", anonymous: true } : { name: db.nickname, anonymous: false },\n      createdAt: new Date().toISOString(),\n      mine: true,\n    };\n    save({ ...db, replies: [...db.replies, reply] });\n    return reply;\n  },\n\n  deleteReply(replyId: string) {\n    const db = load();\n    save({ ...db, replies: db.replies.filter((r) => r.id !== replyId) });\n  },\n\n  react(targetId: string, kind: ReactionKind) {\n    const db = load();\n    save({ ...db, reactions: { ...db.reactions, [targetId]: toggleReaction(db.reactions[targetId], kind) } });\n  },\n\n  report(targetId: string, reason: string) {\n    const db = load();\n    save({ ...db, reports: { ...db.reports, [targetId]: { reason, at: new Date().toISOString() } } });\n  },\n\n  undoReport(targetId: string) {\n    const db = load();\n    const reports = { ...db.reports };\n    delete reports[targetId];\n    save({ ...db, reports });\n  },\n};\n"
};

for (const [path, content] of Object.entries(files)) {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, content);
  console.log("  wrote", path);
}
console.log("\nDone: " + Object.keys(files).length + " files created or updated.");
